    }

    // Lookahead: if the next item would fit exactly in the post-residual,
    // reward this placement (chain packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: exact match of next item into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
    }

    // Penalize dead space relative to mean residual
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
    }

    // Prefer filling nearly-full bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 0.6 * tightness * tightness * (bin_capacity as f64);

    // Perfect/near-perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 6.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_slack = post_residual - next_item_size;
        score -= 8.0 * (1.0 - (chain_slack as f64) / (bin_capacity as f64));
        if chain_slack == 0 {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving a residual too small for the next item (dead space risk).
        score += 4.0 * (1.0 - (post_residual as f64) / (next_item_size as f64)).max(0.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing bins would leave large unusable waste.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Opening a bin is penalized more when many bins are open and fits exist.
        score += 25.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
        // But relax the penalty late in the stream or when mean residuals are tiny (fragmented bins).
        score -= 20.0 * progress;
        score -= 15.0 * (1.0 - pressure);
        // If the item is large, a fresh bin is safer.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Mild global pressure: prefer bins with below-average residual (consolidate waste).
    let diff = (bin_residual as f64) - mean_residual;
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling: post_residual shaped by progress.
    // Early in the stream, tolerate larger residuals (favor filling existing bins
    // less aggressively later on, tighten packing as stream progresses).
    let shaping = 1.0 + 0.8 * progress * progress - 0.4 * progress * pr / cap;
    score *= shaping;

    // Quadratic penalty on wasted residual, amplified by progress (late items
    // should not leave large dead space).
    let waste = (pr / cap) * (pr / cap);
    score += 30.0 * progress * waste * cap * 0.01;

    // Cubic interaction: small residuals are excellent late, mildly good early.
    let small_fit = (1.0 - pr / cap).powi(3);
    score -= 10.0 * small_fit * (1.0 - progress);

    // Perfect fit reward, scaled by how tight the fit is.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 8.0 * (1.0 + progress);
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / cap) * (1.0 + progress);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; penalize leaving a residual that is too
        // small to be useful (dead space), more so late in the stream.
        score += 6.0 * progress * (pr / cap);
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin,
    // unless post_residual would be tiny and useless.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual > 0 && post_residual < 10 {
            score += 10.0 * (1.0 - progress);
        }
    }

    // New-bin candidate: prefer opening a new bin early (plenty of stream left
    // to fill it) or when the fit is poor; penalize opening bins late.
    if bin_residual == bin_capacity {
        let poor_fit = item_size as f64 / cap;
        score = 20.0 + 60.0 * (1.0 - progress) * (1.0 - poor_fit)
            - 10.0 * (1.0 - progress)
            + 40.0 * progress * (1.0 - poor_fit);
        // If no existing bin fits well, new bin is more attractive.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // If next item is large, a fresh bin is useful.
        if next_item_size > 50 {
            score -= 8.0;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * (open_bins_count as f64).sqrt();

    // Mean-residual coupling: if this bin's residual is far below mean (it is
    // nearly full), reward closing it out.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.3 * dev.max(0.0) * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small residue" classes (<=20) are near-perfectly packed; reward them.
    let residue_class = post_residual / 10; // 0..=10 harmonic classes
    let class_bonus: f64 = match residue_class {
        0 => 18.0, // post_residual == 0: perfect closure, strongly favored
        1 => 10.0, // 1..=10: dead space nearly unusable (min item is small)
        2 => 6.0,  // 11..=20
        3 => 3.0,  // 21..=30
        4 => 1.0,  // 31..=40
        5 | 6 => 0.0,
        _ => -1.0, // large leftover: bin was roomy anyway, less urgency
    };
    score -= class_bonus;

    // Integer-division threshold: can the NEXT item exactly fill post_residual?
    // Exact co-fill (post_residual == next_item_size) is a harmonic match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 14.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits here: keep this bin attractive proportional to tightness
        let tight = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - tight / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this leftover: penalize dead space creation
        score += 5.0;
    }

    // Modulo arithmetic on capacity fractions: leftover that is a clean
    // fraction of capacity (50, 25, 20, 10) is reusable by common item sizes.
    if post_residual == 50 || post_residual == 25 || post_residual == 20 || post_residual == 10 {
        score -= 4.0;
    }
    // Odd residues under 10 are dead weight for most streams.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance logic: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate (empty bin): make it moderately attractive only when
    // the item is large relative to capacity or open bins are already tight.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // prefer new bin for big items, or when mean residual is low (bins full)
        let new_bin_bias = 12.0 * item_frac + 8.0 * (1.0 - pressure) - 4.0 * progress;
        score += new_bin_bias;
        // never open a new bin when an exact-fit exists elsewhere
        if next_item_size > 0 && post_residual == next_item_size {
            score += 20.0;
        }
    }

    // Slight global preference for filling existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (bin_residual < bin_capacity) as u32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: residuals too small for the smallest possible item
    // (size 1) are never "unusable" per se, but tiny gaps (< ~15) are unlikely
    // to be filled later; penalize them super-linearly.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 15.0 {
        score += (15.0 - gap) * (15.0 - gap) * 2.0;
    }

    // Reward bins whose residual is "just above" the item (tight fit).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // If this bin is the ONLY fitting bin, strongly favor using it
    // (avoids opening a new bin unnecessarily).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when existing bins would leave bad gaps
    // or when open-bin pressure is low. Penalize new bins as open_bins_count grows.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
        // But if the next item could combine with the current one in a fresh bin,
        // give a discount to encourage pairing.
        if next_item_size > 0 && (item_size + next_item_size) <= bin_capacity {
            score -= 20.0;
        }
    } else {
        // Prefer bins whose residual is close to the mean (keep bin states uniform),
        // enabling better future packing.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.5;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 400.0;
    }
    // If next item fits within post residual, mild reward for chaining.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Late in the stream, consolidate: penalize opening new bins more strongly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins that end up (nearly) empty.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose leftover exactly accommodates the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // leftover can host next item; prefer tighter leftover (smaller slack)
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // leftover too small for next item -> dead space risk
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // prefer placements that leave less-than-average residual (denser packing).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, we should use it
    // rather than open a new bin (penalize alternatives implicitly by rewarding this).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a new bin wastes capacity; make it unattractive
    // unless existing bins would create huge dead space.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * (post_residual as f64);
        // early in the stream, allow new bins more freely
        if total_items > 0 {
            score -= 30.0 * (1.0 - step_index as f64 / total_items as f64);
        }
    }

    // Mild preference for filling larger bins first (smaller residual before placement).
    score += 0.1 * (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit flavor: reward tight fits (small post_residual already does this),
    // but amplify the preference for very tight fits.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += tight * tight * 20.0;

    // Lookahead: if the next item fits exactly in the post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item won't fit here; penalize slightly more when waste would be large
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item, use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 10.0;
        // More open bins => prefer reusing; raise new-bin penalty.
        score += (open_bins_count as f64) * 2.0;
        // If many bins can fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 8.0;
        }
        // Late in the stream, prefer closing out open bins rather than starting new ones.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 30.0;
        // If the mean residual is small (bins are nearly full), a new bin is more justified.
        score -= (mean_residual / (bin_capacity as f64)) * 15.0;
        // Perfect-fit item into a fresh bin (item = capacity) is great.
        if item_size == bin_capacity {
            score -= 100.0;
        }
    }

    // Slight preference for filling bins with larger residuals when many bins are open,
    // to consolidate items and free bins.
    score -= (bin_residual as f64) * 0.05;

    // Penalize leaving residuals that are so small no realistic item (>=1) can use them well:
    // tiny non-zero residuals are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual in [0,1]
    let r = post / cap;

    // Base: prefer tight fits (small post_residual)
    let mut score = post;

    // Non-linear polynomial coupling of residual with stream progress:
    // early on, tolerate larger residuals (waste is cheap); late, penalize heavily.
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * (r * r) * cap;

    // Smooth cubic term: mid-size residuals are penalized more as stream advances
    score += 8.0 * progress * r * r * r * cap;

    // Reward near-perfect fits (post_residual close to 0) with smooth quadratic discount
    let tightness = (1.0 - r).max(0.0);
    score -= 6.0 * tightness * tightness * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward (smooth)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (post - nx).abs();
        let fit_quality = 1.0 - gap.min(cap) / cap;
        score -= 10.0 * fit_quality * fit_quality;
    }

    // Slight preference for using already-open bins over opening new ones,
    // scaled by how full the bin already is (smooth coupling)
    let fill = 1.0 - r;
    score -= 2.0 * fill * fill * (open_bins_count as f64).ln().max(0.0);

    // Mild penalty if this bin's residual deviates from mean residual (balance pressure)
    score += 0.05 * (post - mean_residual).abs();

    // New-bin candidate: penalize slightly so we only open new bins on genuinely bad fits
    if bin_residual == bin_capacity {
        score += 12.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of 10, or large enough for typical items)
    // are more attractive; awkward remainders are penalized.
    let pr = post_residual;
    let class = pr % 10;
    // penalty grows with distance of post_residual from a multiple of 10
    let class_penalty = if class == 0 { 0.0 } else { (10 - class.min(10 - class)) as f64 * 0.6 };
    score += class_penalty;

    // Dead space: post_residual too small to ever fit a typical item (>= 10)
    if pr > 0 && pr < 10 {
        score += 25.0; // wasted sliver
    }

    // Reward tight fits (post_residual small but usable)
    if pr >= 1 && pr <= 15 {
        score -= 12.0;
    } else if pr <= 30 {
        score -= 5.0;
    }

    // Lookahead coupling: does post_residual still fit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // good: chain placement possible; reward proportionally
            score -= 8.0 * (next_item_size as f64 / 100.0);
        } else if next_item_size >= 10 && (pr as f64) >= (next_item_size as f64) * 0.5 {
            score += 4.0; // partial risk
        } else {
            score += 10.0; // next item likely can't use this bin
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // the item fits no open bin well. Penalize the empty bin normally,
    // but relax when many bins are open and mean residual is large (fragmentation).
    if bin_residual == bin_capacity {
        let mut nb = 18.0; // base cost of opening a new bin
        if open_bins_count == 0 {
            nb -= 18.0; // must open
        } else if fitting_bins_count == 0 {
            nb -= 40.0; // nothing fits: new bin is correct
        } else if fitting_bins_count == 1 {
            nb += 20.0; // one bin fits, prefer it
        }
        // if mean residual across open bins is tiny, reusing is cheap
        if mean_residual < 15.0 {
            nb += 8.0;
        }
        score += nb;
    }

    // Mild progression term: later in the stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins below mean residual (balance load)
    score += 0.05 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit even the
    // smallest item (1) are worthless; residuals below the typical small-item
    // threshold are heavily penalized as unusable gaps.
    let dead_threshold: f64 = 12.0;
    if (post_residual as f64) < dead_threshold {
        // Perfect fill / near-perfect fill gets a strong reward.
        score -= 30.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    } else {
        // Larger leftover gaps are mildly penalized proportional to their size,
        // but only if they are unlikely to be filled by the lookahead item.
        if (next_item_size as f64) > post_residual as f64 {
            score += 0.15 * ((next_item_size as f64) - post_residual as f64);
        }
    }

    // Reward tight fits: the smaller the post_residual relative to capacity,
    // the better the packing density.
    score -= 40.0 * (1.0 - (post_residual as f64) / bin_capacity as f64).powi(4);

    // Last-chance bonus: if this is the only bin that fits the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spawning new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure.
        score += 10.0 + 8.0 * open_pressure;
        // Slight reprieve late in the stream when consolidation is less valuable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    } else {
        score -= 2.0 * open_pressure;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor),
    // measured against the mean residual of open bins.
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * fit_gap;
    if (bin_residual as f64) < mean_residual {
