    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 0.5;
    }

    // Slight penalty for large leftover fragments (unusable small residuals).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Late in stream, prefer tighter fits even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Tightness reward: quadratic fill bonus
    let fill = 1.0 - post / cap;
    score -= 60.0 * fill * fill;

    // Dead-space penalty for small post residuals that no typical item can use
    if post > 0.0 && post < 10.0 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let waste_after = post - nxt;
            score -= 35.0 * (1.0 - waste_after / cap);
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += 8.0 * (nxt / cap);
        }
    } else {
        // last item: close bins aggressively
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins -> prefer consolidation into existing bins
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
    score -= 2.0 * pressure;

    // Time horizon: early stream -> be picky (penalize loose fits), late -> just fill
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 10.0 * (post / cap);
    score -= t * 15.0 * fill;

    // New-bin candidate: penalize opening unless item is large and no good fit exists
    if bin_residual == bin_capacity {
        let big_item = item / cap;
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 45.0 - 30.0 * big_item - 20.0 * desperation * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Early stream: tolerate large residuals; late stream: penalize them quadratically
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * norm_pr * norm_pr * cap;

    // Reward tight fits (small post_residual) with smooth inverse coupling
    score -= 20.0 / (1.0 + pr * pr);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize bins far from mean residual (fragmentation signal), smooth cubic
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev * dev.abs() / cap;

    // Lookahead coupling: favor bins whose post_residual can host next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 10.0 * progress;
    }

    // Many open bins: slight preference to consolidate into existing bins
    score += 0.1 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: make it moderately attractive only when no bin fits well
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover space by modulo 10
    let class = post_residual % 10;
    // Dead space penalty: residuals that cannot hold small items (1..9) are dead
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        // Reward residuals that are "harmonious" with capacity fractions
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        // Modulo-based dead-space penalty: residual mod 10 far from multiples
        // that align with typical item sizes (multiples of 5)
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        // Integer division thresholds: very small usable leftover is bad
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item can still fit; penalize large leftover less if reusable
            score -= 5.0;
        } else {
            // next item won't fit here; leftover likely wasted
            score += (post_residual as f64) * 0.3;
        }
        // Harmonic pairing: next_item_size class matches residual class
        if next_item_size % 10 == post_residual % 10 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: make it moderately attractive only when current bins
    // would be badly fragmented, otherwise keep it unattractive
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 300.0;
        // cheaper to open a new bin when many bins are open and mean residual is low
        score -= (open_bins_count as f64) * 3.0;
        // early in stream, opening bins is fine
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 50.0;
        // if next item is large, a fresh bin is valuable
        if next_item_size >= bin_capacity / 2 {
            score -= 80.0;
        }
    }

    // Prefer tighter bins overall: penalize bins with much more residual than mean
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.4;

    // Slight preference for filling fuller bins (smaller residual) as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_capacity - bin_residual) as f64 * 0.1 * (0.5 + progress);

    score
}

