pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = (bin_capacity - bin_residual) as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Near-perfect fit: small leftover that is hard to reuse
    if post_residual > 0 && post_residual < 5 {
        score -= 120.0 - post_residual as f64 * 10.0;
    }

    // 2-step lookahead: exact match of next item into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 + slack * 0.5;
        // Extra reward when the leftover after next item is also tiny
        if slack < 5.0 {
            score -= 60.0;
        }
    }

    // Penalize dead space relative to mean residual
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits.
    // Poor fit = item leaves a large unusable gap in the chosen open bin.
    if bin_residual == bin_capacity {
        let best_gap = if fitting_bins_count > 0 {
            (post_residual as f64).min(60.0)
        } else {
            0.0
        };
        // Open a new bin only when the item would waste a lot of space
        // in every open bin, or late in the stream with many bins open.
        if post_residual as f64 > 40.0 + mean_residual * 0.5 {
            score -= 25.0;
        } else {
            score += 40.0 + progress * 30.0;
        }
        let _ = best_gap;
    }

    // Prefer filling nearly-full bins (stronger weight with progress)
    score -= fill * (0.3 + 0.15 * progress);

    // Slight preference for bins with fewer competitors (consolidation)
    if fitting_bins_count > 3 {
        score += (fitting_bins_count as f64 - 3.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fit reward (scaled with progress: perfect fits matter more late)
    if post_residual == 0 {
