    // 2-step lookahead: exact match of next item into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
    }

    // 2-step lookahead: current item + next item both fit post_residual
    if next_item_size > 0 && item_size + next_item_size <= bin_residual {
        score -= 120.0;
    }

    // Penalize dead space relative to mean residual (adaptive weight)
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

