pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward (strengthened)
    if post_residual == 0 {
        score -= 700.0;
    }

    // Harmonic class of post_residual
    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; leftover likely wasted
        score += (post_residual as f64) * 0.3;
    }

    // Two-item lookahead: if next item fits and the one after would too, reward more
    let next_next_fit = next_item_size > 0
        && next_item_size <= post_residual
        && post_residual >= next_item_size + (next_item_size / 2).max(1);
    if next_next_fit {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 + progress * 30.0;
        // slight relief when many bins are open with low mean residual
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        // a fresh bin is valuable if next item is large
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        // relief if mean residual is high (open bins are all loose)
        if mean_residual > bin_capacity as f64 * 0.35 {
            score -= 15.0;
        }
        // NEW: open a fresh bin when no existing bin can hold the next item too
        if next_item_size > post_residual && next_item_size > bin_residual {
            score -= 25.0;
        }
    }

    // Prefer tighter bins overall: penalize bins with much more residual than mean
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins, stronger as stream progresses
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    // Small item into large residual: discourage wasting big space on tiny items
    if item_size <= 10 && post_residual > bin_capacity / 2 {
        score += 20.0;
    }

    // NEW: reward leaving a residual that matches a common harmonic slot for future items
    if post_residual >= 20 && post_residual <= 50 {
        score -= 8.0;
    }

    score
}

