            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
        }
    }

    // Scarcity-aware new-bin suppression — when several open bins
    // already fit, opening a fresh bin should cost more unless the post
    // residual is small enough to be reliably reusable by upcoming items.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let reusable = post_residual as f64 >= mean_residual * 0.8;
        if !reusable {
            score += 8.0 + progress * 12.0;
        } else if post_residual as f64 > mean_residual * 1.6 {
            score += 4.0;
        }
    }

    // Adaptive fragmentation band — 13..=20 late in the stream.
    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Perfect-chain depth bonus — post residual equals next item exactly.
    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        let scarcity = (3 - fitting_bins_count.min(3)) as f64;
        score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
    }

    // Mean-residual harmonic reuse
    if post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev < 2.0 {
                score -= (2.0 - dev) * (1.0 + progress);
            }
        }
    }

    // Endgame consolidation — final 10% of stream.
    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    // MUTATION: demand-proportional residual valuation — value a residual
    // by how well it covers the *expected* upcoming item demand rather than
    // only the immediate next item. Estimate the average remaining item size
    // from capacity and mean residual, then reward residuals that sit in the
    // "sweet spot" (>= expected size, <= 2x expected size) since those are
    // most likely to be consumed exactly by future items. This refines the
    // dead-space ratio weakness by shifting placements toward residuals
    // that the stream can actually reabsorb.
    if post_residual > 0 && progress > 0.15 {
        let expected = (bin_capacity as f64 - mean_residual).max(1.0).min(60.0);
        let pr = post_residual as f64;
        if pr >= expected * 0.9 && pr <= expected * 2.0 {
            // Sweet-spot residual: mildly reward, stronger mid-stream.
            score -= (1.0 + 4.0 * progress) * (1.0 - (pr - expected * 0.9) / (expected * 1.1)).max(0.0);
        } else if pr < expected * 0.9 && pr > 0 && next_item_size == 0 {
            // Unusable sliver with no chain available: penalize.
            score += (expected * 0.9 - pr) * 0.12 * (0.5 + progress);
        }
    }

    // MUTATION: residual decay pressure — a residual loses value as the
    // stream progresses if it stays unclaimed; approximate this by charging
    // an "interest" on residuals that exceed what the remaining demand can
    // absorb, sharpening the existing waste-floor pressure for open bins
    // (not just new-bin candidates).
    if bin_residual != bin_capacity && progress > 0.75 {
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let absorbable = mean_residual * remaining.max(1.0);
        if post_residual as f64 > absorbable && post_residual > 0 {
            score += ((post_residual as f64 - absorbable) * 0.08 * progress).min(30.0);
        }
    }

    score
}

