    // 13..=20 band late in the stream, where residuals rarely get reused
    // because upcoming items skew smaller. Only apply when no chain exists
    // and several bins already fit, so genuine two-item anchors stay safe.
    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
