    // exceeds the projected demand wastes that space; conversely, when the
    // demand is high relative to open capacity, a fresh bin becomes cheap.
    if bin_residual == bin_capacity {
        let remaining = total_items.saturating_sub(step_index) as f64;
        let demand = mean_residual * remaining;
        let open_space = open_bins_count as f64 * mean_residual;
        let deficit = (demand - open_space).max(0.0);
        if deficit > bin_capacity as f64 {
            // Stream genuinely needs more capacity: soften the new-bin cost.
            score -= (deficit / bin_capacity.max(1) as f64).min(3.0) * 6.0;
        } else {
            // Surplus capacity: scale penalty with how unusable the leftover is.
            let unusable = post_residual as f64 / bin_capacity.max(1) as f64;
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
