            } else if progress > 0.75 && unusable > 0.25 {
                score += (unusable - 0.25) * 60.0 * progress;
            }
        }
    }

    // MUTATION: tight-pair anchoring — when the item nearly fills the bin
    // (residual <= 4) and the next item can chain into it, this placement
    // is a near-closure; reward it more strongly as bins become scarce.
    if post_residual <= 4 && next_item_size > 0 && post_residual >= next_item_size.min(post_residual) && next_item_size <= post_residual {
        score -= 8.0 + (fitting_bins_count.min(4)) as f64 * 2.0;
    }

    // MUTATION: large-item hoarding guard — for big items (>60), prefer
    // bins whose post residual stays below the typical next-item scale so
    // the leftover doesn't strand as dead space; also discourage opening a
    // fresh bin for a large item when any open bin has >= item_size room.
    if item_size > 60 && bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 14.0 + progress * 10.0;
    }

    score
}

