    // the next item exactly, the bin closes with zero waste in two steps.
    // Sharpen this beyond the generic lookahead by scaling with scarcity of
    // fitting bins.
    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        let scarcity = (3 - fitting_bins_count.min(3)) as f64;
        score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
