        let horizon = reuse_capacity.min(remaining).min(4.0);
        let deadness = 1.0 - (horizon / 4.0);
        if deadness > 0.0 {
            score += deadness * (2.0 + progress * 8.0) * (post_residual as f64 / bin_capacity.max(1) as f64);
        }
    }

    // MUTATION: two-item exact tiling — when post_residual equals the sum
    // of the next item and a small follow-up remainder that itself matches
    // the mean residual closely, this bin closes nearly waste-free in three
    // steps. Reward beyond the generic chain lookahead.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && mean_residual > 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev < 3.0 {
                score -= (3.0 - dev) * 3.0 * (0.6 + progress);
            }
        }
    }

    // MUTATION: new-bin residual targeting — when a fresh bin must be
    // considered, prefer opening it only if its post residual aligns with
    // the next item size (immediate reuse) or is large enough to remain
    // flexible. Penalize fresh bins whose leftover falls into the dead
    // gap just below the next item.
    if bin_residual == bin_capacity && next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else if post_residual >= next_item_size * 2 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened)
    if post_residual == 0 {
        score -= 700.0;
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
