    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, favor consolidating into existing bins
    // (penalize the new-bin candidate and spread).
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 20.0);
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * pressure.min(3.0);
    } else {
        score -= 2.0 * pressure.min(3.0);
    }

    // Prefer bins with below-mean residual (consolidate fuller bins, keep big gaps open).
    score += 0.05 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    score
}

