        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
    }

    // Fragmentation guard — residuals in the awkward 6..=12 band are
    // the leading source of dead space late in the stream. Penalize leaving
    // them behind unless a perfect chain exists, scaled by stream progress.
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
        }
    }

    // Scarcity-aware new-bin suppression — when several open bins
    // already fit, opening a fresh bin should cost more unless the post
    // residual is small enough to be reliably reusable by upcoming items.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let reusable = post_residual as f64 >= mean_residual * 0.8;
        if !reusable {
            score += 8.0 + progress * 12.0;
        } else if post_residual as f64 > mean_residual * 1.6 {
            score += 4.0;
        }
    }

    // MUTATION: adaptive fragmentation band — extend the guard to the
    // 13..=20 band late in the stream, where residuals rarely get reused
    // because upcoming items skew smaller. Only apply when no chain exists
    // and several bins already fit, so genuine two-item anchors stay safe.
    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // MUTATION: perfect-chain depth bonus — when the post residual equals
    // the next item exactly, the bin closes with zero waste in two steps.
    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        let scarcity = (3 - fitting_bins_count.min(3)) as f64;
        score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
    }

    // MUTATION: mean-residual harmonic reuse — reward residuals close to
    // multiples of the mean residual, since the stream tends to produce
    // items that tile such spaces well. Mild, progress-scaled.
    if post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev < 2.0 {
                score -= (2.0 - dev) * (1.0 + progress);
            }
        }
    }

    // MUTATION: endgame consolidation — in the final 10% of the stream,
    // every open bin's leftover is pure waste. Push hard toward exact fits
    // and against any placement leaving more than 25 dead space.
    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    // MUTATION (gen 12): fill-ratio refinement of the dead-space term.
    // The base dead-space penalty above scales linearly with post_residual,
    // but a large residual in a nearly-empty bin is cheap to fix, while the
    // same residual in a nearly-full bin is unrecoverable waste. Reweight
    // the penalty by the consumed fraction of the bin.
    if post_residual > 0 {
        let consumed_frac = (bin_capacity - bin_residual) as f64 / bin_capacity.max(1) as f64;
        if consumed_frac > 0.6 {
            score += post_residual as f64 * (consumed_frac - 0.6) * 0.8;
        }
    }

    // MUTATION (gen 12): pair-compatibility gate for new bins. Opening a
    // fresh bin is only attractive if the leftover after placing the item
    // can plausibly host the next item too. When post_residual is smaller
    // than the next item AND the next item is large relative to capacity,
    // a new bin just strands two fragments — penalize hard.
    if bin_residual == bin_capacity && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let big_next = next_item_size as f64 > bin_capacity as f64 * 0.35;
        if big_next {
            score += 25.0 + progress * 20.0;
        }
    }

    // MUTATION (gen 12): triple-fit lookahead. When the post residual can
    // absorb the next item AND the remainder still exceeds the item after
    // that (approximated by next_item_size again), the bin supports a
    // three-item chain — reward this deep compaction, weighted by how
    // few alternatives exist.
    if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual > 0 {
        let scarcity = (4 - fitting_bins_count.min(4)) as f64;
        score -= (6.0 + scarcity * 4.0) * (0.5 + progress);
    }

    // MUTATION (gen 12): residual variance sharpening. When the stream's
    // residual spread is tight (small sigma proxy via mean_residual),
    // residuals near the mean are highly reusable; when spread is wide,
    // only very small residuals are safe. Adjust the reuse threshold by
    // the mean-to-capacity ratio.
    let mean_frac = mean_residual / bin_capacity.max(1) as f64;
    if post_residual > 0 && post_residual as f64 <= mean_residual * (0.9 + mean_frac) {
        score -= 4.0 + progress * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream processed
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward high fill ratio of the bin
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small unusable dead space (fragmentation), but tolerate it late
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - t);
    }

    // Lookahead: bonus if next item can fit in the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else {
            // Dead-end risk: post residual too small for next item
            score += 6.0 * (1.0 - t);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer opening a new bin when the item is large
    // and existing fits are poor, or when open-bin residuals are already fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; cheaper late in the stream
        score += 25.0 * (1.0 - 0.4 * t);
        // Large items deserve a fresh bin (avoid wasting big residual)
        score -= 0.15 * item_size as f64;
        // If many bins can fit the item, discourage opening a new one
        if fitting_bins_count > 1 {
            score += 10.0;
        }
        // If mean residual is large and fragmented, a new bin is fine
        if mean_residual > 30.0 {
            score -= 5.0;
        }
        // Lookahead synergy: fresh bin leaves room for the next item too
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward keeping residuals close to mean (balance)
        score += 0.1 * ((post_residual as f64 - mean_residual).abs());
        // Discourage placing small items into bins with large residual early on
        if item_size < 30 && post_residual > 50 && t < 0.5 {
            score += 5.0;
        }
        // Reward using a nearly-full bin (waste-minimization)
        if post_residual <= 15 {
            score -= 10.0;
        }
    }

    // Mild penalty for accumulating many open bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
