        let scarcity = (3 - fitting_bins_count.min(3)) as f64;
        score -= 12.0 + scarcity * 6.0 * (0.5 + progress_f(step_index, total_items));
    }

    // Harmonic reward: residual equal to common capacity fractions
    if post_residual == bin_capacity / 2 {
        score -= 30.0;
    } else if post_residual == bin_capacity / 3 {
        score -= 20.0;
    }

    // Tiny residual sharpening
    if post_residual == 1 || post_residual == 2 || post_residual == 3 {
        score -= 25.0;
    }

    let progress = step_index as f64 / total_items.max(1) as f64;

    // Dead-space penalty relative to mean residual, stronger later in stream
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * (0.5 + progress);
