    let post_norm = post / cap;

    // Base: prefer small post_residual (tight fit), smoothly scaled
    let mut score = post_norm;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, keep residuals flexible; late in the stream, chase tight fits.
    let flex = post_norm * (1.0 - post_norm); // peaks at half-full bins
    score += 2.5 * flex * (1.0 - progress).powi(2);
    score -= 1.5 * post_norm * post_norm * progress;

    // Dead-space penalty: tiny residuals are wasted, penalize quadratically
    if post_norm > 0.0 && post_norm < 0.1 {
        score += 0.8 * (0.1 - post_norm) * (0.1 - post_norm) * 100.0 / 10.0;
    }

    // Exact fit reward (smooth cubic proximity to zero residual)
    score -= 2.0 * (1.0 - post_norm).powi(3) * (post_norm <= 1.0) as i32 as f64 * 0.0;
    score -= 2.0 * (-post_norm).exp();

    // Lookahead coupling: if next item fits the post residual, reward
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= post;
        if next_fits {
            score -= 1.2 * (1.0 - post_norm) * (0.5 + progress);
        } else {
            // next item won't fit: penalize leaving large unusable residue
            score += 0.6 * post_norm * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0;
    } else if fitting_bins_count > 1 {
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // Mild pressure toward consolidating into fewer bins
    score += 0.01 * open_bins_count as f64 * post_norm;

    // Mean residual alignment: prefer bins near the mean residual (balanced packing)
    let mean_norm = mean_residual / cap;
    score += 0.4 * (post_norm - mean_norm) * (post_norm - mean_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 600.0;
    }

    let progress = step_index as f64 / total_items.max(1) as f64;

    // Lookahead: exact match of next item into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 220.0 + (post_residual - next_item_size) as f64 * 0.5;
        let after = post_residual - next_item_size;
        if after <= 5 {
            score -= 18.0 + (5 - after) as f64 * 2.0;
        }
        // Perfect-chain depth bonus: residual exactly equals next item
        if after == 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        // Tri-item chain probe: remainder still absorbent in expectation
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
    } else if next_item_size > post_residual {
        if post_residual < next_item_size / 2 {
            score += 40.0;
        }
        if next_item_size > 0 && post_residual > 0 && fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Harmonic reward: residual equal to common capacity fractions
    if post_residual == bin_capacity / 2 {
        score -= 30.0;
    } else if post_residual == bin_capacity / 3 {
        score -= 20.0;
    }

    // Tiny residual sharpening
    if post_residual == 1 || post_residual == 2 || post_residual == 3 {
        score -= 25.0;
        if progress > 0.95 {
            score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
        }
    }

    // Dead-space penalty relative to mean residual, stronger later in stream
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * (0.5 + progress);
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if post_residual > 0 && res_dev < mean_residual * 0.15 {
        score -= 10.0 + progress * 10.0;
    }

    // Mean-residual harmonic reuse
    if post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev < 2.0 {
                score -= (2.0 - dev) * (1.0 + progress);
            }
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 180.0;
    }

    // Pairing with next item when several bins fit
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Scarcity sharpening: near-exact chain fit when few bins fit
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let d = post_residual - next_item_size;
        if d <= 2 {
            score -= 10.0;
        }
    }

    // New-bin decision: dead-space-aware modulation
    if bin_residual == bin_capacity {
        let waste_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        let gap_dead = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        if gap_dead {
            let dead_ratio = (next_item_size - post_residual) as f64 / bin_capacity.max(1) as f64;
            score += (40.0 + progress * 30.0) * (1.0 - dead_ratio * 2.0).max(0.0);
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score += 40.0 + progress * 30.0;
        } else {
            score += (40.0 + progress * 30.0) * (1.0 - waste_frac * 1.5).max(0.0);
        }
        if next_item_size >= bin_capacity / 2 && next_item_size > mean_residual as u32 {
            score -= 60.0;
        }
        if open_bins_count > 20 && mean_residual < bin_capacity as f64 / 10.0 {
            score -= 25.0;
        }

        // MUTATION: demand-aware new-bin gate — full-stream coupling between
        // remaining item demand and the fresh bin's post residual.
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        // Large open-bin pool: fresh bin must promise a tight residual
        if open_bins_count > 6 && post_f > bin_capacity as f64 * 0.5 {
            score += (post_f - bin_capacity as f64 * 0.5) * 0.25;
        }
        // Scarcity-aware new-bin suppression
        if fitting_bins_count > 0 {
            let reusable = post_f >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_f > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        // Late-stream opening bonus when mean residual is high
        if progress > 0.5 && open_bins_count > 4 && mean_residual > (bin_capacity as f64) * 0.4 {
            score -= 20.0 * (progress - 0.5);
        }
    }

    // Fragmentation guard — awkward 6..=12 band
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
        }
    }

    // Adaptive fragmentation band — 13..=20 late in the stream
    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Endgame consolidation
    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    // Prefer filling nearly-full bins, stronger as stream progresses
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.7 + 0.6 * progress);

    // Tie-break: prefer bins whose residual is close to the item size
    if bin_residual >= item_size {
        score -= (bin_residual - item_size) as f64 * 0.05;
    }

    // Small-item late-stream steering
    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Balanced split reward for exact two-item splits
    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction bands.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap; // 0..1

    // Perfect fit reward: strong subtraction.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Integer-division thresholds on post_residual (harmonic classes of C/2, C/4, C/8)
        let class = post_residual / (bin_capacity / 8); // 0..=8 coarse class
        // Prefer small classes (tight fills) non-linearly
        score += (class as f64).powi(2) * 1.5;

        // Dead-space penalty: residual below smallest plausible item (1) is fine,
        // but residual in awkward mid-band (just above small items) is wasteful.
        if post_residual < 4 {
            score -= 10.0; // near-perfect, nearly dead but tiny
        } else if post_residual <= 10 {
            score += 5.0; // awkward small gap
        }

        // Fractional coupling: penalize leaving more than half the bin free
        // unless the next item can use it.
        if frac > 0.5 {
            if next_item_size > 0 && (next_item_size as u32) <= post_residual {
                score -= 8.0; // lookahead fits, keep room
            } else {
                score += 6.0 * frac; // stranded space
            }
        }
    }

    // Last-chance bonus: only one fitting bin; avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Opening fresh is penalized mildly; worse late in stream or with many bins.
        score += 12.0 + 0.05 * open_bins_count as f64;
        // But if next item is large and current fit is bad, new bin more attractive.
        if next_item_size > 0 && (next_item_size as u32) > (bin_capacity as u32) / 2 {
            score -= 5.0;
        }
        // Early stream: fresh bins cheap.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 6.0;
        }
    }

    // Mean-residual coupling: prefer bins deviating below mean (tighten spread).
    score += (mean_residual - post_f).abs() * 0.1 - (mean_residual - post_f).max(0.0) * 0.3;

    score
}

