        let scarcity = (3 - fitting_bins_count.min(3)) as f64;
        score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
    }

    // Mean-residual harmonic reuse.
    if post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev < 2.0 {
                score -= (2.0 - dev) * (1.0 + progress);
            }
        }
    }

    // Endgame consolidation — final 10% of the stream.
    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    // Demand-aware new-bin gate — full-stream coupling between remaining
    // item demand and the fresh bin's post residual. Early in the stream
    // there is enough future demand to fill any residual, so new bins are
    // cheap; as remaining demand shrinks below the residual, the cost of
    // stranding that space rises super-linearly. Refined: gate threshold
    // now tracks progress so the gate tightens smoothly, and the pool-size
    // check uses fitting_bins_count to distinguish "several bins fit" from
    // "no bin fits" — a fresh bin is cheap only when nothing else fits.
    if bin_residual == bin_capacity {
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        let gate = demand * (0.35 - 0.15 * progress).max(0.15);
        if post_f > gate {
            let excess = post_f - gate;
            score += excess * (0.3 + progress * 1.4);
        }
        if fitting_bins_count > 0 && open_bins_count > 6 && post_f > bin_capacity as f64 * 0.5 {
            score += (post_f - bin_capacity as f64 * 0.5) * 0.25;
        }
    }

    // Tri-item chain probe — reward placements whose residual can absorb
    // the next item and still exceed the item after that in expectation.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
    }

    // Sharpened endgame exact-fit bonus — in the last 5%, residuals of
    // 1..=4 are near-certain closures; deepen proportionally to the end.
    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    // MUTATION: gap-bridging check — when the current residual is just
    // below the next item size, prefer placements that leave a residual
    // exactly equal to the *sum* of plausible small-item pairs, i.e.
    // reward residuals in the [mean_residual, 2*mean_residual] window
    // that no existing fragmentation band covers, since those are the
    // residuals most likely to be exactly consumed by two future items.
    if post_residual > 0 && bin_residual != bin_capacity {
        let mr = mean_residual.max(1.0);
        if post_residual as f64 >= mr && (post_residual as f64) <= 2.0 * mr {
            score -= 8.0 * (1.0 - progress * 0.5);
        }
    }

    // MUTATION: stranded-space sweep — a residual that cannot hold the
    // next item and exceeds the mean residual by more than half capacity
    // fraction is dead weight; penalize it harder as open bins grow,
    // pushing the heuristic toward bins whose space stays usable.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let over = post_residual as f64 - mean_residual;
        if over > 0.0 && open_bins_count > 3 {
            score += over * 0.2 * (open_bins_count as f64).min(10.0) / 10.0;
        }
    }

    score
}

