        let demand = mean_residual * remaining * 0.1;
        if post_residual as f64 > demand && progress > 0.6 {
            score += (post_residual as f64 - demand) * 0.15 * progress;
        }
    }

    // Near-exact fit sharpening — placements that leave residual
    // within 2 of the next item size are prime chain candidates.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let d = post_residual - next_item_size;
        if d <= 2 {
            score -= 10.0;
        }
    }

    // Two-item lookahead — if post_residual can absorb the next item AND
    // the remainder is still larger than half the mean residual, deepen
    // the chain reward proportionally.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
    }

    // Fragmentation guard — residuals in the awkward 6..=12 band are
    // the leading source of dead space late in the stream. Penalize leaving
    // them behind unless a perfect chain exists, scaled by stream progress.
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
        }
    }

    // Scarcity-aware new-bin suppression — when several open bins
    // already fit, opening a fresh bin should cost more unless the post
    // residual is small enough to be reliably reusable by upcoming items.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let reusable = post_residual as f64 >= mean_residual * 0.8;
        if !reusable {
            score += 8.0 + progress * 12.0;
        } else if post_residual as f64 > mean_residual * 1.6 {
            score += 4.0;
        }
    }

    // Adaptive fragmentation band — 13..=20 late in the stream.
    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Perfect-chain depth bonus — post residual equals next item exactly.
    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        let scarcity = (3 - fitting_bins_count.min(3)) as f64;
        score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
    }

    // Mean-residual harmonic reuse.
    if post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev < 2.0 {
                score -= (2.0 - dev) * (1.0 + progress);
            }
        }
    }

    // Endgame consolidation — final 10% of the stream.
    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    // Demand-aware new-bin gate — full-stream coupling between remaining
    // item demand and the fresh bin's post residual. Early in the stream
    // there is enough future demand to fill any residual, so new bins are
    // cheap; as remaining demand shrinks below the residual, the cost of
    // stranding that space rises super-linearly.
    if bin_residual == bin_capacity {
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        // When open-bin pool is large, a fresh bin must promise a tight
        // residual to justify its existence.
        if open_bins_count > 6 && post_f > bin_capacity as f64 * 0.5 {
            score += (post_f - bin_capacity as f64 * 0.5) * 0.25;
        }
    }

    // Tri-item chain probe — reward placements whose residual
    // can absorb the next item and still exceed the item after that in
    // expectation (approximated by mean residual), extending lookahead
    // depth beyond two steps for medium residuals.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
    }

    // Sharpened endgame exact-fit bonus — in the last 5%,
    // residuals of 1..=4 are near-certain closures; deepen the existing
    // tight-fit reward proportionally to how close to the end we are.
    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    // MUTATION: complement-pairing probe — a placement is especially
    // valuable when its post residual is the exact complement of the next
    // item against the mean-residual quantum, i.e. post_residual plus
    // next_item_size lands on a harmonic multiple of mean_residual. Such
    // residuals are primed for two-step closure and deserve a deeper
    // reward than the generic chain bonus, especially mid-stream where
    // most dead space is generated.
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    // MUTATION: dead-space floor sharpening — residuals strictly between
    // the next item and next_item + 3 are "almost-chain" traps: the next
    // item fits but leaves a sliver too small for anything. Penalize them
    // proportionally to stream progress so mid/late stream favors either
    // exact chains or clearly reusable residuals.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
    }

    // MUTATION: scarcity-weighted perfect fit — when only one or two bins
    // fit, a zero post residual is nearly free capacity; deepen the base
    // perfect-fit reward under scarcity to force closure of tight bins
    // before opening new ones.
    if post_residual == 0 && fitting_bins_count <= 2 {
        score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
    }

    // MUTATION (gen 15): residual-orbit targeting — residuals within a
    // tight window around the mean residual are the most reliably reusable
    // by future items of unknown size; deepen the existing entropy-coupling
    // reward into a graded bonus proportional to closeness, and couple it
    // to the open-bin pool: with many open bins, reusable residuals are
    // worth more because future demand can be routed there instead of
    // opening fresh capacity.
    if post_residual > 0 {
        let orbit = (post_residual as f64 - mean_residual).abs() / mean_residual.max(1.0);
        if orbit < 0.25 {
            score -= (0.25 - orbit) * 40.0 * (0.6 + 0.4 * (open_bins_count.min(12) as f64 / 12.0));
        }
    }

    // MUTATION (gen 15): dead-slot arbitration — when the next item cannot
    // fit the post residual and the shortfall is small relative to the
    // mean residual, the leftover space is a "dead slot" only if no other
    // open bin can absorb the next item. Weight the penalty by fitting
    // scarcity: with many fitting bins the next item has alternatives, so
    // the stranded residual is cheaper; with few, it is expensive.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let shortfall = (next_item_size - post_residual) as f64;
        let scarcity = (4 - fitting_bins_count.min(4)) as f64 / 4.0;
        if shortfall < mean_residual * 0.6 {
            score += shortfall * (0.5 + progress) * (0.5 + scarcity);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.16;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: exact match of next item into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
    }

    // Dead-space penalty relative to mean residual, scaled by progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let waste_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        let gap_dead = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        if gap_dead {
            let dead_ratio = (next_item_size - post_residual) as f64 / bin_capacity.max(1) as f64;
            score += (40.0 + progress * 30.0) * (1.0 - dead_ratio * 2.0).max(0.0);
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score += 40.0 + progress * 30.0;
        } else {
            score += (40.0 + progress * 30.0) * (1.0 - waste_frac * 1.5).max(0.0);
        }
        if progress > 0.5 && open_bins_count > 4 && mean_residual > (bin_capacity as f64) * 0.4 {
            score -= 20.0 * (progress - 0.5);
        }
    }

    // Prefer filling nearly-full bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // Small-item late-stream bonus
    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Tight-fit refinement — small residual rewards
    if post_residual == 1 || post_residual == 2 || post_residual == 3 {
        score -= 25.0;
    }

    // Penalty for residual just below next item size with multiple options
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count > 1 {
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Pairing with next item when several bins fit
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    // Balanced split reward
    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    // Chain-lookahead — reward residuals that can absorb the next
    // item AND still leave a small (<=5) usable remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after <= 5 {
            score -= 18.0 + (5 - after) as f64 * 2.0;
        }
    }

    // Waste-floor pressure — when the stream is nearly done, the
    // marginal cost of opening a bin that will be underfilled rises sharply.
    if bin_residual == bin_capacity {
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining * 0.1;
        if post_residual as f64 > demand && progress > 0.6 {
            score += (post_residual as f64 - demand) * 0.15 * progress;
        }
    }

    // Near-exact fit sharpening — placements that leave residual
    // within 2 of the next item size are prime chain candidates.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let d = post_residual - next_item_size;
        if d <= 2 {
            score -= 10.0;
        }
    }

    // Two-item lookahead — if post_residual can absorb the next item AND
    // the remainder is still larger than half the mean residual, deepen
    // the chain reward proportionally.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
    }

    // Fragmentation guard — residuals in the awkward 6..=12 band are
    // the leading source of dead space late in the stream. Penalize leaving
    // them behind unless a perfect chain exists, scaled by stream progress.
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
        }
    }

    // Scarcity-aware new-bin suppression — when several open bins
    // already fit, opening a fresh bin should cost more unless the post
    // residual is small enough to be reliably reusable by upcoming items.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let reusable = post_residual as f64 >= mean_residual * 0.8;
        if !reusable {
            score += 8.0 + progress * 12.0;
        } else if post_residual as f64 > mean_residual * 1.6 {
            score += 4.0;
        }
    }

    // Adaptive fragmentation band — 13..=20 late in the stream.
    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Perfect-chain depth bonus — post residual equals next item exactly.
    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        let scarcity = (3 - fitting_bins_count.min(3)) as f64;
        score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
    }

    // Mean-residual harmonic reuse.
    if post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev < 2.0 {
                score -= (2.0 - dev) * (1.0 + progress);
            }
        }
    }

    // Endgame consolidation — final 10% of the stream.
    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    // Demand-aware new-bin gate — full-stream coupling between remaining
    // item demand and the fresh bin's post residual.
    if bin_residual == bin_capacity {
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > bin_capacity as f64 * 0.5 {
            score += (post_f - bin_capacity as f64 * 0.5) * 0.25;
        }
    }

    // Tri-item chain probe
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
    }

    // Sharpened endgame exact-fit bonus
    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    // Dead-space floor sharpening
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
    }

    // Scarcity-weighted perfect fit
    if post_residual == 0 && fitting_bins_count <= 2 {
        score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
    }

    // MUTATION: residual-quota targeting — estimate the ideal per-bin
    // leftover as the running mean of post residuals implied by demand,
    // and reward placements whose post residual lands within a narrow
    // "harvestable" window around the expected next item size. This
    // directly attacks dead space by steering residuals toward sizes
    // that the stream is statistically likely to consume.
    if post_residual > 0 && next_item_size > 0 {
        let window_lo = (next_item_size as f64 * 0.6).max(1.0);
        let window_hi = next_item_size as f64 * 1.8 + mean_residual * 0.5;
        let pf = post_residual as f64;
        if pf >= window_lo && pf <= window_hi {
            let center = next_item_size as f64 + mean_residual * 0.3;
            let closeness = 1.0 - ((pf - center).abs() / (window_hi - window_lo).max(1.0));
            score -= closeness * 14.0 * (0.4 + progress * 0.8);
        }
    }

    // MUTATION: overflow-avoidance tilt — when the current bin barely
    // fits the item (bin_residual close to item_size), the placement is
    // "free" capacity usage; reward it more strongly mid-stream to keep
    // bins packed to the brim before any new-bin consideration.
    let tightness = bin_residual.saturating_sub(item_size);
    if bin_residual >= item_size && tightness <= 6 && bin_residual != bin_capacity {
        score -= (7.0 - tightness as f64) * 5.0 * (0.5 + progress);
    }

    // MUTATION: large-item reservation — when the next item is large
    // (>= 60% of capacity), avoid leaving residuals that can neither
    // hold it nor be combined; instead prefer placements that empty a
    // bin entirely (post_residual small) so the large item has a clean
    // target. Penalize mid-range residuals under this regime.
    if next_item_size as f64 >= bin_capacity as f64 * 0.6 && post_residual > 8 && post_residual < next_item_size {
        score += 12.0 + progress * 10.0;
    }

    // MUTATION: bin-count pressure valve — when the open-bin pool grows
    // large relative to remaining items, consolidation pressure should
    // dominate: prefer filling existing bins over opening new ones even
    // at the cost of slightly worse residuals.
    if open_bins_count as f64 > (total_items.saturating_sub(step_index)) as f64 * 0.5 && open_bins_count > 8 {
        if bin_residual == bin_capacity {
            score += 25.0;
        } else {
            score -= 8.0;
        }
    }

    score
}

