    } else if post_residual == bin_capacity / 3 {
        score -= 22.0;
    } else if post_residual == bin_capacity / 4 {
        score -= 12.0;
    }

    // Tiny residual rewards
    if post_residual == 1 || post_residual == 2 || post_residual == 3 {
        score -= 25.0;
    }

    // Dead-space penalty relative to mean residual, stronger later
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * (0.5 + progress);
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    // Mean-residual harmonic reuse
    if post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev < 2.0 {
                score -= (2.0 - dev) * (1.0 + progress);
            }
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 190.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let waste_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        let base = 40.0 + progress * 30.0;
        if gap_useful {
            score += base;
        } else {
            score += base * (1.0 - waste_frac * 1.6).max(0.0);
        }
        if next_item_size >= bin_capacity / 2 && next_item_size as f64 > mean_residual {
            score -= 70.0;
        }
        if open_bins_count > 20 && mean_residual < bin_capacity as f64 / 10.0 {
            score -= 30.0;
        }
        // Waste-floor pressure
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining * 0.1;
        if post_residual as f64 > demand && progress > 0.6 {
            score += (post_residual as f64 - demand) * 0.15 * progress;
        }
        // Scarcity-aware suppression: don't open fresh bins when alternatives exist
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        // Fill-forecast gate: fresh bin must be plausibly fillable
        let remaining = total_items.saturating_sub(step_index) as f64;
        let forecast = mean_residual * remaining.min(50.0);
        let cap_f = bin_capacity as f64;
        if forecast < cap_f * 0.8 {
            let shortfall = (cap_f * 0.8 - forecast) / cap_f;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        // Demand-aware gate
        let full_demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > full_demand * 0.35 {
            score += (post_f - full_demand * 0.35) * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap_f * 0.5 {
            score += (post_f - cap_f * 0.5) * 0.25;
        }
    }

    // Prefer filling nearly-full bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.7 + 0.6 * progress);

    // Compact pairing tie-break
    if bin_residual >= item_size {
        score -= (bin_residual - item_size) as f64 * 0.05;
    }

    // Small-item late-stream protection
    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Balanced split reward
    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    // Fragmentation guard: awkward 6..=12 band without chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
        }
    }

    // Adaptive fragmentation band 13..=20 late
    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Almost-chain trap: residual just above next item leaves stranded slivers
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
    }

    // Residual-reusability index: post residual matching small multiples of item_size
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Endgame consolidation
    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    score
}

