    // residual to the expected sizes of upcoming small items. A residual
    // that equals a small multiple of item_size is highly likely to be
    // exactly consumed by future items of similar size; reward it
    // proportionally to how close it lands, strongest mid-stream where
    // most waste accumulates.
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
