    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        let scarcity = (3 - fitting_bins_count.min(3)) as f64;
        score -= 30.0 + scarcity * 15.0 * (0.5 + progress);
    }

    // MUTATION (gen 17): open-bin pool pressure — late in the stream, when
    // many bins remain open with large residuals, adding a new bin spreads
    // the remaining demand thinner and strands more space. Charge new bins
