    // with remaining demand.
    if bin_residual == bin_capacity && progress > 0.4 {
        let remaining = total_items.saturating_sub(step_index) as f64;
        let demand = mean_residual * remaining;
        let pool = open_bins_count as f64 * mean_residual.max(1.0);
        let pressure = pool / (demand + 1.0);
        if pressure > 1.0 {
            score += (pressure - 1.0).min(6.0) * 12.0 * progress;
        }
    }

    score
}

