            let excess = post_residual as f64 - per_bin_demand * 1.5;
            score += excess * 0.35 * progress;
        }
    }

    // MUTATION (gen 19): tightness-vs-freshness tradeoff — a fresh bin is
    // only worth opening when the best existing fit would leave a residual
    // larger than the next item (i.e., a doomed gap). Sharpen the gap
    // penalty on the fresh-bin candidate so doomed gaps never win.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let gap_doomed = next_item_size > 0
            && post_residual > 0
            && post_residual < next_item_size
            && (next_item_size - post_residual) as f64 > mean_residual * 0.5;
        if gap_doomed {
            score += 30.0 + progress * 25.0;
        }
    }

    // MUTATION (gen 19): closure-rate bonus — a placement that closes a bin
    // (post_residual == 0) frees an open bin, which reduces fragmentation
    // pressure across the whole stream; scale by how many bins are open.
    if post_residual == 0 && open_bins_count > 3 {
        score -= (open_bins_count.min(12)) as f64 * 2.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
