        let after = post_residual - next_item_size;
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
    }

    // MUTATION: scarcity-weighted perfect fit — when only one or two bins
    // fit, a zero post residual is nearly free capacity.
    if post_residual == 0 && fitting_bins_count <= 2 {
        score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
    }

    // MUTATION (gen 16): residual-reusability index — couple the post
    // residual to the expected sizes of upcoming small items.
