    // consolidates into fewer, fuller bins.
    if open_bins_count > 5 && progress > 0.25 && post_residual > 15 {
        let pressure = ((open_bins_count as f64) - 5.0).min(10.0) / 10.0;
        score += (post_residual as f64 - 15.0) * pressure * (0.2 + progress * 0.6);
    }

