    // penalty by the jump magnitude rather than applying it uniformly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let jump = next_item_size as f64 / mean_residual.max(1.0);
        if jump > 2.0 {
            score += (next_item_size - post_residual) as f64 * (0.25 + (jump - 2.0).min(3.0) * 0.2);
        }
    }

