    // ±2 of half the bin capacity are prime targets for a single
    // complementary large item; reward keeping them when the next item
    // is small (it can ride along without destroying the halfpoint).
    let half_cap = bin_capacity as f64 * 0.5;
    if post_residual > 0 && (post_residual as f64 - half_cap).abs() <= 2.0 && next_item_size <= 10 {
        score -= 8.0 + progress * 6.0;
    }

    // MUTATION (gen 19): endgame fresh-bin lockout — in the final 12% of
    // the stream, opening a new bin is almost never recoverable unless the
    // very next item exactly matches the item being placed (pair completion).
    if bin_residual == bin_capacity && progress > 0.88 {
        let pairable = next_item_size > 0 && item_size + next_item_size <= bin_capacity;
        if !pairable {
            score += 30.0 + (progress - 0.88) * 400.0;
        }
    }

    score
}

