    // over-penalizing bins that remain salvageable.
    if post_residual >= 6 && post_residual <= 12 && next_item_size > 0 && post_residual < next_item_size {
        if (next_item_size - post_residual) as f64 <= mean_residual {
            score -= 4.0 + progress * 6.0;
        }
    }

    // MUTATION (gen 19): waste-floor sweep — the 68-bin gap suggests the
    // final placements leave large stranded residuals. In the last 20%,
    // any placement that leaves a residual larger than the next item but
    // below the mean residual quantum is a near-certain dead end; penalize
    // it proportionally so bins close cleanly instead.
    if progress > 0.8 && next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && (after as f64) < mean_residual {
            score += (mean_residual - after as f64) * (2.0 + progress * 6.0);
        }
    }

    // MUTATION (gen 19): capacity-tightening of the new-bin gate — the
    // fresh-bin candidate should only win when its post residual is
    // genuinely small relative to capacity; otherwise the residual
    // compounds across bins. Sharpen the existing waste penalty with a
    // quadratic term on the fresh-bin waste fraction, gated on scarcity.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let waste_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        if waste_frac > 0.3 {
            score += (waste_frac - 0.3) * (waste_frac - 0.3) * 90.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 19): dual-fit chain guard — when the item fits more
    // than two bins and the post residual cannot hold the next item, the
    // chain is broken; steer the item toward a bin whose post residual
    // keeps the chain alive, weighted by how much residual is destroyed.
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * (0.5 + progress * 0.7);
    }

    // MUTATION (gen 19): endgame fresh-bin lockout — in the final 10%,
    // opening a new bin almost always wastes more than squeezing into a
    // poor fit, unless the item is a perfect fit for the fresh bin.
    if bin_residual == bin_capacity && progress > 0.9 && post_residual != 0 {
        score += 120.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: exact match of next item into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
    }

    // Dead-space penalty relative to mean residual, scaled by progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let waste_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        let gap_dead = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        if gap_dead {
            let dead_ratio = (next_item_size - post_residual) as f64 / bin_capacity.max(1) as f64;
            score += (40.0 + progress * 30.0) * (1.0 - dead_ratio * 2.0).max(0.0);
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score += 40.0 + progress * 30.0;
        } else {
            score += (40.0 + progress * 30.0) * (1.0 - waste_frac * 1.5).max(0.0);
        }
        if progress > 0.5 && open_bins_count > 4 && mean_residual > (bin_capacity as f64) * 0.4 {
            score -= 20.0 * (progress - 0.5);
        }
    }

    // Prefer filling nearly-full bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // Small-item late-stream bonus
    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Tight-fit refinement — small residual rewards
    if post_residual == 1 || post_residual == 2 || post_residual == 3 {
        score -= 25.0;
    }

    // Penalty for residual just below next item size with multiple options
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count > 1 {
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Pairing with next item when several bins fit
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    // Balanced split reward
    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    // Chain-lookahead — reward residuals that can absorb the next
    // item AND still leave a small (<=5) usable remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after <= 5 {
            score -= 18.0 + (5 - after) as f64 * 2.0;
        }
    }

    // Waste-floor pressure — when the stream is nearly done, the
    // marginal cost of opening a bin that will be underfilled rises sharply.
    if bin_residual == bin_capacity {
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining * 0.1;
        if post_residual as f64 > demand && progress > 0.6 {
            score += (post_residual as f64 - demand) * 0.15 * progress;
        }
    }

    // Near-exact fit sharpening — placements that leave residual
    // within 2 of the next item size are prime chain candidates.
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let d = post_residual - next_item_size;
        if d <= 2 {
            score -= 10.0;
        }
    }

    // Two-item lookahead — if post_residual can absorb the next item AND
    // the remainder is still larger than half the mean residual, deepen
    // the chain reward proportionally.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
    }

    // Fragmentation guard — residuals in the awkward 6..=12 band are
    // the leading source of dead space late in the stream. Penalize leaving
    // them behind unless a perfect chain exists, scaled by stream progress.
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
        }
    }

    // Scarcity-aware new-bin suppression — when several open bins
    // already fit, opening a fresh bin should cost more unless the post
    // residual is small enough to be reliably reusable by upcoming items.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let reusable = post_residual as f64 >= mean_residual * 0.8;
        if !reusable {
            score += 8.0 + progress * 12.0;
        } else if post_residual as f64 > mean_residual * 1.6 {
            score += 4.0;
        }
    }

    // Adaptive fragmentation band — 13..=20 late in the stream.
    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Perfect-chain depth bonus — post residual equals next item exactly.
    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        let scarcity = (3 - fitting_bins_count.min(3)) as f64;
        score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
    }

    // Mean-residual harmonic reuse.
    if post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev < 2.0 {
                score -= (2.0 - dev) * (1.0 + progress);
            }
        }
    }

    // Endgame consolidation — final 10% of the stream.
    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    // Demand-aware new-bin gate — full-stream coupling between remaining
    // item demand and the fresh bin's post residual.
    if bin_residual == bin_capacity {
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > bin_capacity as f64 * 0.5 {
            score += (post_f - bin_capacity as f64 * 0.5) * 0.25;
        }
    }

    // Tri-item chain probe — reward placements whose residual
    // can absorb the next item and still exceed the item after that in
    // expectation (approximated by mean residual).
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
    }

    // Sharpened endgame exact-fit bonus — in the last 5%,
    // residuals of 1..=4 are near-certain closures.
    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    // MUTATION: complement-pairing probe — a placement is especially
    // valuable when its post residual is the exact complement of the next
    // item against the mean-residual quantum.
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    // MUTATION: dead-space floor sharpening — residuals strictly between
    // the next item and next_item + 3 are "almost-chain" traps.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
    }

    // MUTATION: scarcity-weighted perfect fit — when only one or two bins
    // fit, a zero post residual is nearly free capacity.
    if post_residual == 0 && fitting_bins_count <= 2 {
        score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
    }

    // MUTATION (gen 16): residual-reusability index — couple the post
    // residual to the expected sizes of upcoming small items.
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // MUTATION (gen 16): large-item pre-reservation — when the next item
    // is large (> 40% of capacity) and the post residual cannot hold it,
    // this bin becomes stranded space; penalize harder so the item goes
    // into a bin where it can be followed by small fillers.
    if next_item_size as f64 > bin_capacity as f64 * 0.4
        && post_residual > 0
        && post_residual < next_item_size
    {
        score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
    }

    // MUTATION (gen 16): new-bin fill-forecast — a fresh bin should only
    // open when the remaining stream can plausibly fill it.
    if bin_residual == bin_capacity {
        let remaining = total_items.saturating_sub(step_index) as f64;
        let forecast = mean_residual * remaining.min(50.0);
        let cap_f = bin_capacity as f64;
        if forecast < cap_f * 0.8 {
            let shortfall = (cap_f * 0.8 - forecast) / cap_f;
            score += shortfall * 60.0 * (0.4 + progress);
        }
    }

    // MUTATION (gen 17): chain-continuity refinement — the chain-lookahead
    // reward for small remainders (<=5) is strongest when the remainder is
    // small AND the next item itself is small (likely part of a run of
    // small fillers). Scale the reward by next item scarcity so that
    // near-perfect chains in crowded streams dominate.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after <= 5 && next_item_size <= 15 {
            score -= (5 - after) as f64 * 3.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 17): bin-load balance coupling — when several bins
    // already fit the item, prefer the one whose post residual best
    // matches the harmonic mean residual (maximizes future exact-fill
    // probability). Penalize residuals in the "dead zone" just above the
    // next item where nothing else fits well.
    if fitting_bins_count > 1 && post_residual > 0 && mean_residual > 1.0 {
        let ratio = post_residual as f64 / mean_residual;
        let frac = ratio - ratio.floor();
        if frac > 0.6 && frac < 0.95 && post_residual < next_item_size.max(1) * 2 {
            score += (frac - 0.6) * 12.0 * progress;
        }
    }

    // MUTATION (gen 17): early-stream capacity preservation — in the first
    // 20% of the stream, opening new bins is cheap and keeps options open;
    // reward fresh bins slightly so items don't cram into bins that would
    // be better reserved for later large items.
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 6.0 * (0.2 - progress) * 50.0 * (post_residual as f64 / bin_capacity.max(1) as f64);
    }

    // MUTATION (gen 17): next-item stranding guard — if the next item
    // cannot fit into post_residual but WOULD fit into the current
    // residual (i.e., placing here destroys a chain), penalize strongly
    // when few alternatives exist.
    if next_item_size > 0
        && post_residual > 0
        && post_residual < next_item_size
        && bin_residual >= next_item_size
        && fitting_bins_count <= 2
    {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // MUTATION (gen 18): mid-band residual recycling — residuals in the
    // 21..=35 band are the second-largest dead-space source after the
    // 6..=12 band, especially mid-stream. Reward placements that either
    // consume such a residual entirely or reshape it into a reusable
    // quantum (near-multiple of the mean residual).
    if bin_residual >= 21 && bin_residual <= 35 {
        if post_residual == 0 {
            score -= 20.0 + progress * 15.0;
        } else {
            let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
            if reshaped >= 1.0 {
                let dev = (post_residual as f64 - reshaped * mean_residual).abs();
                if dev <= 3.0 {
                    score -= (3.0 - dev) * 4.0 * (0.4 + progress);
                }
            }
        }
    }

    // MUTATION (gen 18): greedy-anchor suppression — when the item is a
    // large anchor (> 55% of capacity), placing it in a partially-filled
    // bin tends to strand the leftover; prefer a fresh bin for anchors
    // unless a near-perfect fit exists, letting small fillers pack the
    // older bins cleanly.
    if item_size as f64 > bin_capacity as f64 * 0.55
        && bin_residual != bin_capacity
        && post_residual > 3
    {
        let stranded_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        score += stranded_frac * 55.0 * (0.5 + progress);
    }

    // MUTATION (gen 18): two-item exact-sum probe — reward placements
    // where the current residual is consumed exactly by the next item
    // plus a plausible filler (approximated by the mean residual),
    // which closes bins with zero waste.
    if next_item_size > 0
        && post_residual > 0
        && post_residual > next_item_size
        && mean_residual >= 1.0
    {
        let filler = post_residual - next_item_size;
        let dev = (filler as f64 - mean_residual).abs();
        if dev <= 2.0 {
            score -= (2.0 - dev) * 10.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 18): scarcity-tuned dead-band softening — the 6..=12
    // fragmentation penalty should relax when the next item could still
    // chain into a *larger* upcoming item (mean residual proxy), avoiding
    // over-penalizing bins that remain salvageable.
    if post_residual >= 6 && post_residual <= 12 && next_item_size > 0 && post_residual < next_item_size {
        if (next_item_size - post_residual) as f64 <= mean_residual {
            score -= 4.0 + progress * 6.0;
        }
    }

    // MUTATION (gen 20): terminal-zone closure sharpening — in the final
    // 15% of the stream, bins that will never see another item should be
    // driven to zero residual. Reward placements that close bins exactly,
    // and penalize leaving any residual that the remaining demand
    // (mean residual proxy) cannot plausibly consume.
    if progress > 0.85 && post_residual > 0 {
        let remaining = total_items.saturating_sub(step_index) as f64;
        let demand = mean_residual * remaining.min(5.0);
        if post_residual as f64 > demand {
            score += (post_residual as f64 - demand) * (0.8 + (progress - 0.85) * 6.0);
        } else {
            score -= (demand - post_residual as f64) * 1.5 * (progress - 0.85) * 10.0;
        }
    }

    // MUTATION (gen 20): fresh-bin residual minimization — for the new-bin
    // candidate, prefer opening bins that will be filled as completely as
    // possible: penalize fresh bins whose post residual exceeds the
    // item-adjusted usable space, with strength coupled to stream progress
    // and open-bin count (more open bins = more competition for items).
    if bin_residual == bin_capacity {
        let post_f = post_residual as f64;
        let cap_f = bin_capacity.max(1) as f64;
        let competition = (open_bins_count.min(20) as f64 / 20.0) * (0.5 + progress);
        score += post_f * 0.12 * competition;
        // Coupled refinement: if the next item exactly fills the fresh bin
        // after this item, the fresh bin is a near-perfect open — reward it.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 35.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 20): dual-remainder chain probe — when the post
    // residual can absorb the next item and the remainder is itself
    // absorbable by a typical filler (mean residual), this placement
    // enables a three-item closure. Reward proportionally to how close
    // the remainder is to the mean residual, strongest mid-stream.
    if next_item_size > 0 && post_residual > next_item_size && progress >= 0.2 && progress <= 0.85 {
        let after = post_residual - next_item_size;
        let m = mean_residual.max(1.0);
        let k = (after as f64 / m).round();
        if k >= 1.0 {
            let dev = (after as f64 - k * m).abs();
            if dev <= 1.0 {
                score -= (1.0 - dev) * 9.0 * (1.0 - (progress - 0.2).abs() * 0.8);
            }
        }
    }

    score
}

