                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        // Compaction squeeze
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        // Almost-chain trap — next item fits but leaves a sliver
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        // Dead-space ratio coupling
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        // Two-item exact-sum probe — residual consumed exactly by
        // next item plus a plausible filler (mean-residual proxy) closes bins
        // with zero waste.
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        // MUTATION: chain-depth compaction — when the remainder after the
        // next item still exceeds a full mean residual AND the item itself
        // is small, prefer reshaping larger residuals over dumping into
        // near-full ones; sharpen the exactness gradient.
        if after >= 2 {
            score += (after.min(20) as f64) * 0.15 * (1.0 - progress);
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; leftover likely wasted
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        // Large-item stranding — big next items leave this bin stranded
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        // Chain-destruction guard — placing here would destroy a
        // chain where the next item fits the *current* residual; penalize
        // when few alternatives exist.
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        // Demand-aware new-bin gate
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        // Fresh-bin fill-forecast — only open a fresh bin when the remaining
        // stream can plausibly fill it.
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        // Early-stream capacity preservation — in the first 20%,
        // opening new bins is cheap and keeps options open for later large items.
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        // Large-anchor routing — big items (>55% cap) are better
        // seeded into a fresh bin so small fillers can pack older bins cleanly.
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        // MUTATION: mid-stream new-bin throttle — between 35% and 80% of the
        // stream, opening bins while many open bins still fit wastes the
        // theoretical minimum; tighten the gate when open_bins_count is high.
        if progress > 0.35 && progress < 0.8 && open_bins_count > 4 && fitting_bins_count > 0 {
            score += (open_bins_count.min(12) as f64 - 4.0) * 3.0 * (1.0 - (progress - 0.35).abs() * 1.5).max(0.3);
        }
    } else {
        // Greedy-anchor suppression — placing a large anchor into a
        // partially-filled bin strands the leftover unless near-perfect fit.
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        // MUTATION: mid-band anchor softening — large anchors that land
        // exactly on a 21..=35 residual's edge (leaving <=3) are fine;
        // relax the suppression for near-closures.
        if item_size as f64 > cap * 0.55 && post_residual <= 3 && bin_residual >= 21 {
            score -= 20.0;
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            // Salvageable-band softening — if the gap to the next
            // item is within one mean residual, this band may still be
            // consumed; relax the penalty.
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index — post residual near a small multiple of
    // item_size is likely exactly consumed by future similar items.
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping — placements into 21..=35 residuals that
    // reshape the leftover into a reusable quantum (near-multiple of mean
    // residual) reduce the second-largest dead-space source.
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // MUTATION: endgame sliver sweep — in the final 15%, any placement
    // leaving post_residual below the mean residual is nearly certain
    // dead space; penalize proportionally to how far below it falls.
    if progress > 0.85 && post_residual > 0 && (post_residual as f64) < mean_residual {
        score += (mean_residual - post_residual as f64) * (2.0 + (progress - 0.85) * 20.0);
    }

    // MUTATION: fitting-count compaction tiebreak — when many bins fit,
    // steer toward the fullest bin (smallest post residual) more strongly
    // late in the stream, tightening overall compaction.
    if fitting_bins_count > 3 {
        score += (post_residual as f64) * 0.1 * (0.3 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap_f = bin_capacity.max(1) as f64;

    // Perfect fit: near-certain closure
    if post_residual == 0 {
        score -= 400.0 + (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
    }

    // Lookahead: next item fits into post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 200.0 + (3 - fitting_bins_count.min(3)) as f64 * 6.0 * (0.5 + progress);
        } else if gap <= 5 {
            // chain with tiny remainder
            score -= 18.0 + (5 - gap) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - gap) as f64 * 3.0 * (0.5 + progress);
            }
        } else {
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 60.0 * fill_ratio * fill_ratio;
            if fitting_bins_count > 2 {
                score -= gap as f64 * 0.2;
            }
        }
    } else if next_item_size > 0 {
        // next item won't fit here: dead space, worse when it strands a large item
        let mut pen = 10.0;
        if next_item_size as f64 > cap_f * 0.4 {
            pen += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if post_residual > 0 && bin_residual >= next_item_size && fitting_bins_count <= 2 {
            pen += (next_item_size - post_residual) as f64 * 0.6;
        }
        if fitting_bins_count > 1 {
            pen += (next_item_size - post_residual) as f64 * 0.4;
        }
        score += pen;
    } else {
        score -= 5.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Dead-space penalty relative to mean residual, scaled by progress
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * (0.3 + 0.5 * progress);
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let waste_frac = post_residual as f64 / cap_f;
        let remaining = total_items.saturating_sub(step_index) as f64;
        let forecast = mean_residual * remaining.min(50.0);
        if next_item_size > 0 && post_residual >= next_item_size {
            // fresh bin enables a great follow-up, but only if stream can fill it
            if forecast >= cap_f * 0.8 {
                score -= 55.0 * (1.0 - progress);
            } else {
                score += 20.0;
            }
        } else if progress < 0.2 {
            // early stream: fresh bins are cheap and keep options open
            score -= 6.0 * (0.2 - progress) * 50.0 * waste_frac;
        } else {
            let dead_gap = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
            if dead_gap {
                score += 30.0;
            } else {
                score += (30.0 * (1.0 - waste_frac * 1.5)).max(0.0);
            }
            // fill-forecast: don't open bins the stream can't fill
            if forecast < cap_f * 0.8 {
                let shortfall = (cap_f * 0.8 - forecast) / cap_f;
                score += shortfall * 60.0 * (0.4 + progress);
            }
        }
        // scarcity-aware suppression
        if fitting_bins_count > 0 && post_residual > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            }
        }
    }

    // Prefer filling nearly-full bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // Fragmentation guard: awkward 6..=12 band unless chainable
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
        } else if (next_item_size - post_residual) as f64 <= mean_residual {
            // salvageable: soften
            score -= 4.0 + progress * 6.0;
        }
    }

    // Harmonic residual reuse: align post residual to mean-residual quanta
    if post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev < 2.0 {
                score -= (2.0 - dev) * (1.0 + progress);
            }
        }
    }

    // Exact-sum filler probe: residual = next item + mean-residual filler
    if next_item_size > 0 && post_residual > next_item_size && mean_residual >= 1.0 {
        let filler = post_residual - next_item_size;
        let dev = (filler as f64 - mean_residual).abs();
        if dev <= 2.0 {
            score -= (2.0 - dev) * 10.0 * (0.5 + progress);
        }
    }

    // Endgame consolidation
    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: exact match of next item into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
    }

    // Dead-space penalty relative to mean residual, scaled by progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let waste_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        let gap_dead = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        if gap_dead {
            let dead_ratio = (next_item_size - post_residual) as f64 / bin_capacity.max(1) as f64;
            score += (40.0 + progress * 30.0) * (1.0 - dead_ratio * 2.0).max(0.0);
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score += 40.0 + progress * 30.0;
        } else {
            score += (40.0 + progress * 30.0) * (1.0 - waste_frac * 1.5).max(0.0);
        }
        if progress > 0.5 && open_bins_count > 4 && mean_residual > (bin_capacity as f64) * 0.4 {
            score -= 20.0 * (progress - 0.5);
        }
    }

    // Prefer filling nearly-full bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // Small-item late-stream bonus
    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Tight-fit refinement
    if post_residual == 1 || post_residual == 2 || post_residual == 3 {
        score -= 25.0;
    }

    // Penalty for residual just below next item size with multiple options
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count > 1 {
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Pairing with next item when several bins fit
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    // Balanced split reward
    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    // Chain-lookahead — reward residuals that absorb next item and leave a small remainder
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after <= 5 {
            score -= 18.0 + (5 - after) as f64 * 2.0;
        }
    }

    // Waste-floor pressure near the end of stream
    if bin_residual == bin_capacity {
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining * 0.1;
        if post_residual as f64 > demand && progress > 0.6 {
            score += (post_residual as f64 - demand) * 0.15 * progress;
        }
    }

    // Near-exact fit sharpening
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let d = post_residual - next_item_size;
        if d <= 2 {
            score -= 10.0;
        }
    }

    // Two-item lookahead — deepen chain reward when remainder stays large
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
    }

    // Fragmentation guard — awkward 6..=12 band
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
        }
    }

    // Scarcity-aware new-bin suppression
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let reusable = post_residual as f64 >= mean_residual * 0.8;
        if !reusable {
            score += 8.0 + progress * 12.0;
        } else if post_residual as f64 > mean_residual * 1.6 {
            score += 4.0;
        }
    }

    // Adaptive fragmentation band 13..=20 late in stream
    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Perfect-chain depth bonus
    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        let scarcity = (3 - fitting_bins_count.min(3)) as f64;
        score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
    }

    // Mean-residual harmonic reuse
    if post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev < 2.0 {
                score -= (2.0 - dev) * (1.0 + progress);
            }
        }
    }

    // Endgame consolidation
    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    // Demand-aware new-bin gate
    if bin_residual == bin_capacity {
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > bin_capacity as f64 * 0.5 {
            score += (post_f - bin_capacity as f64 * 0.5) * 0.25;
        }
    }

    // Tri-item chain probe
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
    }

    // Sharpened endgame exact-fit bonus
    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    // Dead-space floor sharpening — almost-chain traps
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
    }

    // Scarcity-weighted perfect fit
    if post_residual == 0 && fitting_bins_count <= 2 {
        score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Large-item pre-reservation
    if next_item_size as f64 > bin_capacity as f64 * 0.4
        && post_residual > 0
        && post_residual < next_item_size
    {
        score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
    }

    // New-bin fill-forecast
    if bin_residual == bin_capacity {
        let remaining = total_items.saturating_sub(step_index) as f64;
        let forecast = mean_residual * remaining.min(50.0);
        let cap_f = bin_capacity as f64;
        if forecast < cap_f * 0.8 {
            let shortfall = (cap_f * 0.8 - forecast) / cap_f;
            score += shortfall * 60.0 * (0.4 + progress);
        }
    }

    // Chain-continuity refinement
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after <= 5 && next_item_size <= 15 {
            score -= (5 - after) as f64 * 3.0 * (0.5 + progress);
        }
    }

    // Bin-load balance coupling
    if fitting_bins_count > 1 && post_residual > 0 && mean_residual > 1.0 {
        let ratio = post_residual as f64 / mean_residual;
        let frac = ratio - ratio.floor();
        if frac > 0.6 && frac < 0.95 && post_residual < next_item_size.max(1) * 2 {
            score += (frac - 0.6) * 12.0 * progress;
        }
    }

    // Early-stream capacity preservation
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 6.0 * (0.2 - progress) * 50.0 * (post_residual as f64 / bin_capacity.max(1) as f64);
    }

    // Next-item stranding guard
    if next_item_size > 0
        && post_residual > 0
        && post_residual < next_item_size
        && bin_residual >= next_item_size
        && fitting_bins_count <= 2
    {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Mid-band residual recycling (21..=35)
    if bin_residual >= 21 && bin_residual <= 35 {
        if post_residual == 0 {
            score -= 20.0 + progress * 15.0;
        } else {
            let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
            if reshaped >= 1.0 {
                let dev = (post_residual as f64 - reshaped * mean_residual).abs();
                if dev <= 3.0 {
                    score -= (3.0 - dev) * 4.0 * (0.4 + progress);
                }
            }
        }
    }

    // Greedy-anchor suppression
    if item_size as f64 > bin_capacity as f64 * 0.55
        && bin_residual != bin_capacity
        && post_residual > 3
    {
        let stranded_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        score += stranded_frac * 55.0 * (0.5 + progress);
    }

    // Two-item exact-sum probe
    if next_item_size > 0
        && post_residual > 0
        && post_residual > next_item_size
        && mean_residual >= 1.0
    {
        let filler = post_residual - next_item_size;
        let dev = (filler as f64 - mean_residual).abs();
        if dev <= 2.0 {
            score -= (2.0 - dev) * 10.0 * (0.5 + progress);
        }
    }

    // Scarcity-tuned dead-band softening
    if post_residual >= 6 && post_residual <= 12 && next_item_size > 0 && post_residual < next_item_size {
        if (next_item_size - post_residual) as f64 <= mean_residual {
            score -= 4.0 + progress * 6.0;
        }
    }

    // MUTATION (gen 20): variance-aware chain depth — measure how far the
    // next item sits from the mean residual; when the next item is small
    // (well below mean residual), chaining leaves more reusable room, so
    // reward proportionally to the shortfall; when it is large, chains
    // strand more space, so soften the chain reward.
    if next_item_size > 0 && post_residual > next_item_size && mean_residual > 1.0 {
        let shortfall = mean_residual - next_item_size as f64;
        if shortfall > 2.0 {
            let after = post_residual - next_item_size;
            if after as f64 >= mean_residual * 0.6 {
                score -= (shortfall.min(20.0)) * 0.35 * (0.4 + progress);
            }
        } else if shortfall < -8.0 && post_residual > 0 && post_residual < next_item_size {
            // next item is big relative to mean: residual below it is
            // likely stranded for long; penalize the gap harder mid-stream
            score += (next_item_size - post_residual) as f64 * 0.15 * progress;
        }
    }

    // MUTATION (gen 20): closure-urgency gate — when the current residual
    // is small (<= 8) and placing here empties the bin (post_residual 0),
    // closing a bin outright is nearly always superior to leaving a sliver.
    if bin_residual <= 8 && bin_residual != bin_capacity {
        if post_residual == 0 {
            score -= 30.0 * (0.5 + progress);
        } else {
            score += (bin_capacity.min(100) - bin_residual) as f64 * 0.0
                + (8 - bin_residual) as f64 * 2.5;
        }
    }

    // MUTATION (gen 20): open-bin count pressure — with many open bins and
    // low remaining demand, prefer placements that consolidate (post
    // residual 0 or tiny) over spreading items across bins.
    if open_bins_count > 8 {
        let remaining = total_items.saturating_sub(step_index) as f64;
        if remaining < open_bins_count as f64 * 1.5 {
            if post_residual == 0 {
                score -= 15.0;
            } else if post_residual < 6 {
                score -= (6 - post_residual) as f64 * 3.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
    }

    // Harmonic class of post_residual
    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        // perfect-chain depth bonus
        if post_residual == next_item_size {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        // chain remainder shaping: tiny usable remainders are prime
        let after = post_residual - next_item_size;
        if after <= 5 {
            score -= 18.0 + (5 - after) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - after) as f64 * 3.0 * (0.5 + progress);
            }
        } else if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; leftover likely wasted
        score += (post_residual as f64) * 0.3;
        // stranding guard: placing here destroys a chain
        if post_residual > 0 && bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        // large-item pre-reservation
        if next_item_size as f64 > cap_f * 0.4 && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        // fill-forecast: fresh bin only when remaining stream can fill it
        let remaining = total_items.saturating_sub(step_index) as f64;
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap_f * 0.8 {
            let shortfall = (cap_f * 0.8 - forecast) / cap_f;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        // scarcity-aware suppression
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        // early-stream capacity preservation
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_residual as f64 / cap_f.max(1.0));
        }
        // demand-aware gate
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
    }

    // Prefer tighter bins overall: penalize bins with much more residual than mean
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins, stronger as stream progresses
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    // Fragmentation guard — awkward 6..=12 band
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
        } else if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
            score -= 4.0 + progress * 6.0;
        }
    }

    // Mid-band residual recycling — 21..=35
    if bin_residual >= 21 && bin_residual <= 35 {
        if post_residual == 0 {
            score -= 20.0 + progress * 15.0;
        } else {
            let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
            if reshaped >= 1.0 {
                let dev = (post_residual as f64 - reshaped * mean_residual).abs();
                if dev <= 3.0 {
                    score -= (3.0 - dev) * 4.0 * (0.4 + progress);
                }
            }
        }
    }

    // Mean-residual harmonic reuse
    if post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev < 2.0 {
                score -= (2.0 - dev) * (1.0 + progress);
            }
        }
    }

    // Two-item exact-sum probe
    if next_item_size > 0 && post_residual > next_item_size && mean_residual >= 1.0 {
        let filler = post_residual - next_item_size;
        let dev = (filler as f64 - mean_residual).abs();
        if dev <= 2.0 {
            score -= (2.0 - dev) * 10.0 * (0.5 + progress);
        }
    }

    // Greedy-anchor suppression for large items
    if item_size as f64 > cap_f * 0.55 && bin_residual != bin_capacity && post_residual > 3 {
        let stranded_frac = post_residual as f64 / cap_f.max(1.0);
        score += stranded_frac * 55.0 * (0.5 + progress);
    }

    // Endgame consolidation
    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }
    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    // Small-item late-stream bonus
    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    score
}

