    // Scarcity-weighted perfect fit
    if post_residual == 0 && fitting_bins_count <= 2 {
        score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Large-item pre-reservation
    if next_item_size as f64 > bin_capacity as f64 * 0.4
        && post_residual > 0
        && post_residual < next_item_size
    {
        score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
    }

    // New-bin fill-forecast
    if bin_residual == bin_capacity {
        let remaining = total_items.saturating_sub(step_index) as f64;
        let forecast = mean_residual * remaining.min(50.0);
        let cap_f = bin_capacity as f64;
        if forecast < cap_f * 0.8 {
            let shortfall = (cap_f * 0.8 - forecast) / cap_f;
            score += shortfall * 60.0 * (0.4 + progress);
        }
    }

    // Chain-continuity refinement for small fillers
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after <= 5 && next_item_size <= 15 {
            score -= (5 - after) as f64 * 3.0 * (0.5 + progress);
        }
    }

    // Bin-load balance coupling
    if fitting_bins_count > 1 && post_residual > 0 && mean_residual > 1.0 {
        let ratio = post_residual as f64 / mean_residual;
        let frac = ratio - ratio.floor();
        if frac > 0.6 && frac < 0.95 && post_residual < next_item_size.max(1) * 2 {
            score += (frac - 0.6) * 12.0 * progress;
        }
    }

    // Early-stream capacity preservation
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 6.0 * (0.2 - progress) * 50.0 * (post_residual as f64 / bin_capacity.max(1) as f64);
    }

    // Next-item stranding guard
    if next_item_size > 0
        && post_residual > 0
        && post_residual < next_item_size
        && bin_residual >= next_item_size
        && fitting_bins_count <= 2
    {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Mid-band residual recycling — 21..=35
    if bin_residual >= 21 && bin_residual <= 35 {
        if post_residual == 0 {
            score -= 20.0 + progress * 15.0;
        } else {
            let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
            if reshaped >= 1.0 {
                let dev = (post_residual as f64 - reshaped * mean_residual).abs();
                if dev <= 3.0 {
                    score -= (3.0 - dev) * 4.0 * (0.4 + progress);
                }
            }
        }
    }

    // Greedy-anchor suppression for large anchors
    if item_size as f64 > bin_capacity as f64 * 0.55
        && bin_residual != bin_capacity
        && post_residual > 3
    {
        let stranded_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        score += stranded_frac * 55.0 * (0.5 + progress);
    }

    // Two-item exact-sum probe
    if next_item_size > 0
        && post_residual > 0
        && post_residual > next_item_size
        && mean_residual >= 1.0
    {
        let filler = post_residual - next_item_size;
        let dev = (filler as f64 - mean_residual).abs();
        if dev <= 2.0 {
            score -= (2.0 - dev) * 10.0 * (0.5 + progress);
        }
    }

    // Scarcity-tuned dead-band softening
    if post_residual >= 6 && post_residual <= 12 && next_item_size > 0 && post_residual < next_item_size {
        if (next_item_size - post_residual) as f64 <= mean_residual {
            score -= 4.0 + progress * 6.0;
        }
    }

    // MUTATION (gen 22): open-bin inventory pressure — when many bins are
    // open and the sum of their residuals already covers the remaining
    // demand, opening a new bin wastes capacity; penalize fresh bins
    // proportionally to the surplus, but relax when open bins are all
    // too small for the next item (true scarcity).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let remaining = total_items.saturating_sub(step_index) as f64;
        let demand = mean_residual * remaining;
        let open_supply = open_bins_count as f64 * mean_residual;
        let surplus = open_supply - demand;
        if surplus > 0.0 {
            let scarcity_escape = next_item_size > 0
                && open_bins_count == fitting_bins_count
                && (bin_capacity as f64) < next_item_size as f64;
            if !scarcity_escape {
                score += (surplus / (open_bins_count as f64).max(1.0)).min(30.0)
                    * (0.5 + progress * 1.5);
            }
        }
    }

    // MUTATION (gen 22): residual-split harmonization — when the post
    // residual can be split into two halves each fitting the next item,
    // the placement supports a future two-way fill; reward proportional
    // to how many such splits exist (post / next floor).
    if next_item_size > 0 && post_residual >= next_item_size * 2 {
        let splits = post_residual / next_item_size;
        if splits >= 2 {
            score -= (splits.min(4) as f64) * 4.0 * (0.3 + progress);
        }
    }

    // MUTATION (gen 22): late-stream waste ceiling — in the final third,
    // any post residual exceeding (capacity - next_item) is guaranteed
    // unusable dead space for the immediate future; penalize it sharply
    // so the item is pushed into a bin where the leftover stays usable.
    if progress > 0.33
        && next_item_size > 0
        && post_residual > 0
        && post_residual as f64 > bin_capacity as f64 - next_item_size as f64
    {
        let unusable = post_residual as f64 - (bin_capacity as f64 - next_item_size as f64);
        score += unusable * (1.0 + progress * 2.0);
    }

    // MUTATION (gen 22): exact-closure sweep refinement — strengthen the
    // tight-fit reward (residual 1..=3) when the open-bin count is high,
    // since closing bins reduces fragmentation pressure on later items.
    if post_residual >= 1 && post_residual <= 3 && open_bins_count > 5 {
        score -= 8.0 + (3 - post_residual) as f64 * 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to ever be useful are doubly bad.
    // Treat gaps < 10 as fully wasted; gaps that can hold the next item are fine.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual >= next_item_size {
            // Gap is reusable by the lookahead item: reward tight fit.
            score -= 6.0 + (next_item_size as f64) * 0.15;
        } else if post_residual < 10 {
            // Unusable sliver: heavy penalty proportional to wasted fraction.
            score += 30.0 + (10.0 - post_residual as f64) * 4.0;
        } else {
            // Mid-size gap: mild penalty scaled by how far from reusable.
            score += (post_residual as f64) * 0.10;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 25.0;
    }

    // Exact-fit reward when item consumes the whole residual.
    if post_residual == 0 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it slightly unattractive by default, but attractive
    // when existing bins would leave large, unusable gaps.
    if bin_residual == bin_capacity {
        score += 8.0;
        // If mean residual across open bins is large and fragmented, opening fresh
        // can be better: reduce the penalty.
        if mean_residual > 40.0 {
            score -= 10.0;
        }
        // Early in the stream, prefer opening bins to build flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 4.0;
    }

    // Slight preference for filling bins that are already quite full.
    let fullness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= fullness * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        // Two-step anticipation: next item nearly fills this bin exactly
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            // gen 22: small-filler chain reinforcement
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        // Perfect-chain depth bonus: bin closes with zero waste in two steps
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        // Tight chain refinement when few bins fit
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        // Two-item lookahead: remainder still larger than half the mean residual
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        // Tri-item chain probe
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        // Harmonic reuse — reward residuals near multiples of mean residual
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        // Compaction squeeze
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        // Almost-chain trap — next item fits but leaves a sliver
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        // Dead-space ratio coupling
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; leftover likely wasted
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        // Large-item stranding — big next items leave this bin stranded
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        // gen 22: chain destruction guard — placing here destroys a chain
        // the next item would have consumed; strong penalty when few options.
        if next_item_size > 0
            && post_residual > 0
            && bin_residual >= next_item_size
            && fitting_bins_count <= 2
        {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        // Demand-aware new-bin gate
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        // Fresh-bin fill-forecast — only open a fresh bin when
        // the remaining stream can plausibly fill it.
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        // gen 22: early-stream capacity preservation — opening fresh bins
        // early is cheap and preserves options for later large items.
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        // gen 22: waste-floor compaction — when remaining demand is small
        // relative to open capacity, avoid opening underfilled fresh bins.
        let open_waste = (open_bins_count as f64) * mean_residual;
        if demand < open_waste * 0.5 && fitting_bins_count > 0 {
            score += (open_waste * 0.5 - demand).min(80.0) * (0.3 + progress * 0.7);
        }
        // gen 22: mid-stream fresh-bin relief — when several open bins fit
        // and the stream is mid-flow, a fresh bin should only open if the
        // current best fit leaves a large dead residual.
        if fitting_bins_count > 0 && progress >= 0.2 && progress <= 0.8 {
            score += 12.0 * (1.0 - (post_f / cap).min(1.0));
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index — post residual near a small
    // multiple of item_size is likely exactly consumed by future similar items.
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // MUTATION (gen 18): two-item exact-sum probe
    if next_item_size > 0 && post_residual > 0 && post_residual > next_item_size && mean_residual >= 1.0 {
        let filler = post_residual - next_item_size;
        let dev = (filler as f64 - mean_residual).abs();
        if dev <= 2.0 {
            score -= (2.0 - dev) * 10.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 18): greedy-anchor suppression
    if item_size as f64 > cap * 0.55 && bin_residual != bin_capacity && post_residual > 3 {
        let stranded_frac = post_residual as f64 / cap;
        score += stranded_frac * 55.0 * (0.5 + progress);
    }

    // MUTATION (gen 18): mid-band residual recycling
    if bin_residual >= 21 && bin_residual <= 35 {
        if post_residual == 0 {
            score -= 20.0 + progress * 15.0;
        } else {
            let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
            if reshaped >= 1.0 {
                let dev = (post_residual as f64 - reshaped * mean_residual).abs();
                if dev <= 3.0 {
                    score -= (3.0 - dev) * 4.0 * (0.4 + progress);
                }
            }
        }
    }

    // MUTATION (gen 18): scarcity-tuned dead-band softening
    if post_residual >= 6 && post_residual <= 12 && next_item_size > 0 && post_residual < next_item_size {
        if (next_item_size - post_residual) as f64 <= mean_residual {
            score -= 4.0 + progress * 6.0;
        }
    }

    // MUTATION (gen 22): dead-zone harmonic penalty — when multiple bins
    // fit, penalize residuals in the fractional dead zone of the mean
    // residual (likely to strand a sliver no future item consumes).
    if fitting_bins_count > 1 && post_residual > 0 && mean_residual > 1.0 {
        let ratio = post_residual as f64 / mean_residual;
        let frac = ratio - ratio.floor();
        if frac > 0.6 && frac < 0.95 && post_residual < next_item_size.max(1) * 2 {
            score += (frac - 0.6) * 12.0 * progress;
        }
    }

    // MUTATION (gen 22): fine-grained dead-space ratio — sharpen the
    // baseline with a continuous dead-space term scaled by lookahead
    // usability: post residual that neither chains with the next item
    // nor matches a mean-residual quantum is penalized more strongly.
    if post_residual > 0 {
        let chains = next_item_size > 0 && next_item_size <= post_residual;
        let mut quantum = false;
        if mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 && (post_residual as f64 - k * mean_residual).abs() < 2.0 {
                quantum = true;
            }
        }
        if !chains && !quantum {
            let waste = post_residual as f64 / cap;
            score += waste * 35.0 * (0.4 + progress * 0.8);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: place here if the next item exactly fills the leftover.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits in the post-residual: strong reward, scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - 0.25 * slack;
    }

    // Next item cannot use the leftover: penalize creating small dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.35 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Relative to mean residual: prefer bins that become tighter than average.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Penalize very small unusable residuals (dead space < 10).
    if post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate: prefer it only when few fitting bins exist or match is bad.
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * fitting_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Late in the stream: consolidate more aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
