    // Perfect-chain depth bonus
    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        let scarcity = (3 - fitting_bins_count.min(3)) as f64;
        score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
    }

    // Mean-residual harmonic reuse.
    if post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev < 2.0 {
                score -= (2.0 - dev) * (1.0 + progress);
            }
        }
    }

    // Endgame consolidation — final 10% of the stream.
    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    // Demand-aware new-bin gate
    if bin_residual == bin_capacity {
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > bin_capacity as f64 * 0.5 {
            score += (post_f - bin_capacity as f64 * 0.5) * 0.25;
        }
    }

    // Tri-item chain probe
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
    }

    // Sharpened endgame exact-fit bonus
    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    // MUTATION: complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    // MUTATION: dead-space floor sharpening — almost-chain traps
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
    }

    // MUTATION: scarcity-weighted perfect fit
    if post_residual == 0 && fitting_bins_count <= 2 {
        score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
    }

    // MUTATION (gen 16): residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // MUTATION (gen 16): large-item pre-reservation
    if next_item_size as f64 > bin_capacity as f64 * 0.4
        && post_residual > 0
        && post_residual < next_item_size
    {
        score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
    }

    // MUTATION (gen 16): new-bin fill-forecast
    if bin_residual == bin_capacity {
        let remaining = total_items.saturating_sub(step_index) as f64;
        let forecast = mean_residual * remaining.min(50.0);
        let cap_f = bin_capacity as f64;
        if forecast < cap_f * 0.8 {
            let shortfall = (cap_f * 0.8 - forecast) / cap_f;
            score += shortfall * 60.0 * (0.4 + progress);
        }
    }

    // MUTATION (gen 17): chain-continuity refinement
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after <= 5 && next_item_size <= 15 {
            score -= (5 - after) as f64 * 3.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 17): bin-load balance coupling
    if fitting_bins_count > 1 && post_residual > 0 && mean_residual > 1.0 {
        let ratio = post_residual as f64 / mean_residual;
        let frac = ratio - ratio.floor();
        if frac > 0.6 && frac < 0.95 && post_residual < next_item_size.max(1) * 2 {
            score += (frac - 0.6) * 12.0 * progress;
        }
    }

    // MUTATION (gen 17): early-stream capacity preservation
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 6.0 * (0.2 - progress) * 50.0 * (post_residual as f64 / bin_capacity.max(1) as f64);
    }

    // MUTATION (gen 17): next-item stranding guard
    if next_item_size > 0
        && post_residual > 0
        && post_residual < next_item_size
        && bin_residual >= next_item_size
        && fitting_bins_count <= 2
    {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // MUTATION (gen 18): mid-band residual recycling
    if bin_residual >= 21 && bin_residual <= 35 {
        if post_residual == 0 {
            score -= 20.0 + progress * 15.0;
        } else {
            let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
            if reshaped >= 1.0 {
                let dev = (post_residual as f64 - reshaped * mean_residual).abs();
                if dev <= 3.0 {
                    score -= (3.0 - dev) * 4.0 * (0.4 + progress);
                }
            }
        }
    }

    // MUTATION (gen 18): greedy-anchor suppression
    if item_size as f64 > bin_capacity as f64 * 0.55
        && bin_residual != bin_capacity
        && post_residual > 3
    {
        let stranded_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        score += stranded_frac * 55.0 * (0.5 + progress);
    }

    // MUTATION (gen 18): two-item exact-sum probe
    if next_item_size > 0
        && post_residual > 0
        && post_residual > next_item_size
        && mean_residual >= 1.0
    {
        let filler = post_residual - next_item_size;
        let dev = (filler as f64 - mean_residual).abs();
        if dev <= 2.0 {
            score -= (2.0 - dev) * 10.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 18): scarcity-tuned dead-band softening
    if post_residual >= 6 && post_residual <= 12 && next_item_size > 0 && post_residual < next_item_size {
        if (next_item_size - post_residual) as f64 <= mean_residual {
            score -= 4.0 + progress * 6.0;
        }
    }

    // MUTATION (gen 22): residual-halving probe — a placement that splits the
    // current residual into two roughly equal reusable halves (item centered)
    // maximizes the chance that both halves can host upcoming small items.
    if post_residual > 0 && bin_residual > item_size && post_residual > 4 {
        let waste = post_residual as f64;
        if (waste - (bin_residual as f64 - item_size as f64) / 2.0).abs() <= 2.0 {
            score -= 8.0 * (0.6 + progress * 0.8);
        }
    }

    // MUTATION (gen 22): dead-space ratio gate on new bins — replace the
    // coarse fill-forecast with a sharper coupling between the fresh bin's
    // post residual and the running mean residual: opening a bin whose
    // post residual is a near-exact multiple of the mean residual is cheap
    // (it will be refilled by typical items); otherwise it is dead space.
    if bin_residual == bin_capacity && post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual) / mean_residual;
            score += dev * 10.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 22): endgame filler-hoarding — in the final stretch,
    // residuals that can still host the next item deserve a stronger
    // bonus than mid-stream, since every remaining placement counts.
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (progress - 0.85) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        // Two-step anticipation: next item nearly fills this bin exactly
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            // small-filler chain reinforcement
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        // Perfect-chain depth bonus: bin closes with zero waste in two steps
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        // Tight chain refinement when few bins fit
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        // Two-item lookahead: remainder still larger than half the mean residual
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        // Tri-item chain probe
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        // Harmonic reuse — reward residuals near multiples of mean residual
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        // Compaction squeeze
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        // Almost-chain trap — next item fits but leaves a sliver
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        // Dead-space ratio coupling
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; leftover likely wasted
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        // Large-item stranding — big next items leave this bin stranded
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        // chain destruction guard — placing here destroys a chain
        // the next item would have consumed; strong penalty when few options.
        if next_item_size > 0
            && post_residual > 0
            && bin_residual >= next_item_size
            && fitting_bins_count <= 2
        {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        // Demand-aware new-bin gate
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        // Fresh-bin fill-forecast — only open a fresh bin when
        // the remaining stream can plausibly fill it.
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        // early-stream capacity preservation — opening fresh bins
        // early is cheap and preserves options for later large items.
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        // waste-floor compaction — when remaining demand is small
        // relative to open capacity, avoid opening underfilled fresh bins.
        let open_waste = (open_bins_count as f64) * mean_residual;
        if demand < open_waste * 0.5 && fitting_bins_count > 0 {
            score += (open_waste * 0.5 - demand).min(80.0) * (0.3 + progress * 0.7);
        }
        // mid-stream fresh-bin relief — when several open bins fit
        // and the stream is mid-flow, a fresh bin should only open if the
        // current best fit leaves a large dead residual.
        if fitting_bins_count > 0 && progress >= 0.2 && progress <= 0.8 {
            score += 12.0 * (1.0 - (post_f / cap).min(1.0));
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index — post residual near a small
    // multiple of item_size is likely exactly consumed by future similar items.
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // two-item exact-sum probe
    if next_item_size > 0 && post_residual > 0 && post_residual > next_item_size && mean_residual >= 1.0 {
        let filler = post_residual - next_item_size;
        let dev = (filler as f64 - mean_residual).abs();
        if dev <= 2.0 {
            score -= (2.0 - dev) * 10.0 * (0.5 + progress);
        }
    }

    // greedy-anchor suppression
    if item_size as f64 > cap * 0.55 && bin_residual != bin_capacity && post_residual > 3 {
        let stranded_frac = post_residual as f64 / cap;
        score += stranded_frac * 55.0 * (0.5 + progress);
    }

    // mid-band residual recycling
    if bin_residual >= 21 && bin_residual <= 35 {
        if post_residual == 0 {
            score -= 20.0 + progress * 15.0;
        } else {
            let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
            if reshaped >= 1.0 {
                let dev = (post_residual as f64 - reshaped * mean_residual).abs();
                if dev <= 3.0 {
                    score -= (3.0 - dev) * 4.0 * (0.4 + progress);
                }
            }
        }
    }

    // scarcity-tuned dead-band softening
    if post_residual >= 6 && post_residual <= 12 && next_item_size > 0 && post_residual < next_item_size {
        if (next_item_size - post_residual) as f64 <= mean_residual {
            score -= 4.0 + progress * 6.0;
        }
    }

    // dead-zone harmonic penalty — when multiple bins
    // fit, penalize residuals in the fractional dead zone of the mean
    // residual (likely to strand a sliver no future item consumes).
    if fitting_bins_count > 1 && post_residual > 0 && mean_residual > 1.0 {
        let ratio = post_residual as f64 / mean_residual;
        let frac = ratio - ratio.floor();
        if frac > 0.6 && frac < 0.95 && post_residual < next_item_size.max(1) * 2 {
            score += (frac - 0.6) * 12.0 * progress;
        }
    }

    // fine-grained dead-space ratio — sharpen the
    // baseline with a continuous dead-space term scaled by lookahead
    // usability: post residual that neither chains with the next item
    // nor matches a mean-residual quantum is penalized more strongly.
    if post_residual > 0 {
        let chains = next_item_size > 0 && next_item_size <= post_residual;
        let mut quantum = false;
        if mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 && (post_residual as f64 - k * mean_residual).abs() < 2.0 {
                quantum = true;
            }
        }
        if !chains && !quantum {
            let waste = post_residual as f64 / cap;
            score += waste * 35.0 * (0.4 + progress * 0.8);
        }
    }

    // MUTATION (gen 23): residual-halving probe — a placement that splits the
    // current residual into two roughly equal reusable halves (item centered)
    // maximizes the chance that both halves can host upcoming small items.
    if post_residual > 0 && bin_residual > item_size && post_residual > 4 {
        let waste = post_residual as f64;
        if (waste - (bin_residual as f64 - item_size as f64) / 2.0).abs() <= 2.0 {
            score -= 8.0 * (0.6 + progress * 0.8);
        }
    }

    // MUTATION (gen 23): dead-space ratio gate on new bins — opening a bin
    // whose post residual is a near-exact multiple of the mean residual is
    // cheap (it will be refilled by typical items); otherwise it is dead space.
    if bin_residual == bin_capacity && post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual) / mean_residual;
            score += dev * 10.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 23): endgame filler-hoarding — in the final stretch,
    // residuals that can still host the next item deserve a stronger
    // bonus than mid-stream, since every remaining placement counts.
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (progress - 0.85) * 20.0;
    }

    // MUTATION (gen 23): compaction lookahead pair — when the next item
    // exactly fills this bin AND the item after (approximated by mean
    // residual) would land in the freed space, reward opening-space
    // conservation: prefer placements that leave post residuals matching
    // the mean residual quantum when many bins fit.
    if fitting_bins_count >= 3 && post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 && (post_residual as f64 - k * mean_residual).abs() < 1.0 {
            score -= 6.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 23): late-stream exact-closure gate — near the end,
    // any placement that fully closes a bin must dominate; otherwise
    // residual space is lost permanently.
    if progress > 0.8 && post_residual == 0 && bin_residual != bin_capacity {
        score -= 40.0 * (progress - 0.8) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: exact match of next item into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
    }

    // Dead-space penalty relative to mean residual, scaled by progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let waste_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        let gap_dead = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        if gap_dead {
            let dead_ratio = (next_item_size - post_residual) as f64 / bin_capacity.max(1) as f64;
            score += (40.0 + progress * 30.0) * (1.0 - dead_ratio * 2.0).max(0.0);
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score += 40.0 + progress * 30.0;
        } else {
            score += (40.0 + progress * 30.0) * (1.0 - waste_frac * 1.5).max(0.0);
        }
        if progress > 0.5 && open_bins_count > 4 && mean_residual > (bin_capacity as f64) * 0.4 {
            score -= 20.0 * (progress - 0.5);
        }
    }

    // Prefer filling nearly-full bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // Small-item late-stream bonus
    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Tight-fit refinement — small residual rewards
    if post_residual == 1 || post_residual == 2 || post_residual == 3 {
        score -= 25.0;
    }

    // Penalty for residual just below next item size with multiple options
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count > 1 {
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Pairing with next item when several bins fit
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    // Balanced split reward
    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    // Chain-lookahead — reward residuals that can absorb the next
    // item AND still leave a small (<=5) usable remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after <= 5 {
            score -= 18.0 + (5 - after) as f64 * 2.0;
        }
    }

    // Waste-floor pressure
    if bin_residual == bin_capacity {
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining * 0.1;
        if post_residual as f64 > demand && progress > 0.6 {
            score += (post_residual as f64 - demand) * 0.15 * progress;
        }
    }

    // Near-exact fit sharpening
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let d = post_residual - next_item_size;
        if d <= 2 {
            score -= 10.0;
        }
    }

    // Two-item lookahead — deepen chain reward proportionally.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
    }

    // Fragmentation guard — awkward 6..=12 band
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
        }
    }

    // Scarcity-aware new-bin suppression
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let reusable = post_residual as f64 >= mean_residual * 0.8;
        if !reusable {
            score += 8.0 + progress * 12.0;
        } else if post_residual as f64 > mean_residual * 1.6 {
            score += 4.0;
        }
    }

    // Adaptive fragmentation band — 13..=20 late in the stream.
    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Perfect-chain depth bonus
    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        let scarcity = (3 - fitting_bins_count.min(3)) as f64;
        score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
    }

    // Mean-residual harmonic reuse.
    if post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev < 2.0 {
                score -= (2.0 - dev) * (1.0 + progress);
            }
        }
    }

    // Endgame consolidation — final 10% of the stream.
    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    // Demand-aware new-bin gate
    if bin_residual == bin_capacity {
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > bin_capacity as f64 * 0.5 {
            score += (post_f - bin_capacity as f64 * 0.5) * 0.25;
        }
    }

    // Tri-item chain probe
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
    }

    // Sharpened endgame exact-fit bonus
    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    // MUTATION: complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    // MUTATION: dead-space floor sharpening — almost-chain traps
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
    }

    // MUTATION: scarcity-weighted perfect fit
    if post_residual == 0 && fitting_bins_count <= 2 {
        score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
    }

    // MUTATION (gen 16): residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // MUTATION (gen 16): large-item pre-reservation
    if next_item_size as f64 > bin_capacity as f64 * 0.4
        && post_residual > 0
        && post_residual < next_item_size
    {
        score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
    }

    // MUTATION (gen 16): new-bin fill-forecast
    if bin_residual == bin_capacity {
        let remaining = total_items.saturating_sub(step_index) as f64;
        let forecast = mean_residual * remaining.min(50.0);
        let cap_f = bin_capacity as f64;
        if forecast < cap_f * 0.8 {
            let shortfall = (cap_f * 0.8 - forecast) / cap_f;
            score += shortfall * 60.0 * (0.4 + progress);
        }
    }

    // MUTATION (gen 17): chain-continuity refinement
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after <= 5 && next_item_size <= 15 {
            score -= (5 - after) as f64 * 3.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 17): bin-load balance coupling
    if fitting_bins_count > 1 && post_residual > 0 && mean_residual > 1.0 {
        let ratio = post_residual as f64 / mean_residual;
        let frac = ratio - ratio.floor();
        if frac > 0.6 && frac < 0.95 && post_residual < next_item_size.max(1) * 2 {
            score += (frac - 0.6) * 12.0 * progress;
        }
    }

    // MUTATION (gen 17): early-stream capacity preservation
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 6.0 * (0.2 - progress) * 50.0 * (post_residual as f64 / bin_capacity.max(1) as f64);
    }

    // MUTATION (gen 17): next-item stranding guard
    if next_item_size > 0
        && post_residual > 0
        && post_residual < next_item_size
        && bin_residual >= next_item_size
        && fitting_bins_count <= 2
    {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // MUTATION (gen 18): mid-band residual recycling
    if bin_residual >= 21 && bin_residual <= 35 {
        if post_residual == 0 {
            score -= 20.0 + progress * 15.0;
        } else {
            let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
            if reshaped >= 1.0 {
                let dev = (post_residual as f64 - reshaped * mean_residual).abs();
                if dev <= 3.0 {
                    score -= (3.0 - dev) * 4.0 * (0.4 + progress);
                }
            }
        }
    }

    // MUTATION (gen 18): greedy-anchor suppression
    if item_size as f64 > bin_capacity as f64 * 0.55
        && bin_residual != bin_capacity
        && post_residual > 3
    {
        let stranded_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        score += stranded_frac * 55.0 * (0.5 + progress);
    }

    // MUTATION (gen 18): two-item exact-sum probe
    if next_item_size > 0
        && post_residual > 0
        && post_residual > next_item_size
        && mean_residual >= 1.0
    {
        let filler = post_residual - next_item_size;
        let dev = (filler as f64 - mean_residual).abs();
        if dev <= 2.0 {
            score -= (2.0 - dev) * 10.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 18): scarcity-tuned dead-band softening
    if post_residual >= 6 && post_residual <= 12 && next_item_size > 0 && post_residual < next_item_size {
        if (next_item_size - post_residual) as f64 <= mean_residual {
            score -= 4.0 + progress * 6.0;
        }
    }

    // MUTATION (gen 22): residual-halving probe — a placement that splits the
    // current residual into two roughly equal reusable halves (item centered)
    // maximizes the chance that both halves can host upcoming small items.
    if post_residual > 0 && bin_residual > item_size && post_residual > 4 {
        let waste = post_residual as f64;
        if (waste - (bin_residual as f64 - item_size as f64) / 2.0).abs() <= 2.0 {
            score -= 8.0 * (0.6 + progress * 0.8);
        }
    }

    // MUTATION (gen 22): dead-space ratio gate on new bins
    if bin_residual == bin_capacity && post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual) / mean_residual;
            score += dev * 10.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 22): endgame filler-hoarding
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (progress - 0.85) * 20.0;
    }

    // MUTATION (gen 23): residual-continuation index — a placement is most
    // valuable when its post residual can host the next item AND the leftover
    // after that placement is itself a near-harmonic of the mean residual,
    // indicating a self-sustaining packing chain rather than a one-off fit.
    if next_item_size > 0 && post_residual > next_item_size && mean_residual > 1.0 {
        let after = post_residual - next_item_size;
        if after > 0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (after as f64 - k * mean_residual).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 14.0 * (0.5 + progress);
                }
            }
        }
    }

    // MUTATION (gen 23): dead-space liquidity gate — penalize new bins whose
    // post residual falls into a "liquidity trap": too small to host typical
    // items (below mean residual minus tolerance) but too large to count as
    // a near-perfect fit. These residuals are statistically dead space.
    if bin_residual == bin_capacity && post_residual > 0 && mean_residual > 1.0 {
        let lo = (mean_residual * 0.5).floor();
        if (post_residual as f64) < lo && post_residual > 2 {
            score += (lo - post_residual as f64) * 6.0 * (0.6 + progress);
        }
    }

    // MUTATION (gen 23): progressive fill-depth coupling — reward placements
    // that push a bin deeper than the running average fill level, converting
    // residual variance into compacted capacity; scale by remaining demand.
    if bin_residual != bin_capacity && post_residual > 0 {
        let avg_fill = bin_capacity as f64 - mean_residual;
        let new_fill = bin_capacity as f64 - post_residual as f64;
        if new_fill > avg_fill {
            let depth = (new_fill - avg_fill) / bin_capacity.max(1) as f64;
            score -= depth * 18.0 * (0.4 + progress * 0.8);
        }
    }

    // MUTATION (gen 23): scarcity-aware chain handoff — when few bins can
    // host the NEXT item, protect the bin that remains compatible with the
    // current placement so the chain is not broken by a greedy fit.
    if fitting_bins_count <= 3
        && next_item_size > 0
        && post_residual >= next_item_size
        && post_residual > 0
    {
        let scarcity = (4 - fitting_bins_count.min(4)) as f64;
        score -= scarcity * 5.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        // Two-step anticipation: next item nearly fills this bin exactly
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            // small-filler chain reinforcement
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        // Perfect-chain depth bonus: bin closes with zero waste in two steps
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        // Tight chain refinement when few bins fit
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        // Two-item lookahead: remainder still larger than half the mean residual
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        // Tri-item chain probe
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        // Harmonic reuse — reward residuals near multiples of mean residual
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        // Compaction squeeze
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        // Almost-chain trap — next item fits but leaves a sliver
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        // Dead-space ratio coupling
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; leftover likely wasted
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        // Large-item stranding — big next items leave this bin stranded
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        // chain destruction guard
        if next_item_size > 0
            && post_residual > 0
            && bin_residual >= next_item_size
            && fitting_bins_count <= 2
        {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        // Demand-aware new-bin gate
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        // Fresh-bin fill-forecast
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        // early-stream capacity preservation
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        // waste-floor compaction
        let open_waste = (open_bins_count as f64) * mean_residual;
        if demand < open_waste * 0.5 && fitting_bins_count > 0 {
            score += (open_waste * 0.5 - demand).min(80.0) * (0.3 + progress * 0.7);
        }
        // mid-stream fresh-bin relief
        if fitting_bins_count > 0 && progress >= 0.2 && progress <= 0.8 {
            score += 12.0 * (1.0 - (post_f / cap).min(1.0));
        }
        // MUTATION (gen 24): fresh-bin demand-density gate — open a new bin
        // only when the remaining stream's demand density (mean residual per
        // remaining item) suggests the fresh space will actually be consumed.
        let remaining_f = remaining;
        if remaining_f > 0.0 && fitting_bins_count > 0 {
            let density = mean_residual / remaining_f.sqrt().max(1.0);
            if post_f > density * 3.0 {
                score += (post_f - density * 3.0) * 0.2 * (0.5 + progress);
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // two-item exact-sum probe
    if next_item_size > 0 && post_residual > 0 && post_residual > next_item_size && mean_residual >= 1.0 {
        let filler = post_residual - next_item_size;
        let dev = (filler as f64 - mean_residual).abs();
        if dev <= 2.0 {
            score -= (2.0 - dev) * 10.0 * (0.5 + progress);
        }
    }

    // greedy-anchor suppression
    if item_size as f64 > cap * 0.55 && bin_residual != bin_capacity && post_residual > 3 {
        let stranded_frac = post_residual as f64 / cap;
        score += stranded_frac * 55.0 * (0.5 + progress);
    }

    // mid-band residual recycling
    if bin_residual >= 21 && bin_residual <= 35 {
        if post_residual == 0 {
            score -= 20.0 + progress * 15.0;
        } else {
            let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
            if reshaped >= 1.0 {
                let dev = (post_residual as f64 - reshaped * mean_residual).abs();
                if dev <= 3.0 {
                    score -= (3.0 - dev) * 4.0 * (0.4 + progress);
                }
            }
        }
    }

    // scarcity-tuned dead-band softening
    if post_residual >= 6 && post_residual <= 12 && next_item_size > 0 && post_residual < next_item_size {
        if (next_item_size - post_residual) as f64 <= mean_residual {
            score -= 4.0 + progress * 6.0;
        }
    }

    // dead-zone harmonic penalty
    if fitting_bins_count > 1 && post_residual > 0 && mean_residual > 1.0 {
        let ratio = post_residual as f64 / mean_residual;
        let frac = ratio - ratio.floor();
        if frac > 0.6 && frac < 0.95 && post_residual < next_item_size.max(1) * 2 {
            score += (frac - 0.6) * 12.0 * progress;
        }
    }

    // fine-grained dead-space ratio
    if post_residual > 0 {
        let chains = next_item_size > 0 && next_item_size <= post_residual;
        let mut quantum = false;
        if mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 && (post_residual as f64 - k * mean_residual).abs() < 2.0 {
                quantum = true;
            }
        }
        if !chains && !quantum {
            let waste = post_residual as f64 / cap;
            score += waste * 35.0 * (0.4 + progress * 0.8);
        }
    }

    // MUTATION (gen 23): residual-halving probe
    if post_residual > 0 && bin_residual > item_size && post_residual > 4 {
        let waste = post_residual as f64;
        if (waste - (bin_residual as f64 - item_size as f64) / 2.0).abs() <= 2.0 {
            score -= 8.0 * (0.6 + progress * 0.8);
        }
    }

    // MUTATION (gen 23): dead-space ratio gate on new bins
    if bin_residual == bin_capacity && post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual) / mean_residual;
            score += dev * 10.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 23): endgame filler-hoarding
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (progress - 0.85) * 20.0;
    }

    // MUTATION (gen 23): compaction lookahead pair
    if fitting_bins_count >= 3 && post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 && (post_residual as f64 - k * mean_residual).abs() < 1.0 {
            score -= 6.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 23): late-stream exact-closure gate
    if progress > 0.8 && post_residual == 0 && bin_residual != bin_capacity {
        score -= 40.0 * (progress - 0.8) * 5.0;
    }

    // MUTATION (gen 24): waste-slope lookahead — prefer placements whose post
    // residual, combined with the mean residual, forms a near-exact pair
    // (post + mean ≈ next_item * k), signaling a two-step exact closure that
    // eliminates dead space rather than merely deferring it.
    if post_residual > 0 && next_item_size > 0 && mean_residual > 1.0 {
        let pair = post_residual as f64 + mean_residual;
        let k = (pair / next_item_size as f64).round();
        if k >= 1.0 {
            let dev = (pair - k * next_item_size as f64).abs();
            if dev <= 1.5 {
                score -= (1.5 - dev) * 9.0 * (0.5 + progress);
            }
        }
    }

    // MUTATION (gen 24): dead-space slope sharpening — continuous quadratic
    // penalty on post residuals that neither chain nor match a quantum,
    // replacing the flat ratio penalty with a convex curve so mid-sized
    // dead residuals are punished proportionally more.
    if post_residual > 0 {
        let chains = next_item_size > 0 && next_item_size <= post_residual;
        let mut quantum = false;
        if mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 && (post_residual as f64 - k * mean_residual).abs() < 2.0 {
                quantum = true;
            }
        }
        if !chains && !quantum {
            let waste = post_residual as f64 / cap;
            score += waste * waste * 45.0 * (0.4 + progress * 0.8);
        }
    }

    // MUTATION (gen 24): scarcity-scaled chain tightening — when only one
    // open bin can host the item and the next item fits the post residual
    // exactly, force the closure with a decisive bonus to avoid leaving
    // the last usable residual stranded.
    if fitting_bins_count == 1 && post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0 + progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        // compaction-ratio coupling — prefer post residual matching the
        // next item's companion band (near item_size) for filler reuse.
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        // two-filler horizon — remainder should still hold the mean-residual
        // filler after the next item, enabling tri-item closure.
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        // MUTATION: chain-depth consolidation — when the post residual can
        // absorb the next item AND the leftover is a near multiple of the
        // mean residual, this placement closes more of the bin per step.
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (after as f64 - k * mean_residual).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        // complement gap rescue — a future filler may still close this bin.
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        // MUTATION: near-miss rescue — if the gap to the next item equals a
        // plausible small item size (1..=12), the bin may still be closed by
        // the following item; soften the stranding penalty.
        if gap >= 1 && gap <= 12 && progress > 0.3 {
            score -= (12 - gap) as f64 * 1.2 * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        // fresh-bin seeding bonus — a new bin is cheap when the current item
        // is large and the remaining stream is long.
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        // MUTATION: dead-space ratio gate — a fresh bin whose post residual
        // is a near-exact multiple of the mean residual is cheap (it will be
        // refilled by typical items); otherwise it is dead space.
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_f - k * mean_residual) / mean_residual;
                score += dev * 10.0 * (0.5 + progress);
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        // tight-fit sharpening — reward near-quantum residuals.
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        // MUTATION: residual-halving probe — a placement that splits the
        // residual into two roughly equal reusable halves maximizes the
        // chance both halves can host upcoming small items.
        if post_residual > 4 && bin_residual > item_size {
            let half_target = (bin_residual as f64 - item_size as f64) / 2.0;
            if (post_residual as f64 - half_target).abs() <= 2.0 {
                score -= 8.0 * (0.6 + progress * 0.8);
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // MUTATION: endgame filler-hoarding — residuals that can still host the
    // next item deserve a stronger bonus in the final stretch.
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (progress - 0.85) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: exact match of next item into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
    }

    // Dead-space penalty relative to mean residual, scaled by progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let waste_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        let gap_dead = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        if gap_dead {
            let dead_ratio = (next_item_size - post_residual) as f64 / bin_capacity.max(1) as f64;
            score += (40.0 + progress * 30.0) * (1.0 - dead_ratio * 2.0).max(0.0);
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score += 40.0 + progress * 30.0;
        } else {
            score += (40.0 + progress * 30.0) * (1.0 - waste_frac * 1.5).max(0.0);
        }
        if progress > 0.5 && open_bins_count > 4 && mean_residual > (bin_capacity as f64) * 0.4 {
            score -= 20.0 * (progress - 0.5);
        }
    }

    // Prefer filling nearly-full bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // Small-item late-stream bonus
    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Tight-fit refinement — small residual rewards
    if post_residual == 1 || post_residual == 2 || post_residual == 3 {
        score -= 25.0;
    }

    // Penalty for residual just below next item size with multiple options
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count > 1 {
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Pairing with next item when several bins fit
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    // Balanced split reward
    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    // Chain-lookahead — reward residuals that can absorb the next
    // item AND still leave a small (<=5) usable remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after <= 5 {
            score -= 18.0 + (5 - after) as f64 * 2.0;
        }
    }

    // Waste-floor pressure
    if bin_residual == bin_capacity {
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining * 0.1;
        if post_residual as f64 > demand && progress > 0.6 {
            score += (post_residual as f64 - demand) * 0.15 * progress;
        }
    }

    // Near-exact fit sharpening
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let d = post_residual - next_item_size;
        if d <= 2 {
            score -= 10.0;
        }
    }

    // Two-item lookahead — deepen chain reward proportionally.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
    }

    // Fragmentation guard — awkward 6..=12 band
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
        }
    }

    // Scarcity-aware new-bin suppression
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let reusable = post_residual as f64 >= mean_residual * 0.8;
        if !reusable {
            score += 8.0 + progress * 12.0;
        } else if post_residual as f64 > mean_residual * 1.6 {
            score += 4.0;
        }
    }

    // Adaptive fragmentation band — 13..=20 late in the stream.
    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Perfect-chain depth bonus
    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        let scarcity = (3 - fitting_bins_count.min(3)) as f64;
        score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
    }

    // Mean-residual harmonic reuse.
    if post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev < 2.0 {
                score -= (2.0 - dev) * (1.0 + progress);
            }
        }
    }

    // Endgame consolidation — final 10% of the stream.
    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    // Demand-aware new-bin gate
    if bin_residual == bin_capacity {
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > bin_capacity as f64 * 0.5 {
            score += (post_f - bin_capacity as f64 * 0.5) * 0.25;
        }
    }

    // Tri-item chain probe
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
    }

    // Sharpened endgame exact-fit bonus
    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    // MUTATION: complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    // MUTATION: dead-space floor sharpening — almost-chain traps
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
    }

    // MUTATION: scarcity-weighted perfect fit
    if post_residual == 0 && fitting_bins_count <= 2 {
        score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
    }

    // MUTATION (gen 16): residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // MUTATION (gen 16): large-item pre-reservation
    if next_item_size as f64 > bin_capacity as f64 * 0.4
        && post_residual > 0
        && post_residual < next_item_size
    {
        score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
    }

    // MUTATION (gen 16): new-bin fill-forecast
    if bin_residual == bin_capacity {
        let remaining = total_items.saturating_sub(step_index) as f64;
        let forecast = mean_residual * remaining.min(50.0);
        let cap_f = bin_capacity as f64;
        if forecast < cap_f * 0.8 {
            let shortfall = (cap_f * 0.8 - forecast) / cap_f;
            score += shortfall * 60.0 * (0.4 + progress);
        }
    }

    // MUTATION (gen 17): chain-continuity refinement
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after <= 5 && next_item_size <= 15 {
            score -= (5 - after) as f64 * 3.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 17): bin-load balance coupling
    if fitting_bins_count > 1 && post_residual > 0 && mean_residual > 1.0 {
        let ratio = post_residual as f64 / mean_residual;
        let frac = ratio - ratio.floor();
        if frac > 0.6 && frac < 0.95 && post_residual < next_item_size.max(1) * 2 {
            score += (frac - 0.6) * 12.0 * progress;
        }
    }

    // MUTATION (gen 17): early-stream capacity preservation
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 6.0 * (0.2 - progress) * 50.0 * (post_residual as f64 / bin_capacity.max(1) as f64);
    }

    // MUTATION (gen 17): next-item stranding guard
    if next_item_size > 0
        && post_residual > 0
        && post_residual < next_item_size
        && bin_residual >= next_item_size
        && fitting_bins_count <= 2
    {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // MUTATION (gen 18): mid-band residual recycling
    if bin_residual >= 21 && bin_residual <= 35 {
        if post_residual == 0 {
            score -= 20.0 + progress * 15.0;
        } else {
            let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
            if reshaped >= 1.0 {
                let dev = (post_residual as f64 - reshaped * mean_residual).abs();
                if dev <= 3.0 {
                    score -= (3.0 - dev) * 4.0 * (0.4 + progress);
                }
            }
        }
    }

    // MUTATION (gen 18): greedy-anchor suppression
    if item_size as f64 > bin_capacity as f64 * 0.55
        && bin_residual != bin_capacity
        && post_residual > 3
    {
        let stranded_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        score += stranded_frac * 55.0 * (0.5 + progress);
    }

    // MUTATION (gen 18): two-item exact-sum probe
    if next_item_size > 0
        && post_residual > 0
        && post_residual > next_item_size
        && mean_residual >= 1.0
    {
        let filler = post_residual - next_item_size;
        let dev = (filler as f64 - mean_residual).abs();
        if dev <= 2.0 {
            score -= (2.0 - dev) * 10.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 18): scarcity-tuned dead-band softening
    if post_residual >= 6 && post_residual <= 12 && next_item_size > 0 && post_residual < next_item_size {
        if (next_item_size - post_residual) as f64 <= mean_residual {
            score -= 4.0 + progress * 6.0;
        }
    }

    // MUTATION (gen 22): residual-halving probe — a placement that splits the
    // current residual into two roughly equal reusable halves (item centered)
    // maximizes the chance that both halves can host upcoming small items.
    if post_residual > 0 && bin_residual > item_size && post_residual > 4 {
        let waste = post_residual as f64;
        if (waste - (bin_residual as f64 - item_size as f64) / 2.0).abs() <= 2.0 {
            score -= 8.0 * (0.6 + progress * 0.8);
        }
    }

    // MUTATION (gen 22): dead-space ratio gate on new bins
    if bin_residual == bin_capacity && post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual) / mean_residual;
            score += dev * 10.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 22): endgame filler-hoarding — in the final stretch,
    // residuals that can still host the next item deserve a stronger
    // bonus than mid-stream, since every remaining placement counts.
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (progress - 0.85) * 20.0;
    }

    // MUTATION (gen 23): dead-space ratio sharpening — penalize placements
    // whose post residual is unusable dead space relative to the item size
    // distribution. If post_residual is smaller than both the next item and
    // the mean residual, it is likely stranded forever.
    if post_residual > 0 && mean_residual > 1.0 {
        let pr = post_residual as f64;
        let mr = mean_residual;
        let stranded = pr < mr * 0.45
            && (next_item_size == 0 || pr < next_item_size as f64);
        if stranded {
            score += (mr * 0.45 - pr) * (1.5 + progress * 2.5);
        }
    }

    // MUTATION (gen 23): open-bin saturation pressure — when many bins are
    // open but few can fit the item, prefer the bin that leaves the most
    // "next-item-compatible" residual; when many bins fit, prefer the
    // tightest one (already covered) plus a mild coupling to open_bins_count
    // to discourage spreading load across too many partially-filled bins.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let scarcity = (open_bins_count as f64 / 8.0).min(1.0);
        score -= (post_residual - next_item_size) as f64 * 0.1 * scarcity;
    }

    // MUTATION (gen 23): dual-item fill probe — reward placements where the
    // post residual plus a typical (mean-residual-sized) filler item lands
    // close to a perfect fill, i.e. the bin can be finished off quickly.
    if post_residual > 0 && mean_residual > 1.0 && progress > 0.4 {
        let pr = post_residual as f64;
        let near_full = (pr - mean_residual).abs() <= 3.0
            || (pr - mean_residual * 2.0).abs() <= 3.0;
        if near_full && pr < bin_capacity as f64 * 0.35 {
            score -= (3.0 - (pr - (pr / mean_residual).round() * mean_residual).abs())
                * 5.0
                * (0.5 + progress);
        }
    }

    // MUTATION (gen 23): new-bin threshold tightening — only open a fresh bin
    // when the best existing option leaves clearly worse residual; scale the
    // fresh-bin penalty with how reusable the post residual actually is.
    if bin_residual == bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let cap_f = bin_capacity as f64;
        let reusability = if next_item_size > 0 && pr >= next_item_size as f64 {
            1.0
        } else if next_item_size > 0 {
            0.0
        } else {
            (pr / (mean_residual.max(1.0))).min(1.0)
        };
        score += cap_f * 0.06 * (1.0 - reusability) * (0.5 + progress);
    }

    score
}

