        }
    }

    // dead-zone harmonic penalty
    if fitting_bins_count > 1 && post_residual > 0 && mean_residual > 1.0 {
        let ratio = post_residual as f64 / mean_residual;
        let frac = ratio - ratio.floor();
        if frac > 0.6 && frac < 0.95 && post_residual < next_item_size.max(1) * 2 {
            score += (frac - 0.6) * 12.0 * progress;
        }
    }

    // fine-grained dead-space ratio
    if post_residual > 0 {
        let chains = next_item_size > 0 && next_item_size <= post_residual;
        let mut quantum = false;
        if mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 && (post_residual as f64 - k * mean_residual).abs() < 2.0 {
                quantum = true;
            }
        }
        if !chains && !quantum {
            let waste = post_residual as f64 / cap;
            score += waste * 35.0 * (0.4 + progress * 0.8);
        }
    }

    // residual-halving probe
    if post_residual > 0 && bin_residual > item_size && post_residual > 4 {
        let waste = post_residual as f64;
        if (waste - (bin_residual as f64 - item_size as f64) / 2.0).abs() <= 2.0 {
            score -= 8.0 * (0.6 + progress * 0.8);
        }
    }

    // dead-space ratio gate on new bins
    if bin_residual == bin_capacity && post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual) / mean_residual;
            score += dev * 10.0 * (0.5 + progress);
        }
    }

    // endgame filler-hoarding
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (progress - 0.85) * 20.0;
    }

    // compaction lookahead pair
    if fitting_bins_count >= 3 && post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 && (post_residual as f64 - k * mean_residual).abs() < 1.0 {
            score -= 6.0 * (0.5 + progress);
        }
    }

    // late-stream exact-closure gate
    if progress > 0.8 && post_residual == 0 && bin_residual != bin_capacity {
        score -= 40.0 * (progress - 0.8) * 5.0;
    }

    // MUTATION (gen 24): dual-fit anticipation — when the next item fits AND
    // the resulting remainder can also host a typical (mean-residual-sized)
    // item, reward placements that preserve two-step fillability; this
    // couples fine-grained residual fitting with lookahead anticipation.
    if next_item_size > 0 && post_residual >= next_item_size && mean_residual > 1.0 {
        let after = post_residual - next_item_size;
        if after as f64 >= mean_residual * 0.9 && after > 0 {
            score -= (after as f64 - mean_residual * 0.9).min(6.0) * 3.0 * (0.4 + progress);
        }
    }

    // MUTATION (gen 24): dead-space decay coupling — penalize large unusable
    // remainders more sharply when few bins fit, since stranded space in
    // scarce options is the primary source of wasted bins.
    if post_residual > 0 && next_item_size > post_residual && fitting_bins_count <= 3 {
        let waste = post_residual as f64 / cap;
        score += waste * 45.0 * (1.0 - progress * 0.5);
    }

    // MUTATION (gen 24): tight-bin priority sharpening — when multiple bins
    // fit, break ties toward the bin whose post residual best matches the
    // next item's size, avoiding near-miss placements that strand slivers.
    if fitting_bins_count > 1 && next_item_size > 0 && post_residual >= next_item_size {
        let miss = post_residual - next_item_size;
        if miss > 0 && miss <= 2 {
            score -= 6.0;
        } else if miss > 12 {
            score += miss as f64 * 0.35;
        }
    }

    score
}

