        let dev = (filler as f64 - mean_residual).abs();
        if dev <= 2.0 {
            score -= (2.0 - dev) * 10.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 18): scarcity-tuned dead-band softening
    if post_residual >= 6 && post_residual <= 12 && next_item_size > 0 && post_residual < next_item_size {
        if (next_item_size - post_residual) as f64 <= mean_residual {
            score -= 4.0 + progress * 6.0;
        }
    }

    // MUTATION (gen 22): residual-halving probe
    if post_residual > 0 && bin_residual > item_size && post_residual > 4 {
        let waste = post_residual as f64;
        if (waste - (bin_residual as f64 - item_size as f64) / 2.0).abs() <= 2.0 {
            score -= 8.0 * (0.6 + progress * 0.8);
        }
    }

    // MUTATION (gen 22): dead-space ratio gate on new bins
    if bin_residual == bin_capacity && post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual) / mean_residual;
            score += dev * 10.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 22): endgame filler-hoarding
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (progress - 0.85) * 20.0;
    }

    // MUTATION (gen 25): dead-space-ratio refinement — the diagnosed weakness is
    // dead space. Sharpen the base waste penalty by coupling it to the bin's
    // remaining fraction: wasting space in an almost-empty bin is far worse
    // than in a nearly-full one, so scale the raw post-residual term by how
    // much of the bin is still free after placement.
    if post_residual > 0 {
        let free_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        if free_frac > 0.5 {
            score += (free_frac - 0.5) * 30.0 * (0.4 + progress);
        }
    }

    // MUTATION (gen 25): dual-item viability probe — favor placements whose
    // post residual can host the next item AND whose leftover after that
    // chain is itself close to a reusable quantum (mean residual), so the
    // bin keeps cycling instead of stranding a dead remainder.
    if next_item_size > 0 && post_residual > next_item_size && mean_residual > 1.0 {
        let after = post_residual - next_item_size;
        if after > 0 {
            let dev = ((after as f64) / mean_residual - (after as f64 / mean_residual).round()).abs() * mean_residual;
            if dev <= 1.0 {
                score -= (1.0 - dev) * 9.0 * (0.5 + progress);
            }
        }
    }

    // MUTATION (gen 25): new-bin threshold tightening — only open a fresh bin
    // when no open bin offers a residual that the next item could chain into;
