    // chain-friendly the best existing option would be.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5 * (0.5 + progress);
        }
    }

    score
}

