    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        let depth = (after as f64 / mean_residual.max(1.0)).floor().min(4.0);
        if depth >= 1.0 {
            score -= depth * depth * 3.0 * (0.4 + progress);
        }
    }

    // MUTATION (gen 25): residual utilization gate — when several bins fit,
    // prefer the one whose post residual is smallest but still usable by the
