        }
    }

    // Dead-space ratio gate on new bins
    if bin_residual == bin_capacity && post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual) / mean_residual;
            score += dev * 10.0 * (0.5 + progress);
        }
    }

    // Endgame filler-hoarding
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (progress - 0.85) * 20.0;
    }

    // MUTATION (gen 25): dead-space ratio gate sharpened by scarcity —
    // when few bins can host the item, a fresh bin whose post residual
    // deviates from a multiple of the mean residual is far more costly,
    // since it will likely never be refilled. Scale the penalty by the
    // inverse of fitting availability.
