        let scarcity = (4 - fitting_bins_count.min(4)) as f64 / 4.0; // 0..=0.75
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = ((post_residual as f64 - k * mean_residual) / mean_residual).abs();
            score += dev * 14.0 * (0.5 + progress) * (0.4 + scarcity);
        } else {
            // post_residual below one mean-residual unit: pure dead space
            score += (post_residual as f64) * 0.35 * (0.5 + progress) * (0.5 + scarcity);
