    }

    // MUTATION (gen 25): chain-depth-aware new-bin suppression — opening a
    // fresh bin while the next item could still chain inside an existing
    // bin's post residual wastes an entire capacity unit. Penalize the
    // fresh bin proportionally to how deep the existing chain would run
    // (how many consecutive next-sized items the residual could absorb).
    if bin_residual == bin_capacity && next_item_size > 0 && post_residual > 0 {
        let chain_depth = post_residual / next_item_size.max(1);
        if chain_depth >= 2 {
            score += (chain_depth.min(4) as f64) * 9.0 * (0.4 + progress);
        }
    }

    // MUTATION (gen 25): residual-vs-remainder tradeoff — when placing the
    // item leaves a remainder after the next item that is itself too small
    // for the mean item, the chain dies there. Reward placements whose
    // post-chain remainder stays above the mean residual instead.
    if next_item_size > 0 && post_residual > next_item_size && mean_residual > 1.0 {
        let after = post_residual - next_item_size;
        if (after as f64) < mean_residual * 0.5 && after > 0 {
            score += (mean_residual * 0.5 - after as f64) * 3.0 * (0.5 + progress);
        } else if (after as f64) >= mean_residual {
            score -= 4.0 * (0.4 + progress);
        }
    }

    // MUTATION (gen 25): open-bin pool pressure — late in the stream with
    // many open bins, slightly favor placements that zero out residuals
    // (closing bins) over spreading load, to consolidate dead space.
    if progress > 0.6 && open_bins_count > 5 && post_residual == 0 {
        score -= 10.0 + (open_bins_count.min(12) as f64) * 1.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
