    // their mean residual is low, prefer placements that keep post_residual
    // tight (below half the mean residual) to avoid spreading fragmentation;
    // when the pool is small, allow looser fits to preserve flexibility.
    if open_bins_count > 3 && mean_residual > 1.0 && post_residual > 0 {
        let half_mean = mean_residual * 0.5;
        if post_residual as f64 <= half_mean {
            score -= (half_mean - post_residual as f64) * 6.0 * (0.5 + progress);
        } else if open_bins_count > 8 && post_residual as f64 > mean_residual * 2.0 {
            score += (post_residual as f64 - mean_residual * 2.0) * 0.8 * progress;
