    // the item is large relative to capacity or no open bin leaves a tight
    // remainder; a fresh bin whose post residual exceeds the next item by a
    // wide margin wastes capacity the open pool could have absorbed.
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let slack = post_residual as f64 - next_item_size as f64;
        if slack > 8.0 {
            score += slack * (0.6 + progress * 0.8);
        }
    }

    score
}

