            score -= (0.12 - dead_frac) * 40.0 * (0.5 + progress);
        }
        // Coupled with open-bin availability: with many open bins,
        // opening fresh dead space is worse.
        if open_bins_count > 3 {
            score += dead_frac * 6.0 * ((open_bins_count - 3) as f64).min(10.0);
        }
    }

    // MUTATION (gen 26): two-item sum chain — reward placements where the
    // next item fits exactly into the post residual together with the
    // current item, i.e. item_size + next_item_size == bin_residual.
    // This is a perfect two-item closure and deserves a strong bonus.
    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 15.0 + progress * 10.0;
    }

    // MUTATION (gen 26): residual floor sweep — residuals that are one
    // item short of the next item (post + 1..=2 == next) are the worst
    // traps late in the stream; penalize them harder than the generic
    // stranding guard, but only when alternatives exist.
    if next_item_size > 0
        && post_residual > 0
        && post_residual < next_item_size
        && next_item_size - post_residual <= 2
        && fitting_bins_count > 1
        && progress > 0.4
    {
        score += 10.0 + (2 - (next_item_size - post_residual)) as f64 * 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues that form "useful" classes
    // (multiples of 10, or large enough to hold common small items) are less penalized.
    let pr = post_residual;
    let class_penalty = if pr == 0 {
        -30.0 // perfect fit is ideal
    } else if pr % 10 == 0 {
        -8.0 // round residual: likely reusable by decimal-distributed items
    } else if pr >= 10 {
        // fractional dead space: penalize by how far from the nearest multiple of 10
        let frac = (pr % 10) as f64;
        -2.0 + 0.6 * frac
    } else {
        // tiny unusable sliver (< 10): strong penalty, scaled by how tiny
        12.0 + (10 - pr) as f64 * 1.5
    };
    score += class_penalty;

    // Integer-division threshold coupling: post_residual / item_size ratio
    // rewards bins where the item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Lookahead harmonic check: does post_residual admit the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits: bonus proportional to how snugly it would fit
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 - 0.15 * slack;
            // harmonic bonus if both post_residual and next_item_size share a gcd-like class
            if pr % 10 == next_item_size % 10 {
                score -= 3.0;
            }
        } else {
            // next item won't fit here: mild penalty, worse if residual is small
            score += 2.0 + 0.05 * (next_item_size - pr).min(40) as f64;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin and stranding this residual.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        // extra reward if the placement leaves a "classy" residual
        if pr % 10 == 0 || pr == 0 {
            score -= 5.0;
        }
    } else if fitting_bins_count > 1 {
        // many options: prefer tightest fit (already via post_residual), nudge competition
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a new bin is only attractive early in the
    // stream or when mean residual across open bins is already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // base cost of a fresh bin
        score = 55.0;
        // cheaper to open bins early (amortization), costlier late
        score -= 20.0 * (1.0 - progress);
        // if existing bins are fragmented (low mean residual), a new bin is more justified
        score -= 25.0 * (1.0 - fragmentation);
        // if the item is large relative to capacity, prefer fresh bin slightly
        score -= 0.1 * item_size as f64;
        // if many bins already open, discourage proliferation
        score += 1.5 * open_bins_count as f64;
        // if next item is small, a fresh bin preserves a big usable residual for it
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 8.0;
        }
    }

    // Mild global pressure: when few bins remain usable, tighten scoring variance
    if fitting_bins_count <= 2 {
        score *= 0.95;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
