    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        // chain-continuity refinement for small next items
        if after <= 5 && next_item_size <= 15 {
            score -= (5 - after) as f64 * 3.0 * (0.5 + progress);
        }
        // MUTATION: triple-chain probe — after hosting the next item, the
        // leftover should still host a typical item (mean_residual), keeping
        // the bin cycling toward zero waste.
        if after > 0 && mean_residual >= 1.0 && after as f64 >= mean_residual * 0.9 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.4 + progress);
            }
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        // scarcity-tuned dead-band softening
        if post_residual >= 6 && post_residual <= 12 && gap as f64 <= mean_residual {
            score -= 4.0 + progress * 6.0;
        }
        // next-item stranding guard on scarce options
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        // MUTATION: near-miss rescue — if a small top-up item (<= gap + 2)
        // could plausibly arrive, soften the penalty slightly so the bin is
        // not abandoned while still nearly chainable.
        if gap > 4 && gap <= 10 && progress > 0.4 && post_residual >= 5 {
            score -= (10.0 - gap as f64) * 0.8 * progress;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        // early-stream capacity preservation
        if progress < 0.2 {
            score += 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        // dead-space multiple gate
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_f - k * mean_residual) / mean_residual;
                score += dev * 10.0 * (0.5 + progress);
            }
        }
        // MUTATION: first-fit-of-stream damping — a fresh bin opened while
        // many bins are already open and the stream is mid-flight tends to
        // strand the donors' residuals; scale the penalty with open count.
        if open_bins_count > 3 && progress > 0.25 {
            score += (open_bins_count.min(12) as f64 - 3.0) * 3.0 * progress;
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Two-item exact-sum probe
    if next_item_size > 0 && post_residual > next_item_size && mean_residual >= 1.0 {
        let filler = post_residual - next_item_size;
        let dev = (filler as f64 - mean_residual).abs();
        if dev <= 2.0 {
            score -= (2.0 - dev) * 10.0 * (0.5 + progress);
        }
    }

    // Mid-band residual recycling
    if bin_residual >= 21 && bin_residual <= 35 {
        if post_residual == 0 {
            score -= 20.0 + progress * 15.0;
        } else {
            let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
            if reshaped >= 1.0 {
                let dev = (post_residual as f64 - reshaped * mean_residual).abs();
                if dev <= 3.0 {
                    score -= (3.0 - dev) * 4.0 * (0.4 + progress);
                }
            }
        }
    }

    // Greedy-anchor suppression
    if item_size as f64 > cap * 0.55 && bin_residual != bin_capacity && post_residual > 3 {
        let stranded_frac = post_residual as f64 / cap;
        score += stranded_frac * 55.0 * (0.5 + progress);
    }

    // Bin-load balance coupling
    if fitting_bins_count > 1 && post_residual > 0 && mean_residual > 1.0 {
        let ratio = post_residual as f64 / mean_residual;
        let frac = ratio - ratio.floor();
        if frac > 0.6 && frac < 0.95 && post_residual < next_item_size.max(1) * 2 {
            score += (frac - 0.6) * 12.0 * progress;
        }
    }

    // Endgame filler-hoarding
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (progress - 0.85) * 20.0;
    }

    // Residual-halving probe
    if post_residual > 0 && bin_residual > item_size && post_residual > 4 {
        let waste = post_residual as f64;
        if (waste - (bin_residual as f64 - item_size as f64) / 2.0).abs() <= 2.0 {
            score -= 8.0 * (0.6 + progress * 0.8);
        }
    }

    // MUTATION: dead-space ratio pressure — bins whose post residual exceeds
    // half the item's own size are leaving proportionally large dead zones;
    // penalize proportionally so tighter placements win out.
    if post_residual > 0 && post_residual > item_size / 2 && bin_residual != bin_capacity {
        let ratio = post_residual as f64 / (item_size.max(1) as f64);
        score += (ratio - 0.5).min(2.0) * 8.0 * (0.3 + progress);
    }

    // MUTATION: consolidation sweep — when few bins can host the item, reward
    // placements that leave the residual closest to the next item's size,
    // effectively pre-shaping the bin for the immediate future.
    if fitting_bins_count <= 3 && next_item_size > 0 && post_residual > 0 {
        let dev = (post_residual as f64 - next_item_size as f64).abs();
        score -= (6.0 - dev.min(6.0)) * 2.5 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps below the minimum item size are wasted.
    if post_residual < 10 {
        score -= 60.0; // a fully "sealed" bin is excellent
    } else if post_residual < 25 {
        // risky gap: only usable if the next item is small enough
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 45.0; // dead space penalty
        }
    } else {
        // larger gaps: reward if the lookahead item fits into them
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Reward tight fits: fraction of the bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Squared post-residual coupling: quadratic waste penalty (Best-Fit-like but sharper).
    score += 0.15 * (post_residual as f64) * (post_residual as f64) / 10.0;

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins
    // rather than opening new ones; when few bins are open, opening is cheaper.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to existing open-bin count.
        score += 20.0 + 3.0 * pressure;
        // But if no bin fits well (large mean residual spread), opening is less bad.
        if mean_residual < 20.0 {
            score -= 15.0;
        }
    } else {
        // Existing bin: mild reward that grows with open-bin pressure.
        score -= 1.5 * pressure.sqrt();
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Late in the stream, avoid leaving many nearly-empty open bins behind.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score += 10.0 * progress * (mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        // Two-step anticipation: next item nearly fills this bin exactly
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            // small-filler chain reinforcement
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        // Perfect-chain depth bonus: bin closes with zero waste in two steps
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        // Tight chain refinement when few bins fit
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        // Two-item lookahead: remainder still larger than half the mean residual
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        // Tri-item chain probe
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        // Harmonic reuse — reward residuals near multiples of mean residual
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        // Compaction squeeze
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        // Almost-chain trap — next item fits but leaves a sliver
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        // Dead-space ratio coupling
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; leftover likely wasted
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        // Large-item stranding — big next items leave this bin stranded
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        // chain destruction guard — placing here destroys a chain
        // the next item would have consumed; strong penalty when few options.
        if next_item_size > 0
            && post_residual > 0
            && bin_residual >= next_item_size
            && fitting_bins_count <= 2
        {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        // Demand-aware new-bin gate
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        // Fresh-bin fill-forecast — only open a fresh bin when
        // the remaining stream can plausibly fill it.
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        // early-stream capacity preservation — opening fresh bins
        // early is cheap and preserves options for later large items.
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        // waste-floor compaction — when remaining demand is small
        // relative to open capacity, avoid opening underfilled fresh bins.
        let open_waste = (open_bins_count as f64) * mean_residual;
        if demand < open_waste * 0.5 && fitting_bins_count > 0 {
            score += (open_waste * 0.5 - demand).min(80.0) * (0.3 + progress * 0.7);
        }
        // mid-stream fresh-bin relief — when several open bins fit
        // and the stream is mid-flow, a fresh bin should only open if the
        // current best fit leaves a large dead residual.
        if fitting_bins_count > 0 && progress >= 0.2 && progress <= 0.8 {
            score += 12.0 * (1.0 - (post_f / cap).min(1.0));
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index — post residual near a small
    // multiple of item_size is likely exactly consumed by future similar items.
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // two-item exact-sum probe
    if next_item_size > 0 && post_residual > 0 && post_residual > next_item_size && mean_residual >= 1.0 {
        let filler = post_residual - next_item_size;
        let dev = (filler as f64 - mean_residual).abs();
        if dev <= 2.0 {
            score -= (2.0 - dev) * 10.0 * (0.5 + progress);
        }
    }

    // greedy-anchor suppression
    if item_size as f64 > cap * 0.55 && bin_residual != bin_capacity && post_residual > 3 {
        let stranded_frac = post_residual as f64 / cap;
        score += stranded_frac * 55.0 * (0.5 + progress);
    }

    // mid-band residual recycling
    if bin_residual >= 21 && bin_residual <= 35 {
        if post_residual == 0 {
            score -= 20.0 + progress * 15.0;
        } else {
            let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
            if reshaped >= 1.0 {
                let dev = (post_residual as f64 - reshaped * mean_residual).abs();
                if dev <= 3.0 {
                    score -= (3.0 - dev) * 4.0 * (0.4 + progress);
                }
            }
        }
    }

    // scarcity-tuned dead-band softening
    if post_residual >= 6 && post_residual <= 12 && next_item_size > 0 && post_residual < next_item_size {
        if (next_item_size - post_residual) as f64 <= mean_residual {
            score -= 4.0 + progress * 6.0;
        }
    }

    // dead-zone harmonic penalty — when multiple bins
    // fit, penalize residuals in the fractional dead zone of the mean
    // residual (likely to strand a sliver no future item consumes).
    if fitting_bins_count > 1 && post_residual > 0 && mean_residual > 1.0 {
        let ratio = post_residual as f64 / mean_residual;
        let frac = ratio - ratio.floor();
        if frac > 0.6 && frac < 0.95 && post_residual < next_item_size.max(1) * 2 {
            score += (frac - 0.6) * 12.0 * progress;
        }
    }

    // fine-grained dead-space ratio — sharpen the
    // baseline with a continuous dead-space term scaled by lookahead
    // usability: post residual that neither chains with the next item
    // nor matches a mean-residual quantum is penalized more strongly.
    if post_residual > 0 {
        let chains = next_item_size > 0 && next_item_size <= post_residual;
        let mut quantum = false;
        if mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 && (post_residual as f64 - k * mean_residual).abs() < 2.0 {
                quantum = true;
            }
        }
        if !chains && !quantum {
            let waste = post_residual as f64 / cap;
            score += waste * 35.0 * (0.4 + progress * 0.8);
        }
    }

    // MUTATION (gen 23): residual-halving probe — a placement that splits the
    // current residual into two roughly equal reusable halves (item centered)
    // maximizes the chance that both halves can host upcoming small items.
    if post_residual > 0 && bin_residual > item_size && post_residual > 4 {
        let waste = post_residual as f64;
        if (waste - (bin_residual as f64 - item_size as f64) / 2.0).abs() <= 2.0 {
            score -= 8.0 * (0.6 + progress * 0.8);
        }
    }

    // MUTATION (gen 23): dead-space ratio gate on new bins — opening a bin
    // whose post residual is a near-exact multiple of the mean residual is
    // cheap (it will be refilled by typical items); otherwise it is dead space.
    if bin_residual == bin_capacity && post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual) / mean_residual;
            score += dev * 10.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 23): endgame filler-hoarding — in the final stretch,
    // residuals that can still host the next item deserve a stronger
    // bonus than mid-stream, since every remaining placement counts.
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (progress - 0.85) * 20.0;
    }

    // MUTATION (gen 23): compaction lookahead pair — when the next item
    // exactly fills this bin AND the item after (approximated by mean
    // residual) would land in the freed space, reward opening-space
    // conservation: prefer placements that leave post residuals matching
    // the mean residual quantum when many bins fit.
    if fitting_bins_count >= 3 && post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 && (post_residual as f64 - k * mean_residual).abs() < 1.0 {
            score -= 6.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 23): late-stream exact-closure gate — near the end,
    // any placement that fully closes a bin must dominate; otherwise
    // residual space is lost permanently.
    if progress > 0.8 && post_residual == 0 && bin_residual != bin_capacity {
        score -= 40.0 * (progress - 0.8) * 5.0;
    }

    // MUTATION (gen 24): dual-quantum chain — placement whose post residual
    // simultaneously chains with the next item AND leaves a remainder near
    // the mean residual quantum is the ideal compaction target; reward it
    // proportionally to how many open bins compete (scarcity-aware).
    if next_item_size > 0 && post_residual > next_item_size && mean_residual > 1.0 {
        let after = post_residual - next_item_size;
        let k = (after as f64 / mean_residual).round();
        if k >= 1.0 && (after as f64 - k * mean_residual).abs() < 1.5 {
            score -= (1.5 - (after as f64 - k * mean_residual).abs()) * (4.0 + (3 - fitting_bins_count.min(3)) as f64 * 3.0) * (0.5 + progress);
        }
    }

    // MUTATION (gen 24): wasted-bin saturation guard — when many open bins
    // already fit the item, strongly discourage opening a fresh bin whose
    // post residual cannot absorb the next item (pure dead space).
    if bin_residual == bin_capacity && fitting_bins_count >= 2 && next_item_size > 0 && post_residual < next_item_size {
        score += 18.0 + (next_item_size - post_residual) as f64 * 0.35 * (0.5 + progress);
    }

    // MUTATION (gen 24): near-full bin sharpening — placements that leave
    // a residual in the 1..=5 band get an extra continuous reward scaled
    // by stream progress, tightening late-stage compaction.
    if post_residual >= 1 && post_residual <= 5 && bin_residual != bin_capacity {
        score -= (6.0 - post_residual as f64) * 2.5 * (0.3 + progress);
    }

    // MUTATION (gen 27): dead-space absorption forecast — a placement whose
    // post residual can absorb the next item AND whose remainder stays below
    // the mean residual (so it is fully consumable by typical future items)
    // is the tightest possible two-step compaction; reward it strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && (after as f64) <= mean_residual {
            score -= 10.0 * (1.0 - after as f64 / mean_residual.max(1.0)) * (0.4 + progress);
        }
    }

    // MUTATION (gen 27): fresh-bin dead-space ceiling — a new bin should only
    // open when the leftover dead space (capacity - item) is small relative
    // to what the stream can still consume; otherwise push hard against it.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let leftover = cap - item_size as f64;
        if leftover > mean_residual * 1.5 {
            score += (leftover - mean_residual * 1.5) * (0.5 + progress * 0.8);
        }
    }

    // MUTATION (gen 27): scarcity-ordered chain preference — when only a few
    // bins fit, prefer the bin whose post residual is closest to the next
    // item size above zero (minimal leftover), a continuous sharpening of
    // the exact-match bonus.
    if fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        let d = (post_residual - next_item_size) as f64;
        score -= (8.0 - d.min(8.0)) * (0.5 + progress) * (3.0 - fitting_bins_count.min(3) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: this bin's post-fit residual exactly matches the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Partial reward: next item still fits into the post-fit residual.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let tight = (post_residual - next_item_size) as f64;
        score -= 20.0 - tight * 0.35;
    }
    // Penalty: placement strands space the next item can't use.
    else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.30;
    }

    // Reward tightness relative to capacity (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 12.0;

    // Deviation from mean residual: prefer bins whose residual is close to
    // the average (keeps the pool of usable bins balanced).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.10;

    // Last-chance bin: if this is the only bin that fits, use it rather than
    // opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when the current fit is very poor
    // (large post_residual dead space) or no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 40.0;
        if poor_fit {
            score -= 10.0; // fresh bin beats wasting a big gap
        } else {
            score += 25.0; // discourage opening bins when fits are decent
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild pressure against accumulating many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: exact match of next item into post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
    }

    // Dead-space penalty relative to mean residual, scaled by progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let waste_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        let gap_dead = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        if gap_dead {
            let dead_ratio = (next_item_size - post_residual) as f64 / bin_capacity.max(1) as f64;
            score += (40.0 + progress * 30.0) * (1.0 - dead_ratio * 2.0).max(0.0);
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score += 40.0 + progress * 30.0;
        } else {
            score += (40.0 + progress * 30.0) * (1.0 - waste_frac * 1.5).max(0.0);
        }
        if progress > 0.5 && open_bins_count > 4 && mean_residual > (bin_capacity as f64) * 0.4 {
            score -= 20.0 * (progress - 0.5);
        }
    }

    // Prefer filling nearly-full bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // Small-item late-stream bonus
    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Tight-fit refinement — small residual rewards
    if post_residual == 1 || post_residual == 2 || post_residual == 3 {
        score -= 25.0;
    }

    // Penalty for residual just below next item size with multiple options
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && fitting_bins_count > 1 {
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Pairing with next item when several bins fit
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    // Balanced split reward
    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    // Chain-lookahead — reward residuals that can absorb the next
    // item AND still leave a small (<=5) usable remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after <= 5 {
            score -= 18.0 + (5 - after) as f64 * 2.0;
        }
    }

    // Waste-floor pressure
    if bin_residual == bin_capacity {
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining * 0.1;
        if post_residual as f64 > demand && progress > 0.6 {
            score += (post_residual as f64 - demand) * 0.15 * progress;
        }
    }

    // Near-exact fit sharpening
    if fitting_bins_count <= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let d = post_residual - next_item_size;
        if d <= 2 {
            score -= 10.0;
        }
    }

    // Two-item lookahead — deepen chain reward proportionally.
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
    }

    // Fragmentation guard — awkward 6..=12 band
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
        }
    }

    // Scarcity-aware new-bin suppression
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let reusable = post_residual as f64 >= mean_residual * 0.8;
        if !reusable {
            score += 8.0 + progress * 12.0;
        } else if post_residual as f64 > mean_residual * 1.6 {
            score += 4.0;
        }
    }

    // Adaptive fragmentation band — 13..=20 late in the stream.
    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Perfect-chain depth bonus
    if next_item_size > 0 && post_residual == next_item_size && post_residual > 0 {
        let scarcity = (3 - fitting_bins_count.min(3)) as f64;
        score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
    }

    // Mean-residual harmonic reuse.
    if post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev < 2.0 {
                score -= (2.0 - dev) * (1.0 + progress);
            }
        }
    }

    // Endgame consolidation — final 10% of the stream.
    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    // Demand-aware new-bin gate
    if bin_residual == bin_capacity {
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > bin_capacity as f64 * 0.5 {
            score += (post_f - bin_capacity as f64 * 0.5) * 0.25;
        }
    }

    // Tri-item chain probe
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
    }

    // Sharpened endgame exact-fit bonus
    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    // Dead-space floor sharpening — almost-chain traps
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
    }

    // Scarcity-weighted perfect fit
    if post_residual == 0 && fitting_bins_count <= 2 {
        score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Large-item pre-reservation
    if next_item_size as f64 > bin_capacity as f64 * 0.4
        && post_residual > 0
        && post_residual < next_item_size
    {
        score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
    }

    // New-bin fill-forecast
    if bin_residual == bin_capacity {
        let remaining = total_items.saturating_sub(step_index) as f64;
        let forecast = mean_residual * remaining.min(50.0);
        let cap_f = bin_capacity as f64;
        if forecast < cap_f * 0.8 {
            let shortfall = (cap_f * 0.8 - forecast) / cap_f;
            score += shortfall * 60.0 * (0.4 + progress);
        }
    }

    // Chain-continuity refinement
    if next_item_size > 0 && post_residual > next_item_size {
        let after = post_residual - next_item_size;
        if after <= 5 && next_item_size <= 15 {
            score -= (5 - after) as f64 * 3.0 * (0.5 + progress);
        }
    }

    // Bin-load balance coupling
    if fitting_bins_count > 1 && post_residual > 0 && mean_residual > 1.0 {
        let ratio = post_residual as f64 / mean_residual;
        let frac = ratio - ratio.floor();
        if frac > 0.6 && frac < 0.95 && post_residual < next_item_size.max(1) * 2 {
            score += (frac - 0.6) * 12.0 * progress;
        }
    }

    // Early-stream capacity preservation
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 6.0 * (0.2 - progress) * 50.0 * (post_residual as f64 / bin_capacity.max(1) as f64);
    }

    // Next-item stranding guard
    if next_item_size > 0
        && post_residual > 0
        && post_residual < next_item_size
        && bin_residual >= next_item_size
        && fitting_bins_count <= 2
    {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Mid-band residual recycling
    if bin_residual >= 21 && bin_residual <= 35 {
        if post_residual == 0 {
            score -= 20.0 + progress * 15.0;
        } else {
            let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
            if reshaped >= 1.0 {
                let dev = (post_residual as f64 - reshaped * mean_residual).abs();
                if dev <= 3.0 {
                    score -= (3.0 - dev) * 4.0 * (0.4 + progress);
                }
            }
        }
    }

    // Greedy-anchor suppression
    if item_size as f64 > bin_capacity as f64 * 0.55
        && bin_residual != bin_capacity
        && post_residual > 3
    {
        let stranded_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        score += stranded_frac * 55.0 * (0.5 + progress);
    }

    // Two-item exact-sum probe
    if next_item_size > 0
        && post_residual > 0
        && post_residual > next_item_size
        && mean_residual >= 1.0
    {
        let filler = post_residual - next_item_size;
        let dev = (filler as f64 - mean_residual).abs();
        if dev <= 2.0 {
            score -= (2.0 - dev) * 10.0 * (0.5 + progress);
        }
    }

    // Scarcity-tuned dead-band softening
    if post_residual >= 6 && post_residual <= 12 && next_item_size > 0 && post_residual < next_item_size {
        if (next_item_size - post_residual) as f64 <= mean_residual {
            score -= 4.0 + progress * 6.0;
        }
    }

    // Residual-halving probe
    if post_residual > 0 && bin_residual > item_size && post_residual > 4 {
        let waste = post_residual as f64;
        if (waste - (bin_residual as f64 - item_size as f64) / 2.0).abs() <= 2.0 {
            score -= 8.0 * (0.6 + progress * 0.8);
        }
    }

    // Dead-space ratio gate on new bins
    if bin_residual == bin_capacity && post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual) / mean_residual;
            score += dev * 10.0 * (0.5 + progress);
        }
    }

    // Endgame filler-hoarding
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (progress - 0.85) * 20.0;
    }

    // MUTATION (gen 27): dead-space ratio sharpening — replace the flat
    // post-residual base score with a convex (quadratic) penalty so that
    // large leftover residuals are punished disproportionately, steering
    // the packer toward placements that leave compact, reusable remainders.
    {
        let post_f = post_residual as f64;
        let cap_f = bin_capacity.max(1) as f64;
        let dead_frac = post_f / cap_f;
        if dead_frac > 0.15 {
            score += (dead_frac - 0.15) * (dead_frac - 0.15) * 120.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 27): residual-harvest lookahead — when the next item
    // would strand the current bin's residual, but a nearby open bin could
    // host the next item cleanly, penalize this placement less if the
    // stranded remainder equals a plausible small-item size (harvestable
    // later); otherwise punish the stranding more strongly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = next_item_size - post_residual;
        if gap <= 10 {
            // Small gap: the stranded space may still host a future small item.
            score -= (10 - gap) as f64 * 1.2 * (1.0 - progress);
        } else {
            score += gap as f64 * 0.35 * (0.6 + progress);
        }
    }

    // MUTATION (gen 27): new-bin carry-over coupling — when opening a fresh
    // bin, prefer that the current item's size leaves a post residual close
    // to the complement of the next item (item + next fills a bin nearly
    // exactly), enabling a tight two-item chain inside the new bin.
    if bin_residual == bin_capacity && next_item_size > 0 && item_size > 0 {
        let sum = (item_size + next_item_size) as f64;
        let cap_f = bin_capacity as f64;
        if sum <= cap_f {
            let slack = cap_f - sum;
            score -= (slack.max(0.0)).min(20.0) * 0.8 * (0.5 + progress);
        } else {
            let over = (sum - cap_f) / cap_f;
            score += over * 25.0 * (0.5 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let combo_tightness = (item_size + next_item_size) as f64 / bin_residual.max(1) as f64;
        score -= 15.0 * combo_tightness;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize leaving small dead space that the next item cannot use.
        let dead = post_residual as f64;
        score += 0.5 * dead;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Penalize bins with residuals far from the mean (outliers are awkward).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Time horizon: early in the stream, be more willing to open new bins;
    // late in the stream, squeeze into existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced early, inflated late.
        score = 10.0 + 60.0 * progress - 0.2 * mean_residual;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 5.0; // slight penalty so we prefer existing bins when possible
        }
    } else {
        score -= 10.0 * progress;
    }

    score
}

