    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let cap_f = bin_capacity.max(1) as f64;
        let unusable = post_residual as f64 / cap_f;
        let remaining = total_items.saturating_sub(step_index) as f64;
        let pressure = (1.0 - (remaining / (remaining + 20.0))).max(0.15);
