    // residual a large usable fraction of the bin deserve a bonus, scaled by
    // how many alternative bins exist (scarcity sharpens it).
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let cap_f = bin_capacity.max(1) as f64;
        let usable = post_residual as f64 / cap_f;
        let scarcity = (4 - fitting_bins_count.min(4)) as f64 * 0.25;
        score -= usable * (14.0 + scarcity * 20.0) * (0.4 + progress * 0.8);
    }

    // MUTATION (gen 27): new-bin residual sweep — when opening a bin, prefer
    // the resulting residual to be just below a common item size band so the
    // fresh bin is immediately refillable; penalize residuals in the
    // 1..=4 "just-miss" trap zone of the next item.
    if bin_residual == bin_capacity && next_item_size > 1 && post_residual > 0 {
        let miss = next_item_size.saturating_sub(post_residual);
        if miss >= 1 && miss <= 4 {
            score += (5.0 - miss as f64) * 9.0 * (0.5 + progress);
        }
    }

    score
}

