    // MUTATION (gen 28): dead-space interleave probe — when the leftover
    // after placing the next item is itself near the current item's size,
    // the bin can host a repeating size pattern; reward tight coupling of
    // (post_residual - next_item_size) to item_size to squeeze dead space.
    if next_item_size > 0 && post_residual > next_item_size && item_size > 0 {
        let after = post_residual - next_item_size;
