    if post_residual >= 3 && post_residual <= 5 && next_item_size > 0 && post_residual < next_item_size {
        score += (6.0 - post_residual as f64) * (2.0 + progress * 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly discounted by progress (late stream => tighter packing)
    let mut score = pr * (1.0 + 0.5 * progress);

    // Non-linear polynomial coupling of normalized post_residual with progress
    let t = progress;
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 40.0 * poly * (0.5 + t);

    // Reward near-perfect fills
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + t);

    // Lookahead: penalize leaving a residual that neither fits nor matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let waste = pr - nxt;
            score -= 8.0 * (1.0 - waste / cap) - 4.0 * (waste / cap);
        } else {
            score += 6.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins late in the stream when alternatives exist
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - t) + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size as f64 >= pr - item_size as f64 {
            score -= 10.0;
        }
    }

    // Mild coupling with mean residual: prefer bins below mean residual (tighter bins)
    score += 0.15 * (mean_residual - pr);

    score
}

