    // Early-stream capacity preservation
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 6.0 * (0.2 - progress) * 50.0 * (post_residual as f64 / bin_capacity.max(1) as f64);
    }

    // Next-item stranding guard
    if next_item_size > 0
        && post_residual > 0
        && post_residual < next_item_size
        && bin_residual >= next_item_size
        && fitting_bins_count <= 2
    {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Mid-band residual recycling
    if bin_residual >= 21 && bin_residual <= 35 {
        if post_residual == 0 {
            score -= 20.0 + progress * 15.0;
        } else {
            let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
            if reshaped >= 1.0 {
                let dev = (post_residual as f64 - reshaped * mean_residual).abs();
                if dev <= 3.0 {
                    score -= (3.0 - dev) * 4.0 * (0.4 + progress);
                }
            }
        }
    }

    // Greedy-anchor suppression
    if item_size as f64 > bin_capacity as f64 * 0.55
        && bin_residual != bin_capacity
        && post_residual > 3
    {
        let stranded_frac = post_residual as f64 / bin_capacity.max(1) as f64;
        score += stranded_frac * 55.0 * (0.5 + progress);
    }

    // Two-item exact-sum probe
    if next_item_size > 0
        && post_residual > 0
        && post_residual > next_item_size
        && mean_residual >= 1.0
    {
        let filler = post_residual - next_item_size;
        let dev = (filler as f64 - mean_residual).abs();
        if dev <= 2.0 {
            score -= (2.0 - dev) * 10.0 * (0.5 + progress);
        }
    }

    // Scarcity-tuned dead-band softening
    if post_residual >= 6 && post_residual <= 12 && next_item_size > 0 && post_residual < next_item_size {
        if (next_item_size - post_residual) as f64 <= mean_residual {
            score -= 4.0 + progress * 6.0;
        }
    }

    // Residual-halving probe
    if post_residual > 0 && bin_residual > item_size && post_residual > 4 {
        let waste = post_residual as f64;
        if (waste - (bin_residual as f64 - item_size as f64) / 2.0).abs() <= 2.0 {
            score -= 8.0 * (0.6 + progress * 0.8);
        }
    }

    // Dead-space ratio gate on new bins
    if bin_residual == bin_capacity && post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual) / mean_residual;
            score += dev * 10.0 * (0.5 + progress);
        }
    }

    // Endgame filler-hoarding
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (progress - 0.85) * 20.0;
    }

    // MUTATION (gen 28): dead-space utilization ratio — penalize placements
    // whose post residual is a large fraction of the ORIGINAL bin residual
    // (i.e. the item barely dented the free space), scaled by how much of
    // the bin's total capacity remains locked as dead space.
    if post_residual > 0 && bin_residual > item_size {
        let dent = item_size as f64 / bin_residual as f64;
        if dent < 0.35 {
            score += (0.35 - dent) * (bin_residual as f64 / bin_capacity.max(1) as f64) * 18.0 * (0.4 + progress);
        }
    }

    // MUTATION (gen 28): next-item exact-dent reward — when the item size
    // consumes the residual down to a small, still-usable remainder that
    // matches the mean residual closely, this is the ideal compaction.
    if post_residual > 0 && mean_residual > 1.0 && item_size > 0 {
        let ideal = (bin_residual as f64 - mean_residual).max(0.0);
        if item_size as f64 >= ideal * 0.8 && item_size as f64 <= ideal * 1.2 && ideal > 0.0 {
            score -= 9.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 28): sharper new-bin dead-space threshold — open a new
    // bin only if its expected post residual stays below the mean residual;
    // otherwise the fresh bin starts as dead space.
    if bin_residual == bin_capacity && post_residual > 0 {
        let post_f = post_residual as f64;
        if post_f > mean_residual * 1.1 {
            score += (post_f - mean_residual * 1.1) * (0.6 + progress * 1.0);
        } else if post_f <= mean_residual * 0.9 {
            score -= (mean_residual * 0.9 - post_f) * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward small, "usable" residuals using harmonic bands of 1/k fractions of capacity
    // Bands: [0..10] excellent (near-perfect fit), (10..25] good, (25..50] mediocre, >50 poor
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual <= bin_capacity / 10 {
        score -= 35.0;
    } else if post_residual <= bin_capacity / 4 {
        score -= 12.0;
    } else if post_residual <= bin_capacity / 2 {
        score += 8.0;
    } else {
        score += 25.0;
    }

    // Integer-division thresholds: residuals that form harmonic multiples
    // of common item sizes (10, 20, 25, 50) are more likely to be filled later.
    let harmonic_bonus: f64 = if post_residual % 10 == 0 {
        6.0
    } else if post_residual % 5 == 0 {
        3.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Dead-space penalty: residual too small for the smallest possible item (1..100 range)
    // but nonzero is wasted. Penalize residuals in (0, 10) that are not exactly filled well.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another residual: partial reward
            let next_left = post_residual - next_item_size;
            score -= 20.0 - (next_left as f64) * 0.3;
        } else {
            // next item won't fit here; if residual is small that's fine, if large it's wasted
            score += (frac - 0.5).max(0.0) * 20.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when existing
    // residuals are poor. Make the empty bin moderately attractive by default but
    // let well-fitting existing bins beat it.
    if bin_residual == bin_capacity {
        score = 40.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin may be useful
        }
    }

    // Mean-residual coupling: when average residual is high, prefer bins that
    // reduce dispersion (place into large-residual bins).
    if bin_residual < bin_capacity {
        let dev = mean_residual - post_residual as f64;
        score -= dev * 0.15;
    }

    // Late-stream tightening: as the stream progresses, avoid leaving medium residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * 10.0 * progress;

    // Small noise-free tie-break by exact fit quality
    score += (item_size as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        // compaction-ratio coupling
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        // two-filler horizon
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        // MUTATION (gen 28): exact-closure gate — if the next item exactly
        // empties this bin, that is the single best compaction outcome;
        // deepen the reward when the stream is still long (avoids wasting
        // a perfectly chainable residual on a mediocre alternative).
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        // complement gap rescue
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        // MUTATION (gen 28): stranding trap detection — when the gap is
        // small but no other bin can host the next item either, this bin
        // is the last hope; soften the penalty so we keep it usable.
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        // fresh-bin seeding bonus
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        // MUTATION (gen 28): fresh-bin exact-refill forecast — a new bin is
        // attractive only if its post residual (capacity - item) is likely
        // to be refilled by typical items; otherwise the residual becomes
        // permanent dead space. Compare against mean_residual multiples.
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        // MUTATION (gen 28): late-stream new-bin suppression — near the end
        // of the stream every new bin is almost guaranteed to be underfilled;
        // make opening one substantially more expensive.
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 20.0 * 0.25;
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        // tight-fit sharpening
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // MUTATION (gen 28): endgame chain-hunger — in the last 15% of the
    // stream, any residual that can host the next item gets a strong bonus
    // regardless of fit quality, since stranding residual space then is
    // an unrecoverable loss.
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 20.0 * 0.25;
    }

    // MUTATION (gen 28): dead-space ceiling — penalize placements leaving a
    // residual that is simultaneously too small for the next item and too
    // large relative to the mean residual (unfillable dead zone).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals that are too small for any future item
    // (min item size is 1, but practically small gaps are wasted) get a
    // super-linear penalty, strongest for tiny unusable slivers.
    let pr = post_residual as f64;
    if post_residual > 0 {
        let dead_threshold = 12.0;
        if pr <= dead_threshold {
            score += (dead_threshold - pr) * (dead_threshold - pr) * 2.5;
        }
    } else {
        // Perfect fit: strongly reward.
        score -= 40.0;
    }

    // Reward tight fits relative to the bin's remaining space.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Open-bin pressure: prefer packing into existing bins when many are open,
    // to avoid bin proliferation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (1.0 + progress) * 1.2;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward;
    // if post residual is smaller than next item, slightly penalize (dead end).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (i.e., fuller bins) to consolidate space.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: make opening a new bin costly unless the current bin
    // fit is terrible (handled by the above bonuses for good fits).
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        // compaction-ratio coupling
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        // two-filler horizon
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        // exact-closure gate — if the next item exactly empties this bin,
        // that is the single best compaction outcome; deepen the reward when
        // the stream is still long (avoids wasting a perfectly chainable
        // residual on a mediocre alternative).
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        // MUTATION (gen 29): two-step lookahead — if after placing the next
        // item, the remainder can exactly host the item after that (approx
        // by mean_residual multiples), reward the chain continuation. This
        // directly targets dead-space reduction via chained closures.
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        // complement gap rescue
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        // stranding trap detection — when the gap is small but no other bin
        // can host the next item either, this bin is the last hope; soften
        // the penalty so we keep it usable.
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        // fresh-bin seeding bonus
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        // fresh-bin exact-refill forecast — a new bin is attractive only if
        // its post residual (capacity - item) is likely to be refilled by
        // typical items; otherwise the residual becomes permanent dead space.
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        // late-stream new-bin suppression — near the end of the stream every
        // new bin is almost guaranteed to be underfilled; make opening one
        // substantially more expensive.
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 20.0 * 0.25;
        }
        // MUTATION (gen 29): open-bin saturation check — if the largest open
        // residual is already comfortably above the mean residual, a fresh
        // bin is redundant; penalize proportionally to that slack.
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        // tight-fit sharpening
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        // MUTATION (gen 29): item-multiple closure probe — reward placements
        // whose post residual is a near-exact multiple of the incoming item
        // size (same item types chain cleanly into the leftover space).
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // endgame chain-hunger — in the last 15% of the stream, any residual
    // that can host the next item gets a strong bonus regardless of fit
    // quality, since stranding residual space then is an unrecoverable loss.
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 20.0 * 0.25;
    }

    // dead-space ceiling — penalize placements leaving a residual that is
    // simultaneously too small for the next item and too large relative to
    // the mean residual (unfillable dead zone).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 29): waste-floor coupling — when the number of open bins
    // already exceeds what the remaining demand requires, squeeze harder on
    // existing bins (favor tight fits) and punish any residual above the
    // mean, since every unit of slack risks becoming permanent dead space.
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    score
}

