        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // MUTATION: dual-granularity compaction — reward residuals that sit on
    // mean_residual multiples and can host the next item, with tiered
    // post-fill closure rewards.
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        // dead-zone wedge: residual larger than next item but smaller than
        // two mean residuals — likely stranded after one fill.
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // MUTATION: endgame chain-hunger — squeeze residual usage hard near the
    // end of the stream.
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // MUTATION: dead-space ceiling — unfillable dead zone penalty relative
    // to the mean residual.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    // MUTATION: waste-floor coupling — squeeze harder when open bins exceed
    // remaining demand.
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        // compaction-ratio coupling
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        // two-filler horizon
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        // exact-closure gate — deepen the reward for placements that empty
        // the bin exactly, while the stream is still long.
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        // two-step lookahead — chain continuation into mean_residual multiples
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        // complement gap rescue
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        // stranding trap detection
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        // fresh-bin seeding bonus
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        // fresh-bin exact-refill forecast
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        // late-stream new-bin suppression
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 20.0 * 0.25;
        }
        // open-bin saturation check
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        // tight-fit sharpening
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        // item-multiple closure probe
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // endgame chain-hunger
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 20.0 * 0.25;
    }

    // dead-space ceiling — unfillable dead zone penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    // waste-floor coupling — squeeze harder when open bins exceed demand
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    // MUTATION (gen 31): dual-granularity compaction, refined — widen the
    // multiple tolerance, scale chain rewards by remaining stream length,
    // and add a dead-zone wedge penalty for residuals stranded between the
    // next item size and two mean residuals.
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        // dead-zone wedge: post residual larger than next item but smaller
        // than two mean residuals — likely stranded after one fill.
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // MUTATION (gen 31): chain-depth forecast — when the post residual can
    // host the next item AND the leftover after that is still >= the item
    // itself (same item chains twice), reward proportionally to remaining
    // stream length; this targets compaction of homogeneous item runs.
    if post_residual > 0 && next_item_size > 1 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= next_item_size {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 31): near-perfect fill sharpening — placements leaving
    // a residual within 2 units of the mean residual are highly reusable;
    // reward them slightly more mid-stream when compaction matters most.
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // MUTATION (gen 32): residual-variance targeting — the diagnosed weakness
    // is residual dead space. Penalize placements that leave the post
    // residual in a "gap band" between the next item and one extra item
    // worth of slack, scaled by how much stream remains to fill those gaps.
    if post_residual > 0 && next_item_size > 0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        let remaining_frac = 1.0 - progress;
        if slack > 0 && (slack as f64) < mean_residual * 0.8 && (slack as f64) > mean_residual * 0.15 {
            // leftover is too small to reliably host a mean item but too
            // large to ignore — a soft dead-space wedge, stronger mid-stream.
            score += slack as f64 * 0.9 * (0.3 + remaining_frac);
        }
        // hard wedge: leftover in 5..=9 band with no chain continuation
        if slack >= 5 && slack <= 9 && progress > 0.3 {
            score += (slack as f64 - 4.0) * 3.0 * (0.4 + progress);
        }
    }

    // MUTATION (gen 32): bin-fill homogenization — when several bins can fit
    // the item, prefer the one whose post residual best matches the mean
    // residual, keeping the fleet of open residuals uniform and chainable.
    if fitting_bins_count > 1 && post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs() / mean_residual;
        if dev < 0.5 {
            score -= (0.5 - dev) * 9.0 * (0.4 + progress * 0.8);
        }
    }

    // MUTATION (gen 32): two-item lookahead closure — if the post residual
    // can absorb the next item AND the mean residual afterwards (a likely
    // two-step emptying), reward it strongly; this converts near-closed bins
    // into fully closed ones instead of leaving 1-2 units of dead space.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && (after as f64) <= mean_residual + 2.0 && (after as f64) >= mean_residual - 2.0 {
            score -= 9.0 * (0.5 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        // compaction-ratio coupling
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        // two-filler horizon
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        // exact-closure gate — deepen the reward for placements that empty
        // the bin exactly, while the stream is still long.
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        // two-step lookahead — chain continuation into mean_residual multiples
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        // complement gap rescue
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        // stranding trap detection
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        // fresh-bin seeding bonus
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        // fresh-bin exact-refill forecast
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        // late-stream new-bin suppression
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 20.0 * 0.25;
        }
        // open-bin saturation check
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        // tight-fit sharpening
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        // item-multiple closure probe
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // endgame chain-hunger
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 20.0 * 0.25;
    }

    // dead-space ceiling — unfillable dead zone penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    // waste-floor coupling — squeeze harder when open bins exceed demand
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    // Gen-31 mutation: dual-granularity compaction, refined
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        // dead-zone wedge: post residual larger than next item but smaller
        // than two mean residuals — likely stranded after one fill.
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // Gen-31 mutation: chain-depth forecast — homogeneous item run compaction
    if post_residual > 0 && next_item_size > 1 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= next_item_size {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
    }

    // Gen-31 mutation: near-perfect fill sharpening
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // MUTATION (gen 33): dead-space ratio minimizer — quantify the fraction of
    // the bin that becomes permanently dead after this placement, and scale
    // the penalty by how much of the remaining stream could still be packed
    // into that dead zone if it were avoided. This directly targets the
    // diagnosed weakness: suboptimal residual / dead-space ratio.
    if post_residual > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let remaining_f2 = (total_items.saturating_sub(step_index)) as f64;
        let rescue_capacity = if mean_residual > 1.0 {
            (post_residual as f64 / mean_residual).floor().min(remaining_f2) * mean_residual
        } else {
            post_residual as f64
        };
        let stranded = (post_residual as f64 - rescue_capacity).max(0.0);
        if stranded > 0.0 {
            score += stranded * (0.5 + progress * 0.8);
        }
        // mild refinement: reward placements whose dead ratio shrinks below
        // the mean residual fraction of the bin — compact residual profiles.
        let mean_dead_ratio = mean_residual / cap;
        if dead_ratio < mean_dead_ratio * 0.5 && progress > 0.2 {
            score -= 3.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 33): two-item horizon probe — if the post residual can
    // host next_item_size AND item_size (the current item repeating soon),
    // reward the placement, scaled by how tight the double fit is.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= item_size && item_size > 1 {
            let tight = (after - item_size) as f64;
            score -= (3.0 - tight.min(3.0)) * 2.0 * (0.4 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    // Harmonic class of post_residual
    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        let after = post_residual - next_item_size;
        // near-exact closure sharpening
        if after <= 5 {
            score -= 18.0 + (5 - after) as f64 * 2.0;
        }
        // exact closure gate
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        // chain-depth forecast: same item chains twice
        if next_item_size > 1 && after >= next_item_size {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        // after-residual reusability: leftover close to a mean-residual multiple
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (after as f64 - k * mean_residual).abs();
                if dev <= 2.0 {
                    score -= (2.0 - dev) * 6.0 * (0.5 + progress);
                }
            }
        }
        // small-but-usable leftovers are still fine
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 6.0);
        }
    } else if next_item_size > post_residual {
        // next item won't fit here; leftover likely wasted
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        // complement gap rescue: next item almost fits
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        // stranding trap: only fitting bin nearly fits next item
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        // fresh-bin relief when no open bin is reusable
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            }
        }
        // demand forecast: suppress new bins when remaining demand is small
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        // dead-space ceiling on new-bin waste
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        // late-stream new-bin suppression
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
    } else {
        // large item placed in open bin: penalize stranding large residual
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        // item-multiple closure probe
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall: penalize bins with much more residual than mean
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins, stronger as stream progresses
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    // Residual-entropy coupling: residuals near the mean are highly reusable
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    // Two-item complement: bin_residual exactly hosts this item plus two more
    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    // Endgame: squeeze hard late in the stream
    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }
    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // MUTATION (gen 33): dual-granularity compaction with chain-aware gating —
    // reward placements whose post residual sits on a mean-residual multiple AND
    // whose after-residual either closes the bin or lands on another multiple.
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        // dead-zone wedge: residual larger than next item but smaller than
        // two mean residuals — likely stranded after one fill.
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // MUTATION (gen 33): near-mean residual sharpening mid-stream — residuals
    // within 2 units of the mean are prime targets for later small items.
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        // compaction-ratio coupling
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        // two-filler horizon
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        // exact-closure gate — deepen the reward for placements that empty
        // the bin exactly, while the stream is still long.
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        // two-step lookahead — chain continuation into mean_residual multiples
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        // complement gap rescue
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        // stranding trap detection
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        // fresh-bin seeding bonus
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        // fresh-bin exact-refill forecast
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        // late-stream new-bin suppression
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 20.0 * 0.25;
        }
        // open-bin saturation check
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        // tight-fit sharpening
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        // item-multiple closure probe
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // endgame chain-hunger
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 20.0 * 0.25;
    }

    // dead-space ceiling — unfillable dead zone penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    // waste-floor coupling — squeeze harder when open bins exceed demand
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    // MUTATION (gen 31): dual-granularity compaction, refined
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        // dead-zone wedge
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // MUTATION (gen 31): chain-depth forecast
    if post_residual > 0 && next_item_size > 1 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after >= next_item_size {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
    }

    // MUTATION (gen 31): near-perfect fill sharpening
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // MUTATION (gen 33): dead-space budget coupling — when the leftover after
    // placing the next item cannot host even half the mean residual, penalize
    // proportionally to how much capacity is being locked away, scaled by how
    // many open bins compete for the same future demand.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && (after as f64) < mean_residual * 0.5 {
            let locked = after as f64 / cap;
            let competition = (open_bins_count.min(12) as f64) / 12.0;
            score += locked * 45.0 * (0.4 + progress) * (0.5 + competition);
        }
        // complementary reward: leftovers that can host the NEXT-next demand
        // (approximated by mean residual) keep bins alive — deepen slightly
        // when the bin is one of few fitting candidates.
        if after > 0 && (after as f64) >= mean_residual * 0.9 {
            let scarcity = (4 - fitting_bins_count.min(4)) as f64 / 4.0;
            score -= (after as f64 - mean_residual * 0.9).min(6.0) * 1.8 * (0.5 + progress) * (0.5 + scarcity);
        }
    }

    // MUTATION (gen 33): threshold refinement on the wedge penalty — narrow
    // the stranded band so residuals close to the next item are no longer
    // punished, and scale the penalty with the dead fraction of the bin.
    if post_residual > next_item_size && next_item_size > 0 {
        let overshoot = (post_residual - next_item_size) as f64;
        if overshoot > mean_residual * 0.9 && overshoot < mean_residual * 2.2 {
            score += (2.5 + (post_residual as f64 / cap) * 6.0) * (0.4 + progress);
        }
    }

    // MUTATION (gen 33): open-bin pressure valve — when many bins are open
    // and the current bin would leave a large residual, discourage adding
    // more scattered dead space; prefer consolidating into fuller bins.
    if open_bins_count > 5 && post_residual > 0 {
        let spread = (post_residual as f64 / mean_residual.max(1.0)) - 1.0;
        if spread > 0.0 {
            score += spread.min(5.0) * 2.2 * (0.3 + progress);
        }
    }

    score
}

