                }
            }
        }
        // MUTATION (gen 36): exact-closure ladder — when the next item closes
        // this bin exactly and the item is a large chunk of capacity, deepen
        // the reward; this steers big items into near-full bins rather than
        // fresh ones.
        if next_item_size > 0 && post_residual == next_item_size {
            let big_frac = next_item_size as f64 / cap;
            if big_frac > 0.3 {
