        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
        // NEW: gap-rescue horizon — a near-closable gap on a large residual
        // is worth pursuing harder when plenty of stream remains.
        let remaining_g = (total_items.saturating_sub(step_index)) as f64;
        if gap >= 1 && gap <= 8 && remaining_g > 20.0 {
            score -= (8 - gap) as f64 * 2.0 * (0.4 + progress * 0.6);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        // NEW: fresh-bin misalignment gate — when the new bin's post-residual
        // does NOT chain to the next item and deviates from mean multiples,
        // opening it wastes dead space; deepen the penalty.
        if post_f > 0.0 && next_item_size > 0 && post_f < next_item_size as f64 {
            let k = (post_f / mean_residual.max(1.0)).round();
            let dev = (post_f - k * mean_residual.max(1.0)).abs();
            if dev > 1.5 {
                score += (dev - 1.5) * 9.0 * (0.5 + progress);
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // endgame chain-hunger — squeeze residual use at the end.
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // dead-space ceiling — unfillable dead zone penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    // waste-floor coupling — squeeze harder when open bins exceed demand
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    // dual-granularity compaction
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // near-perfect fill sharpening mid-stream
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // dead-space ratio governor (refined: smoother transition band around
    // the chain boundary so near-chain residuals are not over-penalized)
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            // NEW: near-miss softening — if the next item ALMOST fits,
            // halve the dead-zone penalty; the gap may close via a small item.
            let near_miss = (next_item_size - post_residual) <= 3;
            let weight = if near_miss { 0.55 } else { 1.0 };
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9) * weight;
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 60.0 * (0.5 + progress) * weight;
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
    }

    // NEW: residual-efficiency index — reward placements whose post_residual
    // can still absorb the mean filler at least twice (high reusability),
    // penalize one-shot residuals more sharply in the second half.
    if post_residual > 0 && mean_residual > 1.0 {
        let mean_fills = (post_residual as f64 / mean_residual).floor();
        if mean_fills >= 2.0 && progress > 0.3 {
            score -= (mean_fills - 1.0).min(3.0) * 2.5 * progress;
        } else if mean_fills < 1.0 && post_residual > 4 && progress > 0.5 {
            score += (4.0 - mean_fills * 4.0).max(0.0) * (0.4 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // endgame chain-hunger
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // dead-space ceiling
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    // waste-floor coupling
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    // dual-granularity compaction
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // near-perfect fill sharpening mid-stream
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // dead-space ratio governor (mutation: quadratic waste cap deepened,
    // chained-horizon reward widened)
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 50.0 * (0.45 + progress * 0.9);
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 80.0 * (0.5 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 4.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
    }

    // MUTATION: tight-bin dominance — when a bin can chain the next item
    // almost exactly, prefer it over looser bins even late in the stream.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 6.0 {
            score -= (6.0 - slack) * 2.5 * (0.6 + progress * 0.6);
        }
    }

    // MUTATION: large-item reservation — don't burn a bin whose residual
    // would be the only home for a big next item.
    if next_item_size as f64 > cap * 0.45 && bin_residual >= next_item_size && post_residual < next_item_size {
        score += 25.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        // closure ladder — exact closures consume larger leftovers,
        // extra compaction credit mid-stream.
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        // compaction-ratio coupling
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        // two-filler horizon
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        // exact-closure gate — deepen the reward for placements that empty
        // the bin exactly, while the stream is still long.
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        // two-step chain continuation into mean multiples.
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        // chain-depth forecast — same item chains twice.
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        // closure ladder — exact closures of larger leftovers get extra
        // compaction credit mid-stream.
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
        // NEW: two-item horizon — if the item AFTER next also chains into
        // the leftover, this placement is compounding; reward deeper.
        if after >= next_item_size && next_item_size > 1 {
            let twice = after - next_item_size;
            if twice as f64 <= mean_residual * 1.5 {
                score -= 5.0 * (0.5 + progress);
            }
        }
        // NEW: dead-space avoidance via chain — leftover that exactly
        // equals mean_residual kills future fragmentation.
        if after > 0 && mean_residual > 1.0 && (after as f64 - mean_residual).abs() < 0.5 {
            score -= 6.0 * (0.5 + progress);
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        // complement gap rescue
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        // gap-rescue sharpening — tiny gaps on scarce bins
        // are nearly closable; lean in further.
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        // stranding trap detection.
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
        // NEW: near-gap trap — if the gap is small and this bin's residual
        // is the ONLY thing standing between perfect packing, penalize
        // proportionally to how much of the bin would be wasted.
        if gap >= 1 && gap <= 8 {
            let waste_frac = post_residual as f64 / cap;
            score += waste_frac * (8 - gap) as f64 * 3.0 * (0.4 + progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        // fresh-bin seeding bonus
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        // fresh-bin exact-refill forecast — misaligned fresh-bin
        // post-residuals cycle poorly; penalize deviation.
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        // late-stream new-bin suppression.
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        // open-bin saturation check
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        // new-bin pressure gate — only open fresh when demand pressure
        // justifies virgin capacity.
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        // fresh-bin exact-refill relaxation — when the new bin's
        // post-residual aligns with mean-residual multiples AND existing
        // fits exist, the fresh bin will cycle cleanly; ease the opening cost.
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        // NEW: fresh-bin seeding alignment — prefer opening a new bin when
        // the incoming item leaves a residual that will exactly accept the
        // NEXT item (seed-then-chain), easing the opening cost.
        if next_item_size > 0 && post_f >= next_item_size as f64 {
            let seed_after = post_f - next_item_size as f64;
            if (seed_after - mean_residual).abs() <= 1.0 {
                score -= 9.0 * (0.4 + progress);
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        // tight-fit sharpening
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        // item-multiple closure probe.
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // endgame chain-hunger — squeeze residual use at the end.
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // dead-space ceiling — unfillable dead zone penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    // waste-floor coupling — squeeze harder when open bins exceed demand
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    // dual-granularity compaction — reward residuals that land on
    // mean-residual multiples AND chain cleanly past the next item.
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        // dead-zone wedge
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // near-perfect fill sharpening mid-stream
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // dead-space ratio governor — penalize stranded leftovers,
    // reward tight-window residuals, adjust chained leftovers by horizon.
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9);
            // stranded-waste hard cap — a leftover that cannot chain to the
            // next item NOR the mean filler AND exceeds half capacity is
            // near-certain waste; sharp quadratic penalty, deepened.
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 60.0 * (0.5 + progress);
            }
            // NEW: stranded-waste lookahead rescue — even a non-chaining
            // leftover is acceptable if the item after next could fill it;
            // approximate by checking item_size chains into the leftover.
            if item_size > 0 && post_residual >= item_size {
                let after2 = post_residual - item_size;
                if after2 as f64 <= mean_residual * 1.2 {
                    score -= 10.0 * (0.4 + progress);
                }
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
        // NEW: dead-space slope refinement — penalize leftovers whose
        // waste fraction grows faster than the chain horizon can absorb.
        if chains_next {
            let after_f = (post_residual - next_item_size) as f64;
            let absorbable = mean_residual.max(1.0) * 2.0;
            if after_f > absorbable {
                score += (after_f - absorbable) * 2.0 * (0.4 + progress * 0.8);
            }
        }
    }

    // NEW: global compaction coupling — when open bins are few relative to
    // demand, reward placements that leave mean-aligned residuals so future
    // items stack cleanly; scaled by remaining stream length.
    if post_residual > 0 && mean_residual > 1.0 && remaining_f > 20.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.0 {
                score -= 3.0 * (remaining_f / (remaining_f + 50.0)) * (0.5 + progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        // closure ladder — exact closures consume larger leftovers,
        // extra compaction credit mid-stream.
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        // compaction-ratio coupling
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        // two-filler horizon
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        // exact-closure gate — deepen the reward for placements that empty
        // the bin exactly, while the stream is still long.
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        // two-step chain continuation into mean multiples.
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        // chain-depth forecast — same item chains twice.
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        // closure ladder — exact closures of larger leftovers get extra
        // compaction credit mid-stream.
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
        // NEW: two-step exact-closure forecast — placement leaves an `after`
        // that exactly matches next_item_size, enabling a perfect chain.
        if after > 0 && after == next_item_size && progress > 0.2 {
            score -= 9.0 * (0.4 + progress);
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        // complement gap rescue
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        // gap-rescue sharpening — tiny gaps on scarce bins
        // are nearly closable; lean in further.
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        // stranding trap detection.
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        // fresh-bin seeding bonus
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        // fresh-bin exact-refill forecast — misaligned fresh-bin
        // post-residuals cycle poorly; penalize deviation.
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        // late-stream new-bin suppression.
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        // open-bin saturation check
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        // new-bin pressure gate — only open fresh when demand pressure
        // justifies virgin capacity.
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        // fresh-bin exact-refill relaxation — when the new bin's
        // post-residual aligns with mean-residual multiples AND existing
        // fits exist, the fresh bin will cycle cleanly; ease the opening cost.
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        // NEW: fresh-bin complement seeding — open a fresh bin only when
        // its post-residual can absorb the next item closely; otherwise
        // penalize slightly harder to avoid premature bin churn.
        if fitting_bins_count > 0 && next_item_size > 0 && post_f < next_item_size as f64 {
            let gap = next_item_size as f64 - post_f;
            if gap <= 8.0 {
                score -= (8.0 - gap) * 1.2 * (0.4 + progress);
            } else {
                score += 6.0 * (0.4 + progress);
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        // tight-fit sharpening
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        // item-multiple closure probe.
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // endgame chain-hunger — squeeze residual use at the end.
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // dead-space ceiling — unfillable dead zone penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    // waste-floor coupling — squeeze harder when open bins exceed demand
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    // dual-granularity compaction — reward residuals that land on
    // mean-residual multiples AND chain cleanly past the next item.
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        // dead-zone wedge
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // near-perfect fill sharpening mid-stream
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // dead-space ratio governor — penalize stranded leftovers,
    // reward tight-window residuals, adjust chained leftovers by horizon.
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9);
            // stranded-waste hard cap — a leftover that cannot chain to the
            // next item NOR the mean filler AND exceeds half capacity is
            // near-certain waste; sharp quadratic penalty, deepened.
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 60.0 * (0.5 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
        // NEW: half-capacity dead-zone trap — residuals near half capacity
        // that chain to neither the next item nor the mean filler are the
        // classic source of wasted space; add a localized penalty spike.
        if !chains_next && !chains_mean && (post_residual as i64 - (bin_capacity / 2) as i64).abs() <= 3 {
            score += 8.0 * (0.5 + progress);
        }
    }

    // NEW: scarcity-weighted tight-bin preference — when few bins fit the
    // item, tighten the effective residual weighting so the best-fitting
    // bin wins decisively rather than marginally.
    if fitting_bins_count >= 1 && bin_residual != bin_capacity {
        let tightness = 1.0 - (post_residual as f64 / cap);
        let scarcity_w = (3.0 - fitting_bins_count.min(3) as f64) / 3.0;
        score -= tightness * 4.0 * scarcity_w * (0.3 + progress * 0.7);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // endgame chain-hunger — squeeze residual use at the end.
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // dead-space ceiling — unfillable dead zone penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    // waste-floor coupling — squeeze harder when open bins exceed demand
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    // dual-granularity compaction
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // near-perfect fill sharpening mid-stream
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // dead-space ratio governor — sharpened with scarcity weighting
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            // scarcity-scaled dead-space penalty: stranded leftovers on
            // bins with few fitting alternatives are punished harder,
            // since accepting a poor fit strands capacity permanently.
            let scarcity = match fitting_bins_count {
                0 => 1.25,
                1 => 1.0,
                2 => 0.8,
                _ => 0.65,
            };
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9) * scarcity;
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 60.0 * (0.5 + progress) * scarcity;
            }
            // salvageable-wedge credit: if the stranded leftover is within a
            // small gap of the next item, the next-next stream may close it;
            // ease the penalty proportionally to the gap tightness.
            let gap = next_item_size - post_residual;
            if gap <= 8 {
                score -= (8 - gap) as f64 * 1.8 * (0.4 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
    }

    // NEW: residual-recovery horizon — a leftover that equals a plausible
    // future item size (near mean_residual or its small multiples) will
    // likely be reclaimed by the stream; reward that alignment, especially
    // when few bins can currently fit the item (compaction priority).
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > post_residual {
        let m = mean_residual;
        let near = [
            (post_residual as f64 - m).abs(),
            (post_residual as f64 - 2.0 * m).abs(),
            (post_residual as f64 - m * 0.5).abs(),
        ];
        let best = near.iter().cloned().fold(f64::INFINITY, f64::min);
        if best <= 2.0 {
            let scarcity = (4 - fitting_bins_count.min(4)) as f64;
            score -= (2.0 - best) * 4.0 * (0.4 + progress) * (0.5 + scarcity * 0.25);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: next item chains into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let after = post_residual - next_item_size;
        score -= 200.0 + after as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if after <= 5 {
            score -= 18.0 + (5 - after) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - after) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if after == 0 && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        // chain-depth forecast — same item chains repeatedly
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        let dead_frac = after as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        if after == 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
    } else {
        // Last item: just minimize post residual
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // endgame chain-hunger
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // dead-space ceiling — unfillable dead zone penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    // waste-floor coupling
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    // dual-granularity compaction
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // near-perfect fill sharpening mid-stream
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // dead-space ratio governor
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9);
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 60.0 * (0.5 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
    }

    // MUTATION: scarcity-weighted compaction — when few bins can fit the
    // item, reward placements that leave mean-residual-aligned leftovers.
    if fitting_bins_count <= 2 && post_residual > 0 && mean_residual > 1.0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (0.5 + progress);
            }
        }
    }

    // MUTATION: late-stream new-bin suppression — near the end, prefer
    // any fitting open bin over virgin capacity.
    if progress > 0.8 && bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 30.0 * (progress - 0.8) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        // closure ladder — exact closures consume larger leftovers,
        // extra compaction credit mid-stream.
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
        // gen-42: exact closures of very large leftovers are the highest-value
        // compaction events; deepen the reward proportionally.
        if bin_residual as f64 > cap * 0.45 {
            score -= 8.0 * ((bin_residual as f64 / cap) - 0.45) * (0.5 + progress);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        // compaction-ratio coupling
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        // two-filler horizon
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        // exact-closure gate — deepen the reward for placements that empty
        // the bin exactly, while the stream is still long.
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        // two-step chain continuation into mean multiples.
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        // chain-depth forecast — same item chains twice.
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        // closure ladder — exact closures of larger leftovers get extra
        // compaction credit mid-stream.
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
        // gen-42: chain-continuity probe — reward leftovers that can absorb
        // the mean filler after the next item lands (two-step viability).
        if after > 0 && mean_residual > 1.0 && after as f64 >= mean_residual * 0.9 {
            score -= 5.0 * (0.4 + progress) * ((after as f64 / mean_residual).min(2.0) / 2.0);
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        // complement gap rescue
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        // gap-rescue sharpening — tiny gaps on scarce bins
        // are nearly closable; lean in further.
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        // stranding trap detection.
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        // fresh-bin seeding bonus
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        // fresh-bin exact-refill forecast — misaligned fresh-bin
        // post-residuals cycle poorly; penalize deviation.
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        // late-stream new-bin suppression.
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        // open-bin saturation check
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        // new-bin pressure gate — only open fresh when demand pressure
        // justifies virgin capacity.
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        // fresh-bin exact-refill relaxation — when the new bin's
        // post-residual aligns with mean-residual multiples AND existing
        // fits exist, the fresh bin will cycle cleanly; ease the opening cost.
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        // gen-42: aggregate-slack gate — when total slack across open bins
        // already covers near-term demand, opening a fresh bin strands that
        // slack; penalize proportionally.
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let open_slack = (open_bins_count as f64) * mean_residual;
            let near_demand = mean_residual * remaining.min(12.0);
            if open_slack > near_demand * 1.1 {
                let over = ((open_slack - near_demand) / cap).min(1.0);
                score += over * 18.0 * (0.5 + progress);
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        // tight-fit sharpening
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        // item-multiple closure probe.
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // endgame chain-hunger — squeeze residual use at the end.
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // dead-space ceiling — unfillable dead zone penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    // waste-floor coupling — squeeze harder when open bins exceed demand
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    // dual-granularity compaction — reward residuals that land on
    // mean-residual multiples AND chain cleanly past the next item.
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        // dead-zone wedge
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // near-perfect fill sharpening mid-stream
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // dead-space ratio governor — penalize stranded leftovers,
    // reward tight-window residuals, adjust chained leftovers by horizon.
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9);
            // stranded-waste hard cap — a leftover that cannot chain to the
            // next item NOR the mean filler AND exceeds half capacity is
            // near-certain waste; sharp quadratic penalty, deepened.
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 60.0 * (0.5 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
        // gen-42: stranded-sliver decay — a non-chaining leftover that is
        // also larger than the mean filler but below 2x it is a slow leak;
        // add a mild progressive penalty so tighter fits win ties.
        if !chains_next && chains_mean && dead_ratio > 0.2 {
            score += (dead_ratio - 0.2) * 10.0 * progress;
        }
    }

    // gen-42: horizon-waste governor — when remaining stream is short,
    // any leftover that exceeds the largest plausible filler (next item or
    // mean residual) is dead weight; escalate its penalty late.
    if post_residual > 0 && next_item_size > 0 {
        let biggest = (next_item_size as f64).max(mean_residual);
        if (post_residual as f64) > biggest * 1.5 {
            let excess = (post_residual as f64 - biggest * 1.5) / cap;
            score += excess * 30.0 * (0.3 + progress * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        // closure ladder — exact closures consume larger leftovers,
        // extra compaction credit mid-stream.
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        // compaction-ratio coupling
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        // two-filler horizon
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        // exact-closure gate — deepen the reward for placements that empty
        // the bin exactly, while the stream is still long.
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        // two-step chain continuation into mean multiples.
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        // chain-depth forecast — same item chains twice.
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        // closure ladder — exact closures of larger leftovers get extra
        // compaction credit mid-stream.
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
        // NEW: chain-continuation probe — after placing, the leftover should
        // still chain to the mean filler; otherwise the lookahead was shallow.
        if after > 0 && mean_residual > 1.0 && (after as f64) < mean_residual * 0.5 {
            score += (mean_residual * 0.5 - after as f64) * 1.6 * (0.4 + progress);
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        // complement gap rescue
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        // gap-rescue sharpening — tiny gaps on scarce bins
        // are nearly closable; lean in further.
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        // stranding trap detection.
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        // fresh-bin seeding bonus
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        // fresh-bin exact-refill forecast — misaligned fresh-bin
        // post-residuals cycle poorly; penalize deviation.
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        // late-stream new-bin suppression.
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        // open-bin saturation check
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        // new-bin pressure gate — only open fresh when demand pressure
        // justifies virgin capacity.
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        // fresh-bin exact-refill relaxation — when the new bin's
        // post-residual aligns with mean-residual multiples AND existing
        // fits exist, the fresh bin will cycle cleanly; ease the opening cost.
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        // NEW: fresh-bin alignment sharpening — a fresh bin whose post-residual
        // is a tight multiple of the mean filler will cycle cleanly; reward
        // near-exact multiples harder while demand remains.
        if post_f > 0.0 && mean_residual > 1.0 && remaining > 5.0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_f - k * mean_residual).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 9.0 * (0.5 + progress);
                }
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        // tight-fit sharpening
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        // item-multiple closure probe.
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // endgame chain-hunger — squeeze residual use at the end.
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // dead-space ceiling — unfillable dead zone penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    // waste-floor coupling — squeeze harder when open bins exceed demand
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    // dual-granularity compaction — reward residuals that land on
    // mean-residual multiples AND chain cleanly past the next item.
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        // dead-zone wedge
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // near-perfect fill sharpening mid-stream
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // dead-space ratio governor — penalize stranded leftovers,
    // reward tight-window residuals, adjust chained leftovers by horizon.
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9);
            // stranded-waste hard cap — a leftover that cannot chain to the
            // next item NOR the mean filler AND exceeds half capacity is
            // near-certain waste; sharp quadratic penalty, deepened.
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 60.0 * (0.5 + progress);
            }
            // NEW: stranded leftover that also cannot absorb the item after
            // next placement is fully dead — escalate late-stream.
            if dead_ratio > 0.35 && progress > 0.5 {
                score += (dead_ratio - 0.35) * 22.0 * (progress - 0.5);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
    }

    // NEW: horizon-aware leftover valuation — a leftover that can absorb the
    // next item AND still leaves a mean-sized filler is worth extra; one that
    // leaves a sub-mean sliver after the next item is worth less.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && mean_residual > 1.0 {
        let after = post_residual - next_item_size;
        if (after as f64) >= mean_residual * 0.9 {
            score -= 4.0 * (0.4 + progress);
        } else if (after as f64) < mean_residual * 0.35 && after > 0 {
            score += (mean_residual * 0.35 - after as f64) * 2.2 * (0.4 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        // closure ladder — exact closures consume larger leftovers
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        // MUTATION: chain-depth forecast — same item chains twice+
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        // MUTATION: exact-closure gate mid-stream
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
        // MUTATION: after-filler alignment with mean residual
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        // MUTATION: after-filler alignment with current item size
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        // MUTATION: two-filler horizon
        if after > 0 && progress > 0.4 && mean_residual > 1.0 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        // MUTATION: complement gap rescue
        if gap >= 1 && gap <= 20 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        // MUTATION: tiny-gap sharpening on scarce bins
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        // MUTATION: stranding trap on the last fitting bin
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score += 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        // MUTATION: late-stream new-bin suppression
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        // MUTATION: fresh-bin exact-refill forecast
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
            if fitting_bins_count > 0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        // MUTATION: demand pressure gate for opening fresh bins
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        // MUTATION: large items seed fresh bins early
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
    } else {
        // MUTATION: greedy-anchor suppression for large items in partial bins
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        // MUTATION: tight-fit sharpening
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        // MUTATION: item-multiple closure probe
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            // MUTATION: near-chain softening within one mean residual
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // MUTATION: mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // MUTATION: endgame chain-hunger
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // MUTATION: dead-space ratio governor — penalize stranded leftovers,
    // reward tight-window residuals, adjust chained leftovers by horizon.
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9);
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 60.0 * (0.5 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
    }

    // MUTATION: dual-granularity compaction — mean-multiple residuals that
    // chain cleanly past the next item get graded bonuses.
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;
    let remaining = (total_items.saturating_sub(step_index)) as f64;

    // NEW: two-item lookahead — can item_size + next_item_size both land here?
    // This rewards bins whose residual exactly absorbs the current item plus the
    // next one, driving deeper compaction than single-item lookahead alone.
    let pair_need = item_size.saturating_add(next_item_size) as f64;
    if next_item_size > 0 && (bin_residual as f64) >= pair_need {
        let pair_after = bin_residual as f64 - pair_need;
        if pair_after <= 2.0 {
            score -= 26.0 * (0.5 + progress);
        } else if pair_after <= mean_residual.max(1.0) * 1.5 {
            score -= 12.0 * (0.4 + progress);
        } else {
            score -= (pair_after / cap).min(0.3) * 20.0;
        }
        // pair-fit exactness: residual close to an integer multiple of the pair
        let k = (bin_residual as f64 / pair_need).round();
        if k >= 1.0 {
            let dev = (bin_residual as f64 - k * pair_need).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (0.5 + progress);
            }
        }
    }

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
        // NEW: post-chain horizon — after the next item lands, how many mean
        // fillers remain? Reward deep horizons, penalize shallow stranded ones.
        if after > 0 && mean_residual > 1.0 {
            let horizon = after as f64 / mean_residual;
            if horizon >= 1.0 {
                score -= horizon.min(3.0) * 2.0 * (0.3 + progress);
            } else if horizon < 0.35 {
                score += (0.35 - horizon) * 22.0 * (0.5 + progress);
            }
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
        // NEW: gap-closure forecast — if the gap is small AND the mean residual
        // suggests future items can bridge it, this stranded residual is
        // recoverable; soften the penalty proportionally.
        if gap >= 1 && gap <= 15 && mean_residual > 1.0 {
            let bridge = mean_residual * 2.0;
            if (gap as f64) <= bridge {
                score -= (bridge - gap as f64).min(10.0) * 1.5 * (0.4 + progress);
            }
        }
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        // NEW: fresh-bin pair-capacity check — open a new bin only when the
        // current item plus the next item would nearly exhaust it, or when
        // open bins are truly saturated. Otherwise defer.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let pair_fill = pair_need / cap;
            if pair_fill < 0.55 && progress < 0.85 {
                score += (0.55 - pair_fill) * 45.0 * (0.5 + progress);
            } else if pair_fill > 0.85 {
                score -= (pair_fill - 0.85) * 50.0;
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    if open_bins_count as f64 > remaining * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9);
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 60.0 * (0.5 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.89;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity + horizon scaled)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
        // NEW: two-step horizon — after placing next item, can the bin also
        // absorb a mean-residual-sized filler? Reward clean cycle continuation.
        if after > 0 && mean_residual > 1.0 && after as f64 >= mean_residual {
            let cycles = (after as f64 / mean_residual).floor();
            score -= cycles.min(4.0) * 2.5 * (0.4 + progress);
        }
        // NEW: after-residual dead-space check — penalize leftover that
        // neither chains to mean residual nor vanishes.
        if after > 0 && mean_residual > 1.0 && (after as f64) < mean_residual * 0.8 {
            score += (mean_residual - after as f64) * 3.0 * (0.4 + progress);
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
        // NEW: gap-vs-mean rescue — a bin whose gap to the next item is
        // close to the mean filler size will close after one more item;
        // soften the penalty for keeping it alive.
        if gap > 4 && mean_residual > 1.0 {
            let dev = ((gap as f64) - mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 3.0 * (0.4 + progress);
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        // NEW: fresh-bin misfit probe — if the incoming item leaves a
        // residual that is smaller than the mean filler (likely dead),
        // and existing bins could still absorb the item, tilt away.
        if fitting_bins_count > 0 && mean_residual > 1.0 && post_f > 0.0 && post_f < mean_residual * 0.7 {
            score += (mean_residual - post_f) * 5.0 * (0.5 + progress);
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // endgame chain-hunger — squeeze residual use at the end.
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // dead-space ceiling — unfillable dead zone penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    // waste-floor coupling — squeeze harder when open bins exceed demand
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    // dual-granularity compaction
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // near-perfect fill sharpening mid-stream
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // dead-space ratio governor
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9);
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 60.0 * (0.5 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
        // NEW: stranded-sliver escalation — residual that cannot chain to
        // next item and sits just above one mean filler is the worst zone;
        // apply a targeted quadratic bump.
        if !chains_next && mean_residual > 1.0 {
            let over_mean = post_residual as f64 / mean_residual;
            if over_mean > 1.0 && over_mean < 1.6 {
                let x = 1.6 - over_mean;
                score += x * 8.0 * (0.5 + progress);
            }
        }
    }

    // NEW: bin-count governor — when open bins already exceed the
    // theoretical demand for remaining items, discourage spreading into
    // underfilled bins and push compaction of existing residuals.
    if mean_residual > 1.0 && remaining_f > 1.0 {
        let demand_bins = remaining_f / (cap / mean_residual.max(1.0));
        if open_bins_count as f64 > demand_bins * 1.3 {
            let over = open_bins_count as f64 - demand_bins * 1.3;
            if post_residual > 0 {
                score += over.min(5.0) * 2.0 * (0.4 + progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.09;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        // closure ladder — exact closures consume larger leftovers
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        // chain-depth forecast — same item chains twice+
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        // exact-closure gate mid-stream
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
        // after-filler alignment with mean residual
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        // after-filler alignment with current item size
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        // two-filler horizon
        if after > 0 && progress > 0.4 && mean_residual > 1.0 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        // MUTATION: two-step chain continuation into mean multiples
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        // MUTATION: dead-zone wedge — residual just above next item but
        // below two mean fillers risks stranding after the chain.
        if after > 0 && (after as f64) < mean_residual * 2.0 && (after as f64) > mean_residual * 0.6 {
            score += 2.5 * (0.5 + progress);
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        // complement gap rescue
        if gap >= 1 && gap <= 20 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        // tiny-gap sharpening on scarce bins
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        // stranding trap on the last fitting bin
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
        // MUTATION: bin may still hold the next item directly —
        // flag bins whose residual will become a clean post-fit.
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score += 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        // late-stream new-bin suppression
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        // fresh-bin exact-refill forecast
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
            if fitting_bins_count > 0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        // demand pressure gate for opening fresh bins
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        // large items seed fresh bins early
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        // MUTATION: open-bin saturation check — post-residual far above
        // two mean fillers signals slack that existing bins could absorb.
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        // MUTATION: early-stream fresh-bin discount — big items early
        // deserve virgin capacity; ease the opening cost slightly.
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 && progress < 0.3 {
            score -= 18.0 * (0.5 + progress);
        }
    } else {
        // greedy-anchor suppression for large items in partial bins
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        // tight-fit sharpening
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        // item-multiple closure probe
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // endgame chain-hunger
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // dead-space ratio governor — penalize stranded leftovers,
    // reward tight-window residuals, adjust chained leftovers by horizon.
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9);
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 60.0 * (0.5 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
    }

    // dual-granularity compaction — mean-multiple residuals that
    // chain cleanly past the next item get graded bonuses.
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
    }

    // MUTATION: waste-floor coupling — squeeze harder when open bins
    // exceed remaining demand; discourage leaving fat residuals.
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    // MUTATION: unfillable dead zone — residual below next item but
    // large relative to mean filler is likely permanent waste.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    // MUTATION: near-perfect fill sharpening mid-stream
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
        // NEW: after-residual dead-space coupling — the leftover after the
        // next placement is what actually matters; penalize leftovers that
        // neither chain to the mean filler nor shrink below the sliver band.
        if after > 0 {
            let chains_mean = mean_residual > 1.0 && after as f64 >= mean_residual * 0.85;
            let is_sliver = after <= 3;
            if !chains_mean && !is_sliver {
                score += (after as f64 / cap) * 26.0 * (0.4 + progress * 0.8);
            } else if chains_mean {
                let k = (after as f64 / mean_residual).round();
                let dev = (after as f64 - k * mean_residual).abs();
                score -= (2.0 - dev.min(2.0)) * 3.0 * (0.4 + progress);
            }
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        // NEW: fresh-bin alignment sharpening — opening a bin whose leftover
        // will be a near-exact mean-residual multiple is cheap; a misaligned
        // leftover strands dead space. Widen the reward window, steepen the
        // penalty side.
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_f - k * mean_residual).abs();
                if dev <= 2.0 && fitting_bins_count > 0 {
                    score -= (2.0 - dev) * 5.0 * (0.5 + progress);
                } else if dev > mean_residual * 0.45 {
                    score += (dev - mean_residual * 0.45) * 6.0 * (0.4 + progress);
                }
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // dead-space ratio governor (deepened: the diagnosed weakness is
    // stranded dead space, so raise the unchainable penalty and extend
    // the quadratic zone down to 0.45 of capacity).
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 52.0 * (0.45 + progress * 0.9);
            if dead_ratio > 0.45 {
                let x = dead_ratio - 0.45;
                score += x * x * 75.0 * (0.5 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
        // NEW: two-item horizon check — a leftover that fits neither the
        // next item nor the mean filler twice is likely stranded; penalize
        // proportionally to how far short it falls of the second filler.
        if chains_next && mean_residual > 1.0 && progress > 0.2 {
            let after = post_residual - next_item_size;
            let second_gap = (mean_residual * 2.0) - after as f64;
            if second_gap > 0.0 && second_gap < mean_residual {
                score += second_gap * 2.5 * (0.4 + progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        // closure ladder — exact closures consume larger leftovers,
        // extra compaction credit mid-stream.
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
        // NEW: exact-closure horizon bonus — emptying a bin mid-stream frees
        // its full capacity for future demand; scale by remaining stream.
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        if progress < 0.85 && remaining > 10.0 {
            score -= ((cap / 100.0) * 12.0).min(12.0) * (1.0 - progress) * (remaining / (remaining + 40.0));
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        // compaction-ratio coupling
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        // two-filler horizon
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        // exact-closure gate — deepen the reward for placements that empty
        // the bin exactly, while the stream is still long.
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        // two-step chain continuation into mean multiples.
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        // chain-depth forecast — same item chains twice.
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        // closure ladder — exact closures of larger leftovers get extra
        // compaction credit mid-stream.
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
        // NEW: two-step exact-closure probe — if the current item PLUS the
        // next item exactly empties the bin, that is a two-item closure;
        // reward it strongly, scaled by stream position.
        if after == next_item_size && next_item_size > 0 && post_residual >= 2 * next_item_size {
            score -= 10.0 * (0.5 + progress);
        }
        // NEW: dead-space elimination — when the placement leaves an 'after'
        // that is smaller than the mean filler but larger than the smallest
        // plausible item, it is likely stranded; penalize proportionally.
        if after > 0 && after < 10 && mean_residual > 1.0 && (after as f64) < mean_residual * 0.5 {
            score += (mean_residual * 0.5 - after as f64) * 3.0 * (0.5 + progress);
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        // complement gap rescue
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        // gap-rescue sharpening — tiny gaps on scarce bins
        // are nearly closable; lean in further.
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        // stranding trap detection.
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
        // NEW: near-miss gap weighting — when the gap is small relative to
        // mean filler, the bin is one small item away from a chain; soften
        // the penalty slightly so near-miss bins stay competitive.
        if mean_residual > 1.0 && (gap as f64) <= mean_residual * 0.4 {
            score -= (mean_residual * 0.4 - gap as f64) * 4.0 * (0.4 + progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        // fresh-bin seeding bonus
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        // fresh-bin exact-refill forecast — misaligned fresh-bin
        // post-residuals cycle poorly; penalize deviation.
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        // late-stream new-bin suppression.
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        // open-bin saturation check
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        // new-bin pressure gate — only open fresh when demand pressure
        // justifies virgin capacity.
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        // fresh-bin exact-refill relaxation — when the new bin's
        // post-residual aligns with mean-residual multiples AND existing
        // fits exist, the fresh bin will cycle cleanly; ease the opening cost.
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        // NEW: fresh-bin seeding alignment — a new bin whose leftover after
        // placing the current item equals cap - item_size should align with
        // the mean filler for clean cycling; penalize misalignment harder.
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).floor().max(1.0);
            let frac = post_f / mean_residual - k;
            if frac > 0.35 && frac < 0.65 {
                score += 5.0 * (0.5 + progress);
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        // tight-fit sharpening
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        // item-multiple closure probe.
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // endgame chain-hunger — squeeze residual use at the end.
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // dead-space ceiling — unfillable dead zone penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    // waste-floor coupling — squeeze harder when open bins exceed demand
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    // dual-granularity compaction — reward residuals that land on
    // mean-residual multiples AND chain cleanly past the next item.
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        // dead-zone wedge
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // near-perfect fill sharpening mid-stream
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // dead-space ratio governor — penalize stranded leftovers,
    // reward tight-window residuals, adjust chained leftovers by horizon.
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9);
            // stranded-waste hard cap — a leftover that cannot chain to the
            // next item NOR the mean filler AND exceeds half capacity is
            // near-certain waste; sharp quadratic penalty, deepened.
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 60.0 * (0.5 + progress);
            }
            // NEW: stranded-scarcity coupling — when few bins can fit the
            // item, a stranded leftover is doubly costly; sharpen further.
            if dead_ratio > 0.35 && fitting_bins_count <= 2 {
                score += (dead_ratio - 0.35) * 30.0 * (0.4 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
    }

    // NEW: horizon compaction — reward placements whose post-residual can
    // absorb the next item AND whose remainder still chains into mean
    // filler, weighted by how tight the open-bin supply is.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && mean_residual > 1.0 {
        let after = post_residual - next_item_size;
        if after as f64 >= mean_residual * 0.9 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64 / 3.0;
            score -= 5.0 * (0.4 + progress) * (0.5 + scarcity);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        // closure ladder — exact closures consume larger leftovers
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        // chain-depth forecast — same item chains twice+
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        // exact-closure gate mid-stream
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
        // after-filler alignment with mean residual
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        // after-filler alignment with current item size
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        // two-filler horizon
        if after > 0 && progress > 0.4 && mean_residual > 1.0 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        // MUTATION: two-step chain continuation into mean multiples
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        // complement gap rescue
        if gap >= 1 && gap <= 20 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        // tiny-gap sharpening on scarce bins
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        // stranding trap on the last fitting bin
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
        // MUTATION: bin can still hold next item directly — slight credit
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        // MUTATION: early-stream new-bin softening — opening bins early
        // reserves room; make it cheaper at the start.
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        // late-stream new-bin suppression
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        // fresh-bin exact-refill forecast
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
            if fitting_bins_count > 0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        // demand pressure gate for opening fresh bins
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        // large items seed fresh bins early
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        // MUTATION: fresh-bin slack governor — when a fresh bin's post
        // residual holds many mean-residual fillers, opening is justified;
        // when it holds almost none, discourage.
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        // MUTATION: large-item fresh-bin pull — big current items fit
        // cleanly into virgin capacity; prefer opening for them.
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
    } else {
        // greedy-anchor suppression for large items in partial bins
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        // tight-fit sharpening
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        // item-multiple closure probe
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // endgame chain-hunger
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // dead-space ratio governor — penalize stranded leftovers,
    // reward tight-window residuals, adjust chained leftovers by horizon.
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9);
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 60.0 * (0.5 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
        // MUTATION: unfillable-dead-zone wedge — residuals that neither
        // chain to next item nor sit within one mean filler get an extra
        // graded penalty scaled by how far above the mean they sit.
        if !chains_next && mean_residual > 1.0 {
            let over_mean = post_residual as f64 / mean_residual;
            if over_mean > 1.5 {
                score += (over_mean - 1.5).min(4.0) * 6.0 * (0.5 + progress);
            }
        }
    }

    // dual-granularity compaction — mean-multiple residuals that
    // chain cleanly past the next item get graded bonuses.
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        // MUTATION: dead-zone wedge — mid-band residuals that fail to
        // chain are mildly penalized to keep them from lingering.
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // MUTATION: near-perfect fill sharpening mid-stream — residuals
    // within 2 of mean get a small extra pull toward compaction.
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // MUTATION: waste-floor coupling — when open bins outnumber remaining
    // demand, squeeze residual usage harder to avoid stranded capacity.
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
        // NEW: two-step chain exactness — reward placements whose leftover
        // after the next item is itself exactly consumable by a second copy
        // of the next item (chain depth 2 without remainder).
        if after == next_item_size && next_item_size > 1 && after > 0 {
            score -= 9.0 * (0.5 + progress);
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
        // NEW: complement-hold — a residual just below the next item may be
        // closed by the item AFTER next (approximated by mean_residual);
        // ease the penalty when gap ≈ mean_residual.
        if gap >= 1 && gap <= 8 && mean_residual > 1.0 {
            let gdev = (gap as f64 - mean_residual).abs();
            if gdev <= 1.5 {
                score -= (1.5 - gdev) * 6.0 * (0.4 + progress);
            }
        }
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        // NEW: fresh-bin alignment demand — a new bin is only worth opening
        // when its post-residual lands close to a mean-residual multiple;
        // deepen the misalignment penalty at mid-stream where cycles matter.
        if post_f > 0.0 && mean_residual > 1.0 && progress > 0.2 && progress < 0.8 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual).abs();
            if dev > 2.0 {
                score += (dev - 2.0).min(6.0) * 5.0 * (1.0 - progress);
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // Dead-space ratio governor (refined: tightened chains_next horizon
    // threshold and deepened the stranded-waste quadratic to cut residual
    // dead space further).
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 52.0 * (0.45 + progress * 0.9);
            if dead_ratio > 0.45 {
                let x = dead_ratio - 0.45;
                score += x * x * 75.0 * (0.5 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 1.5 {
                score += (dead_ratio - 0.5) * 16.0 * (0.4 + progress);
            } else {
                score -= (horizon - 1.5).min(3.0) * 4.0 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
        // NEW: near-miss gap rescue — if the gap is small AND the mean
        // filler could bridge it, the residual is still recoverable;
        // soften the stranding penalty accordingly.
        if gap >= 1 && gap <= 10 && mean_residual > 1.0 {
            let bridge = gap as f64 - mean_residual;
            if bridge <= 0.0 {
                score -= (10.0 - gap as f64) * 1.2 * (0.4 + progress);
            } else if bridge <= 2.0 {
                score -= (2.0 - bridge) * 2.0 * (0.4 + progress);
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        // NEW: fresh-bin quality gate — a new bin's post-residual should
        // leave a workable remainder (not a sliver). Penalize fresh bins
        // whose leftover after the item falls into the dead 1..=5 band
        // unless the mean filler can chain there.
        if fitting_bins_count > 0 && post_f > 0.0 && post_f <= 5.0 {
            let chainable = next_item_size > 0 && post_residual >= next_item_size;
            let mean_chain = mean_residual > 1.0 && post_f >= mean_residual * 0.8;
            if !chainable && !mean_chain {
                score += (6.0 - post_f) * 5.0 * (0.5 + progress);
            }
        }
        // NEW: demand-saturation gate — when open-bin residual supply
        // already covers remaining demand, opening a fresh bin wastes
        // capacity; penalize proportionally to the oversupply.
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let supply = open_bins_count as f64 * mean_residual;
            if supply > demand * 1.1 {
                score += ((supply - demand * 1.1) / cap).min(1.0) * 30.0 * (0.4 + progress);
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // endgame chain-hunger — squeeze residual use at the end.
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // dead-space ceiling — unfillable dead zone penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    // waste-floor coupling — squeeze harder when open bins exceed demand
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    // dual-granularity compaction — reward residuals that land on
    // mean-residual multiples AND chain cleanly past the next item.
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // near-perfect fill sharpening mid-stream
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // dead-space ratio governor — penalize stranded leftovers,
    // reward tight-window residuals, adjust chained leftovers by horizon.
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9);
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 60.0 * (0.5 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
        // NEW: horizon-chain depth bonus — residuals that can absorb the
        // next item multiple times are prime compaction targets; scale
        // reward by how many future items fit (capped at 3).
        if chains_next && next_item_size > 1 {
            let depth = (post_residual / next_item_size).min(3);
            if depth >= 2 {
                score -= (depth as f64 - 1.0) * 4.0 * (0.5 + progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
        // NEW: two-item horizon — after placing the next item, can the item
        // after that also chain? Reward deep chains, penalize shallow ones.
        if after > 0 && after >= next_item_size && next_item_size > 0 {
            let after2 = after - next_item_size;
            if after2 == 0 {
                score -= 9.0 * (0.5 + progress);
            } else if after2 as f64 <= mean_residual * 0.5 {
                score -= 4.0 * (0.5 + progress);
            }
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        // NEW: fresh-bin horizon coupling — open a fresh bin only when the
        // post-residual can host the next item AND the remainder still
        // aligns with mean-residual multiples; otherwise suppress harder.
        if next_item_size > 0 {
            if post_f < next_item_size as f64 {
                score += (next_item_size as f64 - post_f) * 1.2 * (0.5 + progress);
            } else {
                let rem = post_f - next_item_size as f64;
                if rem > 0.0 && mean_residual > 1.0 {
                    let dev = (rem - (rem / mean_residual).round() * mean_residual).abs();
                    if dev <= 1.5 {
                        score -= 8.0 * (0.5 + progress);
                    }
                }
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // dead-space ratio governor — deepened with a demand-coupled horizon:
    // when many items remain, unchainable dead space is costlier; when the
    // stream is ending, prefer exact closures over reusable slivers.
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            let horizon_boost = 1.0 + (remaining_f / total_items.max(1) as f64).min(1.0) * 0.35;
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9) * horizon_boost;
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 60.0 * (0.5 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
        // NEW: endgame exact-closure pressure — near the stream's end,
        // residuals that cannot be closed exactly should be avoided in
        // favor of bins that can be emptied completely.
        if progress > 0.75 && chains_next && post_residual == next_item_size {
            score -= 6.0 * (progress - 0.75) * 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        // closure ladder — exact closures consume larger leftovers,
        // extra compaction credit mid-stream.
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        // compaction-ratio coupling
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        // two-filler horizon
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        // exact-closure gate — deepen the reward for placements that empty
        // the bin exactly, while the stream is still long.
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        // two-step chain continuation into mean multiples.
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        // chain-depth forecast — same item chains twice.
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        // closure ladder — exact closures of larger leftovers get extra
        // compaction credit mid-stream.
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
        // NEW: chain-shape preservation — if the leftover after this placement
        // still chains to the mean filler, deepen the reward proportionally
        // to how many mean-fillers fit inside it (residual recycling).
        if after > 0 && mean_residual > 1.0 {
            let fits = (after as f64 / mean_residual).floor();
            if fits >= 1.0 && after as f64 >= mean_residual * 0.9 {
                score -= (fits.min(4.0)) * 2.5 * (0.4 + progress * 0.6);
            }
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        // complement gap rescue
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        // gap-rescue sharpening — tiny gaps on scarce bins
        // are nearly closable; lean in further.
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        // stranding trap detection.
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        // fresh-bin seeding bonus
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        // fresh-bin exact-refill forecast — misaligned fresh-bin
        // post-residuals cycle poorly; penalize deviation.
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        // late-stream new-bin suppression.
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        // open-bin saturation check
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        // new-bin pressure gate — only open fresh when demand pressure
        // justifies virgin capacity.
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        // fresh-bin exact-refill relaxation — when the new bin's
        // post-residual aligns with mean-residual multiples AND existing
        // fits exist, the fresh bin will cycle cleanly; ease the opening cost.
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        // NEW: fresh-bin horizon match — if the item just placed leaves a
        // post-residual that exactly absorbs the next item (post == next),
        // the fresh bin is on a clean cycle; ease the opening penalty.
        if next_item_size > 0 && post_f == next_item_size as f64 && fitting_bins_count > 0 {
            score -= 9.0 * (0.5 + progress);
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        // tight-fit sharpening
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        // item-multiple closure probe.
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // endgame chain-hunger — squeeze residual use at the end.
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // dead-space ceiling — unfillable dead zone penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    // waste-floor coupling — squeeze harder when open bins exceed demand
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    // dual-granularity compaction — reward residuals that land on
    // mean-residual multiples AND chain cleanly past the next item.
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        // dead-zone wedge
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // near-perfect fill sharpening mid-stream
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // dead-space ratio governor — penalize stranded leftovers,
    // reward tight-window residuals, adjust chained leftovers by horizon.
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9);
            // stranded-waste hard cap — a leftover that cannot chain to the
            // next item NOR the mean filler AND exceeds half capacity is
            // near-certain waste; sharp quadratic penalty, deepened.
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 60.0 * (0.5 + progress);
            }
            // NEW: stranded-waste demand coupling — when remaining demand is
            // high, stranded dead space is doubly wasteful; scale the penalty
            // by how much future capacity demand is still pending.
            if dead_ratio > 0.35 && mean_residual > 1.0 {
                let pending = (mean_residual * remaining_f.min(40.0)) / cap;
                if pending > 0.5 {
                    score += (dead_ratio - 0.35) * pending.min(2.0) * 18.0 * (0.4 + progress);
                }
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
    }

    // NEW: residual-shape persistence — favor placements whose post-residual
    // matches the current bin's own residual class (mod-10), which keeps
    // future items chainable across bins of similar shape.
    if post_residual > 5 && bin_residual > post_residual {
        if post_residual % 10 == bin_residual % 10 {
            score -= 3.0 * (0.4 + progress * 0.6);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        // closure ladder — exact closures consume larger leftovers,
        // extra compaction credit mid-stream.
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        // compaction-ratio coupling
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        // two-filler horizon
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        // exact-closure gate — deepen the reward for placements that empty
        // the bin exactly, while the stream is still long.
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        // two-step chain continuation into mean multiples.
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        // chain-depth forecast — same item chains twice.
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        // closure ladder — exact closures of larger leftovers get extra
        // compaction credit mid-stream.
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
        // NEW: double-fill horizon — reward placements where the residual
        // after the next item can still absorb the mean filler exactly,
        // pushing toward fully compacted bins rather than near-closures.
        if after > 0 && mean_residual > 1.0 {
            let gap2 = after as f64 - mean_residual;
            if gap2 >= 0.0 && gap2 < 2.0 {
                score -= (2.0 - gap2) * 5.5 * (0.4 + progress);
            }
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        // complement gap rescue
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        // gap-rescue sharpening — tiny gaps on scarce bins
        // are nearly closable; lean in further.
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        // stranding trap detection.
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
        // NEW: sub-mean sliver sharpening — residuals too small for the
        // next item but close to a fraction of it may still host small
        // fillers; reward those that sit within one mean-filler of the gap.
        if mean_residual > 1.0 && gap > 1 {
            let gdev = (gap as f64 - mean_residual).abs();
            if gdev <= 2.0 {
                score -= (2.0 - gdev) * 3.0 * (0.5 + progress);
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        // fresh-bin seeding bonus
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        // fresh-bin exact-refill forecast — misaligned fresh-bin
        // post-residuals cycle poorly; penalize deviation.
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        // late-stream new-bin suppression.
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        // open-bin saturation check
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        // new-bin pressure gate — only open fresh when demand pressure
        // justifies virgin capacity.
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        // fresh-bin exact-refill relaxation — when the new bin's
        // post-residual aligns with mean-residual multiples AND existing
        // fits exist, the fresh bin will cycle cleanly; ease the opening cost.
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        // NEW: fresh-bin capacity alignment — opening a fresh bin whose
        // post-residual (cap - item) is an exact multiple of the mean
        // filler is a strong seed; deepen the ease when demand is high.
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() < 0.5 && remaining > 20.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(4.0) / 4.0);
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        // tight-fit sharpening
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        // item-multiple closure probe.
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // endgame chain-hunger — squeeze residual use at the end.
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // dead-space ceiling — unfillable dead zone penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    // waste-floor coupling — squeeze harder when open bins exceed demand
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    // dual-granularity compaction — reward residuals that land on
    // mean-residual multiples AND chain cleanly past the next item.
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        // dead-zone wedge
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // near-perfect fill sharpening mid-stream
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // dead-space ratio governor — penalize stranded leftovers,
    // reward tight-window residuals, adjust chained leftovers by horizon.
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9);
            // stranded-waste hard cap — a leftover that cannot chain to the
            // next item NOR the mean filler AND exceeds half capacity is
            // near-certain waste; sharp quadratic penalty, deepened.
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 60.0 * (0.5 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
        // NEW: near-dead micro-sliver gate — residuals that cannot chain
        // and are smaller than the smallest plausible filler are pure loss;
        // add a flat penalty scaled by how far below mean they sit.
        if !chains_next && !chains_mean && mean_residual > 1.0
            && (post_residual as f64) < mean_residual * 0.45
        {
            score += (mean_residual * 0.45 - post_residual as f64) * 8.0 * (0.5 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        // exact-closure gate — deepen reward while stream is still long
        if progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        // filler matching mean residual — leftover cycles to zero
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        // chain-depth forecast — same item chains twice
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        // two-step lookahead into mean_residual multiples
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        // exact-closure ladder — after==0 mid-stream gets a
        // compaction bonus scaled by how much residual was consumed.
        if after == 0 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
        // MUTATION: dual-filler horizon — if the leftover after the next item
        // can still absorb one mean-sized filler, reward deeper compaction.
        if after > 0 && mean_residual > 1.0 && progress > 0.3 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2 * (0.5 + progress);
            }
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        // complement gap rescue — near-miss gaps may close soon
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        // stranding trap detection on the last usable bin
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
        // gap-rescue sharpening — when the gap is tiny and the bin
        // is one of very few fits, this leftover is nearly closable; lean in.
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score += 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        // late-stream new-bin suppression
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        // fresh-bin seeding for large items mid-stream
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        // new-bin pressure gate — only open fresh when demand pressure
        // justifies virgin capacity
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        // fresh-bin exact-refill forecast — when the new bin's
        // post_residual aligns with mean-residual multiples, the fresh bin
        // will cycle cleanly; relax the opening penalty slightly.
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        // tight-fit sharpening
        if post_residual > 0 && post_residual <= 4 {
            score -= 6.0 + progress * 8.0;
        }
        // item-multiple closure probe
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // endgame chain-hunger
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // waste-floor coupling — squeeze harder when open bins exceed demand
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    // dead-space ratio governor — penalize stranded leftovers,
    // reward tight-window residuals, adjust chained leftovers by horizon.
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9);
            // MUTATION: stranded-waste hard cap — a leftover that cannot chain to
            // the next item NOR to the mean filler AND exceeds half capacity is
            // near-certain waste; sharp quadratic penalty, deepened.
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 80.0 * (0.5 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
        // MUTATION: mid-band dead-wedge — residuals that sit just above the
        // next item but below two mean fillers tend to strand one filler's
        // worth of space; penalize that narrow wedge.
        if chains_next && (post_residual as f64) < mean_residual * 2.0 && (post_residual as f64) > mean_residual * 0.6 && post_residual > next_item_size {
            score += 2.5 * (0.5 + progress);
        }
    }

    // MUTATION: dual-granularity compaction — reward residuals that land on
    // mean-residual multiples AND chain cleanly past the next item.
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item exactly
    if next_item_size > 0 && post_residual > 0 {
        if post_residual == next_item_size {
            score -= 900.0; // chain two items perfectly
        } else if post_residual >= next_item_size {
            // next item fits too; prefer leaving residual that still keeps pairing potential
            score -= (post_residual - next_item_size) as f64 * 0.8;
            // extra reward if post_residual - next_item_size is small (near-perfect chain)
            let chain_left = post_residual - next_item_size;
            if chain_left <= 10 {
                score -= 150.0;
            }
        } else {
            // next item won't fit: penalize leaving a dead gap that is smaller than next item
            score += (next_item_size - post_residual) as f64 * 0.5;
            // harsher if the gap is tiny (unusable dead space)
            if post_residual < 10 {
                score += 80.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Compare against mean residual: bins tighter than average are more valuable to fill
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.3;

    // Slight preference for filling nearly-full bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_capacity - bin_residual) as f64 * (-0.1) * (1.0 + progress);

    // New-bin candidate: make it unattractive unless nothing else fits well
    if bin_residual == bin_capacity {
        score += 400.0 + open_bins_count as f64 * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
        // NEW: two-step lookahead chain — after placing next item, can the
        // item after that also close a mean-residual gap? Reward tight
        // two-step closures, penalize dead two-step tails.
        if after > 0 && mean_residual > 1.0 {
            let two_step = after as f64 - mean_residual;
            if two_step >= 0.0 && two_step < 1.5 {
                score -= 6.0 * (0.5 + progress);
            } else if two_step < 0.0 && two_step > -2.0 {
                score += (2.0 + two_step) * 3.0 * (0.5 + progress);
            }
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        // NEW: fresh-bin alignment sharpening — when the fresh bin's
        // post-residual is exactly one mean filler, the cycle is clean;
        // deepen the ease. When it's a half-filler, penalize more.
        if post_f > 0.0 && mean_residual > 1.5 && fitting_bins_count > 0 {
            let half_f = post_f / (mean_residual * 2.0);
            if (half_f - half_f.round()).abs() < 0.05 && post_f < cap * 0.5 {
                score += 5.0 * (0.5 + progress);
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // dead-space ratio governor (refined thresholds)
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9);
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 60.0 * (0.5 + progress);
            }
            // NEW: stranded-but-tiny leftover that wastes the bin's
            // remaining room — extra quadratic nudge near full waste.
            if dead_ratio > 0.7 {
                let x = dead_ratio - 0.7;
                score += x * x * 40.0 * progress;
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 25.0 * (fit_ratio - 0.85) / 0.15;
    }

    // Penalize large dead space after placement, superlinearly.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small unusable slivers are fine if item fits snugly
    } else if post_residual >= 10 {
        score += (post_residual as f64).powf(1.25) * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item can use the post-residual, reward leaving it;
    // otherwise penalize keeping a large residual the next item can't use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            score += 4.0 + 0.1 * (next_item_size - post_residual) as f64;
        }
        // Perfect pairing: item + next item exactly fills this bin.
        if item_size + next_item_size == bin_residual {
            score -= 30.0;
        }
    }

    // New-bin candidate logic: opening a new bin is cheap early or when few bins fit,
    // expensive when open bins are already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_penalty = 8.0 * (open_bins_count as f64).ln().max(0.0);
        let frag_penalty = 3.0 * (mean_residual - post_residual as f64).abs();
        score += 10.0 + open_penalty + frag_penalty - 20.0 * progress;
        // If nothing else fits well, new bin is attractive.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Global state: prefer bins whose residual is far from mean (rebalance fragmentation).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Late in the stream, consolidate aggressively into emptier bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) shaping.
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; late, waste becomes costly (super-linear).
    let coupling = 1.0 + 2.0 * progress * progress + 1.5 * progress * norm_pr;
    score *= coupling;

    // Perfect fit reward (smooth, not hard threshold).
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_frac * fit_frac;

    // Reward bins that can also host the lookahead item (smooth overlap term).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 6.0 * (1.0 - slack) * (1.0 - progress);
    }

    // Penalize scarcity of fitting bins (last-chance bin gets bonus priority).
    if fitting_bins_count <= 1 {
        score -= 8.0 * (1.0 + progress);
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln() * progress;
    }

    // Mild penalty for diverging from mean residual (keeps bin pool balanced).
    score += 0.05 * (pr - mean_residual).abs() * (0.5 + progress);

    // New-bin candidate: neutral-ish baseline, slightly worse early, better when
    // open bins are numerous and fragmented.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) + 3.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        // compaction-ratio coupling
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        // two-filler horizon
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        // exact-closure gate — deepen the reward for placements that empty
        // the bin exactly, while the stream is still long.
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        // two-step chain continuation into mean multiples.
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        // chain-depth forecast — same item chains twice.
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
        // NEW: chain-continuation viability — after the next item lands, can
        // the leftover still absorb the mean filler? Reward clean re-chain,
        // penalize one-step-then-dead leftovers.
        if after > 0 && mean_residual > 1.0 {
            if (after as f64) >= mean_residual * 0.95 {
                score -= (after as f64).min(cap * 0.3) * 0.35 * (0.4 + progress);
            } else {
                // leftover below mean filler after this placement: dead soon
                score += (mean_residual - after as f64) * 1.8 * (0.4 + progress);
            }
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        // NEW: fresh-bin alignment gate — opening a new bin is most valuable
        // when the resulting post-residual is small enough to be re-filled by
        // the mean filler; otherwise the fresh bin strands dead space.
        if fitting_bins_count > 0 && mean_residual > 1.0 && post_f > 0.0 {
            let cycles = (post_f / mean_residual).floor();
            if cycles < 1.0 {
                // residual smaller than mean filler: mostly dead space
                score += (mean_residual - post_f) * 2.2 * (0.5 + progress);
            } else if post_f - cycles * mean_residual > mean_residual * 0.5 {
                // large non-alignable remainder
                score += (post_f - cycles * mean_residual - mean_residual * 0.5) * 1.5 * (0.5 + progress);
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    // endgame chain-hunger — squeeze residual use at the end.
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // dead-space ceiling — unfillable dead zone penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    // waste-floor coupling — squeeze harder when open bins exceed demand
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    // dual-granularity compaction
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // near-perfect fill sharpening mid-stream
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // dead-space ratio governor
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9);
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 60.0 * (0.5 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
    }

    // NEW: two-step dead-space forecast — after the next item is placed, will
    // the leftover still be chainable by the mean filler? Penalize residuals
    // that die after exactly one more placement, reward multi-cycle ones.
    if post_residual > 0 && next_item_size > 0 && post_residual >= next_item_size && mean_residual > 1.0 {
        let after = post_residual - next_item_size;
        let cycles_left = ((after as f64) / mean_residual).floor();
        if after > 0 && cycles_left < 1.0 {
            score += (mean_residual - after as f64).max(0.0) * 1.2 * (0.4 + progress);
        } else if cycles_left >= 2.0 {
            score -= (cycles_left - 1.0).min(3.0) * 2.5 * (0.4 + progress);
        }
    }

    // NEW: scarcity-aware large-item reservation — when the next item is
    // large relative to capacity and few bins can host it, avoid consuming
    // the only residual that could take it.
    if next_item_size as f64 > cap * 0.45 && fitting_bins_count <= 2
        && bin_residual >= next_item_size && post_residual < next_item_size
    {
        score += 30.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    if post_residual <= 3 && post_residual > 0 {
        score -= 25.0;
    }

    // Harmonic class of post_residual
    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        let after = post_residual - next_item_size;
        if after <= 5 {
            score -= 18.0 + (5 - after) as f64 * 2.0;
        }
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.5 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        // late-stream new-bin suppression
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            score += (post_residual as f64 / cap) * 55.0 * (0.5 + progress);
        }
        if post_residual > 0 && post_residual <= 4 {
            score -= 6.0 + progress * 8.0;
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    // dead-space ratio governor — penalize stranded leftovers
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9);
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 60.0 * (0.5 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
    }

    // endgame chain-hunger
    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // dual-granularity compaction
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                }
            }
        }
    }

    // complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 && (pair_sum - k * mean_residual).abs() < 1.5 && post_residual >= next_item_size {
            score -= (1.5 - (pair_sum - k * mean_residual).abs()) * 8.0 * (0.5 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod capacity fraction classes
    let frac = post_residual as f64 / bin_capacity as f64;
    // Quanta: how many "size-10 slots" fit in the post residual (harmonic divisibility)
    let quanta = post_residual / 10;
    let harmonic_bonus = match quanta % 10 {
        0 => -6.0,           // perfectly divisible: residual is a round number, very reusable
        1 | 9 => 4.0,        // nearly full/empty: awkward dead space
        2 | 8 => 1.0,
        5 => -3.0,           // half-class residuals pair well
        _ => 0.0,
    };
    score += harmonic_bonus;

    // Penalize small but nonzero post_residual (classic dead space), reward exact fits
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score += 12.0; // unusable sliver
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item's size class divides/aligns with post_residual
            let nq = next_item_size / 10;
            if (quanta % nq.max(1)) == 0 {
                score -= 8.0;
            } else {
                score -= 3.0;
            }
        } else {
            score += 5.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bin moderately attractive only when
    // open bins are fragmented (high mean residual spread) or late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened carelessly
        score += 30.0;
        // Fragmentation signal: mean residual large relative to typical item
        let frag = mean_residual / bin_capacity as f64;
        if frag > 0.5 && fitting_bins_count > 0 {
            score -= 20.0 * (frag - 0.5);
        }
        // Early stream: opening bins is fine; late stream: prefer consolidation
        score -= 10.0 * (1.0 - progress);
        // If many bins can fit, discourage new bin
        if fitting_bins_count > 2 {
            score += 10.0 * (fitting_bins_count as f64 - 2.0);
        }
    }

    // Prefer tighter bins generally (best-fit flavor) scaled by stream progress
    score += (bin_residual as f64 / bin_capacity as f64) * 4.0 * progress;

    // Mild penalty for spreading across too many open bins
    if open_bins_count > 8 {
        score += 0.5 * (open_bins_count as f64 - 8.0).min(6.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    // Small residual rewards
    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size - tri as u32).min(10) as f64 * 1.2;
            }
        }
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
        // NEW: two-step exact-closure forecast — placing next item here
        // leaves a residual that the item AFTER next would exactly close
        // (approximated by mean_residual as the typical filler size).
        if after > 0 && mean_residual > 1.0 {
            let k2 = (after as f64 / mean_residual).floor();
            if k2 >= 1.0 && (after as f64 - k2 * mean_residual).abs() <= 0.5 {
                score -= 5.0 * (0.4 + progress) * (k2.min(3.0) / 3.0);
            }
        }
        // NEW: after-residual must not strand below the next item's size
        // band while still large enough to be tempting — a classic
        // dead-space trap. Penalize 1..=6 leftovers that no known filler
        // (item, next, mean) can consume.
        if after >= 1 && after <= 6 {
            let consumable = after == item_size as u32
                || after == next_item_size
                || (mean_residual > 1.0 && (after as f64 - mean_residual).abs() <= 1.0);
            if !consumable {
                score += (7.0 - after as f64) * 3.5 * (0.5 + progress);
            }
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
        // NEW: near-miss coupling — if the gap is small AND the current
        // item is small enough that a companion filler could bridge it,
        // this residual is recoverable; soften the penalty.
        if gap >= 1 && gap <= 8 && item_size as f64 >= gap as f64 {
            score -= (8.0 - gap as f64) * 1.5 * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        // NEW: fresh-bin seeding alignment — opening a bin whose residual
        // (cap - item) lands within 2 of a mean_residual multiple will
        // cycle cleanly; reward that alignment when demand is real.
        if mean_residual > 1.0 && remaining > 5.0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_f - k * mean_residual).abs();
                if dev <= 2.0 {
                    score -= (2.0 - dev) * 5.0 * (0.4 + progress);
                }
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    // Fragmentation guard: awkward 6..=12 band without a chain
    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    // Residual-entropy coupling
    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    // Complement-pairing probe
    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    // Residual-reusability index
    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    // Mid-band reshaping
    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // dead-space ceiling — unfillable dead zone penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    // waste-floor coupling — squeeze harder when open bins exceed demand
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    // dual-granularity compaction
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // near-perfect fill sharpening mid-stream
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // dead-space ratio governor — sharpened: the diagnosed weakness is
    // dead space, so deepen the stranded-leftover penalty and extend the
    // quadratic hard cap down to 40% of capacity.
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 52.0 * (0.45 + progress * 0.9);
            if dead_ratio > 0.4 {
                let x = dead_ratio - 0.4;
                score += x * x * 75.0 * (0.5 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
        // NEW: chain-depth dead-space discount — residuals that can host
        // two or more consecutive next-item fills are genuinely usable;
        // reward proportionally to usable depth.
        if chains_next && next_item_size > 0 {
            let depth = (post_residual / next_item_size) as f64;
            if depth >= 2.0 {
                score -= (depth - 1.0).min(4.0) * 4.0 * (0.4 + progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (10)
    // are pure waste. Penalize them super-linearly.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits generally (small relative post residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Dead-zone coupling: if post_residual is small but nonzero and cannot
    // plausibly fit the lookahead item, penalize extra.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // If lookahead item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternatives: open a bin
        } else {
            score += 35.0 + mean_residual * 0.3; // prefer using open bins
        }
    }

    // Mild preference for bins below mean residual (keeps big gaps available).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        if after > 0 && progress > 0.4 && mean_residual > 1.0 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
        // two-step chain continuation into mean multiples
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        if gap >= 1 && gap <= 20 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
    }

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
            if fitting_bins_count > 0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        // open-bin saturation check
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    // waste-floor coupling — squeeze harder when open bins exceed demand
    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    // dual-granularity compaction
    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        // dead-zone wedge
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    // near-perfect fill sharpening mid-stream
    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // dead-space ratio governor
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 46.0 * (0.45 + progress * 0.9);
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 60.0 * (0.5 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
    }

    // dead-space ceiling — unfillable dead zone penalty
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base: prefer tight fits (low post_residual dominates).
    score += post_residual as f64 * 0.35;

    // 2-step lookahead: reward bins whose post_residual exactly or nearly
    // accommodates the next item size (perfect chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let gap = post_residual as f64 - nxt;
            // Exact match is heavily rewarded; reward decays with gap.
            score -= 30.0 * (1.0 - gap / 100.0).max(0.0);
        } else {
            // Post-residual too small for next item: mild penalty proportional
            // to how close it is (near-miss still leaves usable dead space).
            let miss = nxt - post_residual as f64;
            score += 0.15 * miss;
        }
    }

    // Relative-to-mean-residual coupling: bins with residual near the mean
    // are "average" targets; deviations penalized so we keep bin residuals
    // homogeneous, preserving flexibility for future items.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item is large relative to capacity and no good fit exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin generally...
        score += 20.0;
        // ...unless the item is large (would leave big residual in any
        // partial bin) and few fitting bins exist.
        if fill_ratio > 0.6 && fitting_bins_count <= 2 {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight preference for bins with more residual being consumed
    // proportionally (waste-rate normalization).
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity.max(1) as f64;

    // Perfect fit reward (strengthened, scarcity-weighted)
    if post_residual == 0 {
        score -= 700.0;
        if fitting_bins_count <= 2 {
            score -= (3 - fitting_bins_count.min(3)) as f64 * 25.0 * (0.5 + progress);
        }
        if bin_residual >= 21 && bin_residual <= 35 {
            score -= 20.0 + progress * 15.0;
        }
        if progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (bin_residual as f64 / cap).min(1.0);
        }
    }

    if post_residual <= 3 {
        score -= 25.0;
    }

    let class = post_residual % 10;
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else {
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        let quarter = bin_capacity / 4;
        if post_residual == half {
            score -= 40.0;
        } else if post_residual == third {
            score -= 30.0;
        } else if post_residual == quarter {
            score -= 20.0;
        }
        let dist_to_5 = class.min(10 - class);
        score += (dist_to_5 as f64) * 1.5;
        if post_residual / 10 == 0 {
            score += 25.0;
        } else if post_residual / 10 == 1 {
            score += 10.0;
        }
    }

    // Lookahead: exact match of next item into post_residual (strong, scaled)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 + (post_residual - next_item_size) as f64 * 0.5;
        if next_item_size % 10 == post_residual % 10 {
            score -= 15.0;
        }
        if post_residual - next_item_size <= 5 {
            score -= 18.0 + (5 - (post_residual - next_item_size)) as f64 * 2.0;
            if next_item_size <= 15 {
                score -= (5 - (post_residual - next_item_size)) as f64 * 3.0 * (0.5 + progress);
            }
        }
        if post_residual == next_item_size && post_residual > 0 {
            let scarcity = (3 - fitting_bins_count.min(3)) as f64;
            score -= 12.0 + scarcity * 6.0 * (0.5 + progress);
        }
        if fitting_bins_count <= 2 {
            let d = post_residual - next_item_size;
            if d <= 2 {
                score -= 10.0;
            }
        }
        let after = post_residual - next_item_size;
        if after as f64 > mean_residual * 0.5 && after > 5 {
            score -= (after as f64 - mean_residual * 0.5).min(20.0) * 0.4;
        }
        if after as f64 >= mean_residual && after > 8 && progress > 0.3 {
            score -= 6.0 + progress * 6.0;
        }
        if post_residual > 0 && mean_residual > 1.0 {
            let k = (post_residual as f64 / mean_residual).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * mean_residual).abs();
                if dev < 2.0 {
                    score -= (2.0 - dev) * (1.0 + progress);
                }
            }
        }
        if fitting_bins_count >= 2 && after > 0 && after as f64 <= mean_residual * 1.2 {
            score -= 5.0 + progress * 5.0;
        }
        if after >= 1 && after <= 3 {
            score += (4.0 - after as f64) * (2.0 + progress * 8.0);
        }
        let dead_frac = post_residual as f64 / cap;
        if dead_frac > 0.4 {
            score += (dead_frac - 0.4) * 90.0 * (0.4 + progress);
        }
        if after > 0 && mean_residual >= 1.0 {
            let dev = (after as f64 - mean_residual).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 10.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count > 1 && after > 0 {
            let dev = (after as f64 - item_size as f64).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 6.0 * (0.3 + progress);
            }
        }
        if after > 0 && progress > 0.4 {
            let tri = after as f64 - mean_residual;
            if tri >= 0.0 && tri < next_item_size as f64 {
                score -= (next_item_size as f64 - tri).min(10.0) * 1.2;
            }
        }
        if after == 0 && post_residual > 0 && progress < 0.9 {
            score -= 20.0 * (1.0 - progress);
        }
        if after > 0 && mean_residual > 1.0 {
            let k = (after as f64 / mean_residual).round();
            if k >= 1.0 && (after as f64 - k * mean_residual).abs() <= 1.0 {
                score -= 4.0 * (0.5 + progress) * (k.min(3.0) / 3.0);
            }
        }
        if after >= next_item_size && next_item_size > 1 {
            let depth = (after / next_item_size).min(3);
            score -= depth as f64 * 3.0 * (0.5 + progress);
        }
        if after == 0 && post_residual > 0 && progress > 0.1 && progress < 0.9 {
            score -= 6.0 * (1.0 - progress) * (post_residual as f64 / cap).min(1.0);
        }
        // NEW: two-item lookahead — can the residual absorb the next two items?
        if next_item_size > 1 && after >= next_item_size {
            let twice = after >= next_item_size * 2;
            if twice {
                score -= 8.0 * (0.4 + progress);
            } else {
                let tail = after - next_item_size;
                if tail <= 2 {
                    score -= 5.0 * (0.5 + progress);
                }
            }
        }
    } else if next_item_size > post_residual {
        score += (post_residual as f64) * 0.3;
        if post_residual < 20 {
            score += 20.0;
        }
        if fitting_bins_count > 1 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        let gap = next_item_size - post_residual;
        if gap <= 4 {
            score -= (4 - gap) as f64 * 3.0;
        }
        if next_item_size as f64 > cap * 0.4 {
            score += (next_item_size - post_residual) as f64 * (0.3 + progress * 0.5);
        }
        if bin_residual >= next_item_size && fitting_bins_count <= 2 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
        if gap <= 20 && gap >= 1 {
            score -= (20 - gap) as f64 * 0.8 * (0.5 + progress);
        }
        if gap >= 1 && gap <= 3 && fitting_bins_count <= 2 {
            score -= (4 - gap) as f64 * 4.0 * (0.6 + progress * 0.8);
        }
        if gap >= 1 && gap <= 6 && fitting_bins_count == 1 {
            score -= 10.0 * (1.0 - progress);
        }
        // NEW: near-miss gap that matches the mean filler — the residual is one
        // mean-item away from chaining; soften the penalty.
        if gap > 3 && mean_residual > 1.0 && gap as f64 <= mean_residual * 2.0 {
            score -= (mean_residual * 2.0 - gap as f64) * 2.0 * (0.4 + progress);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0 + progress * 30.0;
        score -= (open_bins_count as f64).min(10.0) * 1.0;
        if next_item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        let gap_useful = next_item_size > 0 && post_residual >= next_item_size;
        if !gap_useful {
            let waste = post_residual as f64 / cap;
            score -= (40.0 + progress * 30.0) * (waste * 1.5).min(1.0);
        }
        if fitting_bins_count > 0 {
            let reusable = post_residual as f64 >= mean_residual * 0.8;
            if !reusable {
                score += 8.0 + progress * 12.0;
            } else if post_residual as f64 > mean_residual * 1.6 {
                score += 4.0;
            }
        }
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        let demand = mean_residual * remaining;
        let post_f = post_residual as f64;
        if post_f > demand * 0.35 {
            let excess = post_f - demand * 0.35;
            score += excess * (0.3 + progress * 1.2);
        }
        if open_bins_count > 6 && post_f > cap * 0.5 {
            score += (post_f - cap * 0.5) * 0.25;
        }
        if item_size <= 15 && fitting_bins_count > 0 {
            score += 25.0 + progress * 25.0;
        }
        if fitting_bins_count > 0 && progress > 0.35 && progress < 0.85 {
            score += 10.0 * (1.0 - (progress - 0.35).abs() * 2.0).max(0.0);
        }
        if progress > 0.6 {
            let demand_floor = mean_residual * remaining * 0.1;
            if post_f > demand_floor {
                score += (post_f - demand_floor) * 0.15 * progress;
            }
        }
        let dead_frac = post_f / cap;
        if dead_frac > 0.35 {
            score += (dead_frac - 0.35) * 120.0 * (0.3 + progress * 1.4);
        }
        let forecast = mean_residual * remaining.min(50.0);
        if forecast < cap * 0.8 {
            let shortfall = (cap * 0.8 - forecast) / cap;
            score += shortfall * 60.0 * (0.4 + progress);
        }
        if progress < 0.2 {
            score -= 6.0 * (0.2 - progress) * 50.0 * (post_f / cap);
        }
        if item_size as f64 > cap * 0.55 && fitting_bins_count > 0 {
            score -= 18.0 * (0.5 + progress);
        }
        if item_size as f64 > cap * 0.5 && remaining > 30.0 && progress < 0.7 {
            score -= 8.0 * (1.0 - progress);
        }
        if post_f > 0.0 && mean_residual > 1.0 {
            let k = (post_f / mean_residual).round().max(1.0);
            let dev = (post_f - k * mean_residual) / mean_residual;
            score += dev * 14.0 * (0.4 + progress);
        }
        if progress > 0.85 && fitting_bins_count > 0 {
            score += 35.0 * (progress - 0.85) * 5.0;
        }
        if fitting_bins_count > 0 && mean_residual > 1.0 {
            let slack = (post_f / mean_residual) - 2.0;
            if slack > 0.0 {
                score += slack.min(4.0) * 6.0 * (0.5 + progress);
            }
        }
        if fitting_bins_count >= 2 && mean_residual > 1.0 {
            let pressure = mean_residual * remaining.min(30.0) / cap;
            if pressure > 1.2 {
                score -= 10.0 * (pressure - 1.2).min(2.0) * (0.5 + progress);
            }
        }
        if post_f > 0.0 && mean_residual > 1.0 && fitting_bins_count > 0 {
            let k = (post_f / mean_residual).round();
            if k >= 1.0 && (post_f - k * mean_residual).abs() <= 1.0 {
                score -= 6.0 * (0.5 + progress);
            }
        }
        // NEW: fresh-bin horizon check — if the new bin's post-residual cannot
        // even hold the next item, the virgin capacity is wasted; penalize.
        if next_item_size > 0 && post_f < next_item_size as f64 && fitting_bins_count > 0 {
            score += (next_item_size as f64 - post_f) * 0.5 * (0.5 + progress);
        }
    } else {
        if item_size as f64 > cap * 0.55 && post_residual > 3 {
            let stranded_frac = post_residual as f64 / cap;
            score += stranded_frac * 55.0 * (0.5 + progress);
        }
        if post_residual > 0 && post_residual <= 4 && fitting_bins_count >= 1 {
            score -= 6.0 + progress * 8.0;
        }
        if post_residual > 0 && item_size > 1 {
            let k = (post_residual as f64 / item_size as f64).round();
            if k >= 1.0 {
                let dev = (post_residual as f64 - k * item_size as f64).abs();
                if dev <= 1.0 {
                    score -= (1.0 - dev) * 7.0 * (0.4 + progress);
                }
            }
        }
    }

    // Prefer tighter bins overall
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * (0.4 + progress * 0.3);
    }

    // Prefer filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.3 * (0.5 + progress);

    if progress > 0.7 && item_size < 20 && post_residual > 30 {
        score += 15.0;
    }

    if post_residual >= 6 && post_residual <= 12 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok {
            score += (6.0 + progress * 14.0) * (1.0 - (post_residual as f64 - 6.0) / 6.0);
            if next_item_size > 0 && (next_item_size - post_residual) as f64 <= mean_residual {
                score -= 4.0 + progress * 6.0;
            }
        }
    }

    if post_residual >= 13 && post_residual <= 20 && progress > 0.55 {
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        if !chain_ok && fitting_bins_count > 1 {
            let band_frac = (post_residual as f64 - 13.0) / 7.0;
            score += (4.0 + progress * 10.0) * (1.0 - band_frac * 0.7);
        }
    }

    let res_dev = (post_residual as f64 - mean_residual).abs();
    if res_dev < mean_residual * 0.15 && post_residual > 0 {
        score -= 10.0 + progress * 10.0;
    }

    if post_residual * 2 + item_size == bin_residual && post_residual >= 4 {
        score -= 12.0;
    }

    if progress > 0.9 && post_residual > 25 {
        score += (post_residual as f64 - 25.0) * 0.5;
    }

    if progress > 0.95 && post_residual >= 1 && post_residual <= 4 {
        score -= (4.0 - post_residual as f64) * 4.0 * (progress - 0.95) * 20.0;
    }

    if progress > 0.6 && fitting_bins_count <= 3 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (progress - 0.6) * 5.0;
    }

    if next_item_size > 0 && post_residual > 0 && mean_residual > 1.0 {
        let pair_sum = (post_residual + next_item_size) as f64;
        let k = (pair_sum / mean_residual).round();
        if k >= 1.0 {
            let dev = (pair_sum - k * mean_residual).abs();
            if dev < 1.5 && post_residual >= next_item_size {
                score -= (1.5 - dev) * 8.0 * (0.5 + progress);
            }
        }
    }

    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.2;
    }

    if post_residual > 0 && item_size > 0 {
        let k = (post_residual as f64 / item_size as f64).round();
        if k >= 1.0 && k <= 3.0 {
            let dev = (post_residual as f64 - k * item_size as f64).abs();
            if dev <= 2.0 {
                score -= (2.0 - dev) * 5.0 * (1.0 - progress) * (0.5 + progress);
            }
        }
    }

    if bin_residual >= 21 && bin_residual <= 35 && post_residual > 0 {
        let reshaped = (post_residual as f64 / mean_residual.max(1.0)).round();
        if reshaped >= 1.0 {
            let dev = (post_residual as f64 - reshaped * mean_residual).abs();
            if dev <= 3.0 {
                score -= (3.0 - dev) * 4.0 * (0.4 + progress);
            }
        }
    }

    if progress > 0.85 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (progress - 0.85) * 5.0;
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let unfillable = post_residual as f64 / mean_residual.max(1.0);
        if unfillable > 1.5 {
            score += (unfillable - 1.5) * 6.0 * (0.5 + progress);
        }
    }

    let remaining_f = (total_items.saturating_sub(step_index)) as f64;
    if open_bins_count as f64 > remaining_f * 0.5 && mean_residual > 1.0 {
        let over = post_residual as f64 / mean_residual;
        if over > 1.0 {
            score += (over - 1.0).min(6.0) * 3.5 * (0.6 + progress);
        }
    }

    if post_residual > 0 && mean_residual > 1.0 && next_item_size > 0 {
        let k = (post_residual as f64 / mean_residual).round();
        if k >= 1.0 {
            let dev = (post_residual as f64 - k * mean_residual).abs();
            if dev <= 1.5 && post_residual >= next_item_size {
                let after = post_residual - next_item_size;
                if after == 0 {
                    score -= 11.0 * (0.5 + progress);
                } else if (after as f64 - mean_residual).abs() <= 2.0 {
                    score -= 7.0 * (0.5 + progress);
                } else if (after as f64 / mean_residual).round() >= 1.0 {
                    score -= 3.0 * (0.4 + progress);
                }
            }
        }
        if post_residual > next_item_size
            && (post_residual as f64) < mean_residual * 2.0
            && (post_residual as f64) > mean_residual * 0.6
        {
            score += 2.5 * (0.5 + progress);
        }
    }

    if post_residual > 0 && mean_residual > 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev <= 2.0 && progress > 0.25 && progress < 0.9 {
            score -= (2.0 - dev) * 2.0 * (1.0 - (progress - 0.25).abs().max(0.25));
        }
    }

    // dead-space ratio governor — sharpened: dead residuals that can chain to
    // neither the next item nor the mean filler are penalized harder, while
    // mean-chainable residuals get a mild compaction credit.
    if post_residual > 0 && next_item_size > 0 {
        let dead_ratio = post_residual as f64 / cap;
        let chains_next = post_residual >= next_item_size;
        let chains_mean = mean_residual > 1.0 && post_residual as f64 >= mean_residual * 0.9;
        if !chains_next && !chains_mean {
            score += dead_ratio * 52.0 * (0.45 + progress * 0.9);
            if dead_ratio > 0.5 {
                let x = dead_ratio - 0.5;
                score += x * x * 70.0 * (0.5 + progress);
            }
        } else if chains_next && dead_ratio > 0.5 {
            let horizon = (post_residual as f64 / mean_residual.max(1.0)).floor();
            if horizon < 2.0 {
                score += (dead_ratio - 0.5) * 14.0 * (0.4 + progress);
            } else {
                score -= (horizon - 2.0).min(3.0) * 3.5 * (0.5 + progress);
            }
        }
        if post_residual as f64 <= mean_residual.max(1.0) {
            score -= 9.0 * (0.5 + progress) * (1.0 - dead_ratio);
        }
        // NEW: mid-band dead residual that the item after next could close —
        // mild credit when the residual sits within one mean filler of the
        // next item's complement.
        if !chains_next && chains_mean && post_residual as f64 + mean_residual >= next_item_size as f64 {
            score -= 4.0 * (0.4 + progress);
        }
    }

    score
}
